from (values
(380073,42231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Muffins sehen goldbraun aus, also ... sie fertig zum Rausholen sein. Echt geniale Detektivarbeit.'::text,'müssen'::text,'können nicht'::text,'dürfen nicht'::text,'Die Muffins sehen goldbraun aus, also müssen sie fertig zum Rausholen sein. Echt geniale Detektivarbeit.'::text),
(380077,42231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мафіни виглядають золотистими, тож вони ... бути готові, щоб їх дістати. Справді геніальна детективна робота.'::text,'мають'::text,'не можуть'::text,'не повинні'::text,'Мафіни виглядають золотистими, тож вони мають бути готові, щоб їх дістати. Справді геніальна детективна робота.'::text),
(380076,42231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los muffins se ven dorados, así que ... estar listos para sacarlos. Un trabajo de detective realmente genial.'::text,'deben de'::text,'no pueden'::text,'no deben'::text,'Los muffins se ven dorados, así que deben de estar listos para sacarlos. Un trabajo de detective realmente genial.'::text),
(380075,42231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les muffins sont bien dorés, donc ils ... être prêts à sortir. Un vrai travail de détective de génie.'::text,'doivent'::text,'ne peuvent pas'::text,'ne doivent pas'::text,'Les muffins sont bien dorés, donc ils doivent être prêts à sortir. Un vrai travail de détective de génie.'::text),
(380078,42231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muffinler altın rengi görünüyor, yani çıkarılmaya hazır ..., gerçekten dâhiyane bir dedektiflik işi.'::text,'olmalılar'::text,'olamazlar'::text,'olmamalılar'::text,'Muffinler altın rengi görünüyor, yani çıkarılmaya hazır olmalılar, gerçekten dâhiyane bir dedektiflik işi.'::text),
(380079,42231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A muffinok aranybarnának tűnnek, szóval ... már kivehetők. Igazán zseniális nyomozómunka.'::text,'biztos, hogy'::text,'nem lehet, hogy'::text,'nem szabad, hogy'::text,'A muffinok aranybarnának tűnnek, szóval biztos, hogy már kivehetők. Igazán zseniális nyomozómunka.'::text),
(380082,42232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Bäcker, ... die Brote mit dieser langen Schaufel rausholt, ist echt eine Legende.'::text,'der'::text,'welcher'::text,'dessen'::text,'Bro, der Bäcker, der die Brote mit dieser langen Schaufel rausholt, ist echt eine Legende.'::text),
(380086,42232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, пекар, ... дістає хлібини тією довгою лопатою, — реально легенда.'::text,'який'::text,'котрий'::text,'чий'::text,'Бро, пекар, який дістає хлібини тією довгою лопатою, — реально легенда.'::text),
(380085,42232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el panadero ... saca los panes con esa pala larga es una leyenda, la verdad.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Bro, el panadero que saca los panes con esa pala larga es una leyenda, la verdad.'::text),
(380084,42232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le boulanger ... sort les pains avec cette longue pelle est une vraie légende, sans mentir.'::text,'qui'::text,'lequel'::text,'dont'::text,'Frère, le boulanger qui sort les pains avec cette longue pelle est une vraie légende, sans mentir.'::text),
(380087,42232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, somunları o uzun kürekle ... fırıncı resmen efsane.'::text,'çıkaran'::text,'çıkaran'::text,'çıkardığı'::text,'Kanka, somunları o uzun kürekle çıkaran fırıncı resmen efsane.'::text),
(380088,42232,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a pék, ... azzal a hosszú lapáttal szedi ki a cipókat, simán egy legenda.'::text,'aki'::text,'amelyik'::text,'akinek a'::text,'Tesó, a pék, aki azzal a hosszú lapáttal szedi ki a cipókat, simán egy legenda.'::text),
(380100,42234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem neuen Ofen holte der Bäcker ... 200 Brote am Tag heraus, unter dem Ziel.'::text,'früher'::text,'gewohnheitsmäßig'::text,'früher'::text,'Vor dem neuen Ofen holte der Bäcker früher 200 Brote am Tag heraus, unter dem Ziel.'::text),
(380104,42234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До нової печі пекар ... виймав 200 хлібин на день, нижче плану.'::text,'раніше'::text,'звично'::text,'раніше'::text,'До нової печі пекар раніше виймав 200 хлібин на день, нижче плану.'::text),
(380103,42234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del horno nuevo, el panadero ... sacar 200 panes al día, por debajo del objetivo.'::text,'solía'::text,'estaba acostumbrado a'::text,'solía'::text,'Antes del horno nuevo, el panadero solía sacar 200 panes al día, por debajo del objetivo.'::text),
(380102,42234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le nouveau four, le boulanger ... sortir 200 pains par jour, sous l''objectif.'::text,'avait l''habitude de'::text,'était habitué à'::text,'avait l''habitude de'::text,'Avant le nouveau four, le boulanger avait l''habitude de sortir 200 pains par jour, sous l''objectif.'::text),
(380105,42234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni fırından önce fırıncı günde 200 somun ..., hedefin altında.'::text,'çıkarırdı'::text,'çıkarmaya alışkındı'::text,'çıkarırdı'::text,'Yeni fırından önce fırıncı günde 200 somun çıkarırdı, hedefin altında.'::text),
(380106,42234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új kemence előtt a pék napi 200 cipót ... kiszedni, a cél alatt.'::text,'szokott'::text,'hozzá volt szokva'::text,'szokott'::text,'Az új kemence előtt a pék napi 200 cipót szokott kiszedni, a cél alatt.'::text),
(380109,42235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er vermeidet es, den Truthahn zu früh ..., denn zu früh ist, bevor er fertig ist.'::text,'rauszuholen'::text,'rauszuholen'::text,'rausholen'::text,'Er vermeidet es, den Truthahn zu früh rauszuholen, denn zu früh ist, bevor er fertig ist.'::text),
(380113,42235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уникає того, щоб ... індичку зарано, бо зарано — це до того, як вона готова.'::text,'виймати'::text,'виймати'::text,'виймати'::text,'Він уникає того, щоб виймати індичку зарано, бо зарано — це до того, як вона готова.'::text),
(380112,42235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evita ... el pavo demasiado pronto, porque pronto es antes de que esté listo.'::text,'sacar'::text,'sacar'::text,'sacar'::text,'Evita sacar el pavo demasiado pronto, porque pronto es antes de que esté listo.'::text),
(380111,42235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il évite de ... la dinde trop tôt, parce que tôt, c''est avant qu''elle soit prête.'::text,'sortir'::text,'sortir'::text,'sortir'::text,'Il évite de sortir la dinde trop tôt, parce que tôt, c''est avant qu''elle soit prête.'::text),
(380114,42235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hindiyi çok erken ... kaçınıyor, çünkü erken, hazır olmadan önce demek.'::text,'çıkarmaktan'::text,'çıkarmaktan'::text,'çıkarmaktan'::text,'Hindiyi çok erken çıkarmaktan kaçınıyor, çünkü erken, hazır olmadan önce demek.'::text),
(380115,42235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kerüli, hogy túl korán ... a pulykát, mert a korán az, amikor még nincs kész.'::text,'kivegye'::text,'kivegye'::text,'kivegye'::text,'Kerüli, hogy túl korán kivegye a pulykát, mert a korán az, amikor még nincs kész.'::text),
(380118,42236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat die Muffins aus dem Ofen geholt, ...?'::text,'nicht wahr?'::text,'nicht wahr?'::text,'oder?'::text,'Sie hat die Muffins aus dem Ofen geholt, nicht wahr?'::text),
(380122,42236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дістала мафіни з духовки, ...?'::text,'чи не так?'::text,'чи не так?'::text,'так?'::text,'Вона дістала мафіни з духовки, чи не так?'::text),
(380121,42236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sacó los muffins del horno, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿sí?'::text,'Sacó los muffins del horno, ¿verdad?'::text),
(380120,42236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a sorti les muffins du four, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'hein ?'::text,'Elle a sorti les muffins du four, n''est-ce pas ?'::text),
(380123,42236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muffinleri fırından çıkardı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Muffinleri fırından çıkardı, değil mi?'::text),
(380124,42236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kivette a muffinokat a sütőből, ...?'::text,'nem?'::text,'nem?'::text,'igen?'::text,'Kivette a muffinokat a sütőből, nem?'::text),
(380127,42237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau hat ihr Blech aus dem Ofen geholt, und ...'::text,'der Mann auch.'::text,'der Mann auch.'::text,'der Mann nicht.'::text,'Die Frau hat ihr Blech aus dem Ofen geholt, und der Mann auch.'::text),
(380131,42237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка дістала своє деко з духовки, і ...'::text,'чоловік теж.'::text,'чоловік теж.'::text,'чоловік ні.'::text,'Жінка дістала своє деко з духовки, і чоловік теж.'::text),
(380130,42237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer sacó su bandeja del horno, y ...'::text,'el hombre también.'::text,'el hombre también.'::text,'el hombre tampoco.'::text,'La mujer sacó su bandeja del horno, y el hombre también.'::text),
(380129,42237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a sorti sa plaque du four, et ...'::text,'l''homme aussi.'::text,'l''homme aussi.'::text,'l''homme non plus.'::text,'La femme a sorti sa plaque du four, et l''homme aussi.'::text),
(380132,42237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın tepsisini fırından çıkardı ve ...'::text,'adam da öyle.'::text,'adam da öyle.'::text,'adam da çıkarmadı.'::text,'Kadın tepsisini fırından çıkardı ve adam da öyle.'::text),
(380133,42237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő kivette a tepsijét a sütőből, és ...'::text,'a férfi is.'::text,'a férfi is.'::text,'a férfi sem.'::text,'A nő kivette a tepsijét a sütőből, és a férfi is.'::text),
(380136,42238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Truthahn ... stundenlang im Ofen, bevor der Mann die Form herausnahm.'::text,'briet schon'::text,'brät schon'::text,'briet'::text,'Der Truthahn briet schon stundenlang im Ofen, bevor der Mann die Form herausnahm.'::text),
(380140,42238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Індичка ... в духовці годинами, перш ніж чоловік дістав форму.'::text,'запікалася'::text,'запікається'::text,'запікалася'::text,'Індичка запікалася в духовці годинами, перш ніж чоловік дістав форму.'::text),
(380139,42238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pavo ... en el horno durante horas antes de que el hombre sacara la bandeja.'::text,'llevaba asándose'::text,'lleva asándose'::text,'se estaba asando'::text,'El pavo llevaba asándose en el horno durante horas antes de que el hombre sacara la bandeja.'::text),
(380138,42238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dinde ... au four depuis des heures avant que l''homme sorte le plat.'::text,'rôtissait'::text,'rôtit'::text,'rôtissait'::text,'La dinde rôtissait au four depuis des heures avant que l''homme sorte le plat.'::text),
(380141,42238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam tepsiyi çıkarmadan önce hindi saatlerdir fırında ...'::text,'kızarıyordu'::text,'kızarıyor'::text,'kızarıyordu'::text,'Adam tepsiyi çıkarmadan önce hindi saatlerdir fırında kızarıyordu.'::text),
(380142,42238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pulyka órák óta ... a sütőben, mielőtt a férfi kivette a tepsit.'::text,'sült'::text,'sül'::text,'sült'::text,'A pulyka órák óta sült a sütőben, mielőtt a férfi kivette a tepsit.'::text),
(380145,42239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bis ich da bin, wirst du alle sechs Brote aus dem Ofen ... Beeindruckend.'::text,'geholt haben'::text,'holen'::text,'geholt'::text,'Ehrlich, bis ich da bin, wirst du alle sechs Brote aus dem Ofen geholt haben Beeindruckend.'::text),
(380149,42239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки я туди дійду, ти вже ... всі шість хлібин з печі. Вражає.'::text,'дістанеш'::text,'діставатимеш'::text,'дістав'::text,'Чесно, поки я туди дійду, ти вже дістанеш всі шість хлібин з печі. Вражає.'::text),
(380148,42239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, para cuando llegue, ya ... los seis panes del horno. Impresionante.'::text,'habrás sacado'::text,'sacarás'::text,'has sacado'::text,'La verdad, para cuando llegue, ya habrás sacado los seis panes del horno. Impresionante.'::text),
(380147,42239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, le temps que j''arrive, tu ... les six pains du four. Impressionnant.'::text,'auras sorti'::text,'sortiras'::text,'as sorti'::text,'Franchement, le temps que j''arrive, tu auras sorti les six pains du four. Impressionnant.'::text),
(380150,42239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, ben oraya varana kadar altı somunun hepsini fırından ..., etkileyici.'::text,'çıkarmış olacaksın'::text,'çıkaracaksın'::text,'çıkardın'::text,'Açıkçası, ben oraya varana kadar altı somunun hepsini fırından çıkarmış olacaksın, etkileyici.'::text),
(380151,42239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mire odaérek, már mind a hat cipót ... a kemencéből. Lenyűgöző.'::text,'kiszeded'::text,'ki fogod szedni'::text,'kiszedted'::text,'Őszintén, mire odaérek, már mind a hat cipót kiszeded a kemencéből. Lenyűgöző.'::text),
(380154,42240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, um sechs ... du schon zwölf Stunden lang Brot aus diesem Ofen. Respekt.'::text,'holst'::text,'holst'::text,'holst'::text,'Nicht gelogen, um sechs holst du schon zwölf Stunden lang Brot aus diesem Ofen. Respekt.'::text),
(380158,42240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, о шостій ти вже дванадцять годин ... хліб із тієї печі. Респект.'::text,'витягатимеш'::text,'витягатимеш'::text,'витягнеш'::text,'Не брешу, о шостій ти вже дванадцять годин витягатимеш хліб із тієї печі. Респект.'::text),
(380157,42240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, a las seis ya ... pan de ese horno durante doce horas. Respeto.'::text,'habrás estado sacando'::text,'estarás sacando'::text,'habrás sacado'::text,'No voy a mentir, a las seis ya habrás estado sacando pan de ese horno durante doce horas. Respeto.'::text),
(380156,42240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, à six heures, ça ... douze heures que tu sors du pain de ce four. Respect.'::text,'fera'::text,'fera'::text,'aura fait'::text,'Sans mentir, à six heures, ça fera douze heures que tu sors du pain de ce four. Respect.'::text),
(380159,42240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, saat altıda o fırından on iki saattir ekmek ..., saygı.'::text,'çıkarıyor olacaksın'::text,'çıkarıyor olacaksın'::text,'çıkarmış olacaksın'::text,'Yalan yok, saat altıda o fırından on iki saattir ekmek çıkarıyor olacaksın, saygı.'::text),
(380160,42240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, hatra már tizenkét órája ... kenyeret abból a kemencéből. Le a kalappal.'::text,'szedsz ki'::text,'szedsz ki'::text,'szedtél ki'::text,'Nem hazudok, hatra már tizenkét órája szedsz ki kenyeret abból a kemencéből. Le a kalappal.'::text),
(354828,39426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Bad ..., während er in der Küche war, weil er nicht dort war.'::text,'lief gerade voll'::text,'lief voll'::text,'ist vollgelaufen'::text,'Das Bad lief gerade voll, während er in der Küche war, weil er nicht dort war.'::text),
(354832,39426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ванна кімната ..., поки він був на кухні, бо його там не було.'::text,'затоплювалася'::text,'затопилася'::text,'затопилася'::text,'Ванна кімната затоплювалася, поки він був на кухні, бо його там не було.'::text),
(354831,39426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El baño ... mientras él estaba en la cocina, porque él no estaba allí.'::text,'se estaba inundando'::text,'se inundó'::text,'se ha inundado'::text,'El baño se estaba inundando mientras él estaba en la cocina, porque él no estaba allí.'::text),
(354830,39426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle de bain ... pendant qu''il était dans la cuisine, parce qu''il n''y était pas.'::text,'se remplissait d''eau'::text,'s''est remplie d''eau'::text,'s''est remplie d''eau'::text,'La salle de bain se remplissait d''eau pendant qu''il était dans la cuisine, parce qu''il n''y était pas.'::text),
(354833,39426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O mutfaktayken banyoyu ..., çünkü o orada değildi.'::text,'su basıyordu'::text,'su bastı'::text,'su basmış'::text,'O mutfaktayken banyoyu su basıyordu, çünkü o orada değildi.'::text),
(354834,39426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fürdőszobát ... a víz, amíg ő a konyhában volt, mert nem volt ott.'::text,'éppen elöntötte'::text,'elöntötte'::text,'elöntötte'::text,'A fürdőszobát éppen elöntötte a víz, amíg ő a konyhában volt, mert nem volt ott.'::text),
(354837,39427,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wasser ... seit mehreren Minuten den Badezimmerboden; dieser Prozess erfordert sofortiges Handeln.'::text,'überflutet'::text,'überflutet'::text,'überflutet'::text,'Wasser überflutet seit mehreren Minuten den Badezimmerboden; dieser Prozess erfordert sofortiges Handeln.'::text),
(354841,39427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода ... підлогу ванної вже кілька хвилин; цей процес потребує негайних дій.'::text,'заливає'::text,'заливає'::text,'заливає'::text,'Вода заливає підлогу ванної вже кілька хвилин; цей процес потребує негайних дій.'::text),
(354840,39427,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua ... el suelo del baño desde hace varios minutos; este proceso requiere una acción inmediata.'::text,'ha estado inundando'::text,'está inundando'::text,'inunda'::text,'El agua ha estado inundando el suelo del baño desde hace varios minutos; este proceso requiere una acción inmediata.'::text),
(354839,39427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau ... le sol de la salle de bain depuis plusieurs minutes ; ce processus exige une action immédiate.'::text,'inonde'::text,'inonde'::text,'inonde'::text,'L''eau inonde le sol de la salle de bain depuis plusieurs minutes ; ce processus exige une action immédiate.'::text),
(354842,39427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birkaç dakikadır banyo zeminini su ...; bu süreç acil müdahale gerektiriyor.'::text,'basıyor'::text,'basıyor'::text,'basar'::text,'Birkaç dakikadır banyo zeminini su basıyor; bu süreç acil müdahale gerektiriyor.'::text),
(354843,39427,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víz már percek óta ... a fürdőszoba padlóját; ez a folyamat azonnali beavatkozást igényel.'::text,'önti el'::text,'önti el'::text,'elönti'::text,'A víz már percek óta önti el a fürdőszoba padlóját; ez a folyamat azonnali beavatkozást igényel.'::text),
(354846,39428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... sofort ins Bad, als die Küche unter Wasser stand, schnell gedacht.'::text,'ranntest'::text,'ranntest gerade'::text,'bist gerannt'::text,'Ehrlich, du ranntest sofort ins Bad, als die Küche unter Wasser stand, schnell gedacht.'::text),
(354850,39428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... у ванну тієї ж секунди, як кухню затопило, швидко метикуєш.'::text,'побіг'::text,'біг'::text,'побіг'::text,'Чесно, ти побіг у ванну тієї ж секунди, як кухню затопило, швидко метикуєш.'::text),
(354849,39428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... al baño en cuanto se inundó la cocina, qué rapidez mental.'::text,'corriste'::text,'estabas corriendo'::text,'has corrido'::text,'La verdad, corriste al baño en cuanto se inundó la cocina, qué rapidez mental.'::text),
(354848,39428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... vers la salle de bain dès que la cuisine a été inondée, réflexe rapide.'::text,'as couru'::text,'courais'::text,'as couru'::text,'Franchement, tu as couru vers la salle de bain dès que la cuisine a été inondée, réflexe rapide.'::text),
(354851,39428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, mutfağı su bastığı an banyoya ..., hızlı düşünce.'::text,'koştun'::text,'koşuyordun'::text,'koştun'::text,'Açıkçası, mutfağı su bastığı an banyoya koştun, hızlı düşünce.'::text),
(354852,39428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, abban a pillanatban a fürdőbe ..., amikor elárasztotta a víz a konyhát, gyors észjárás.'::text,'rohantál'::text,'éppen rohantál'::text,'rohantál'::text,'Őszintén, abban a pillanatban a fürdőbe rohantál, amikor elárasztotta a víz a konyhát, gyors észjárás.'::text),
(354855,39429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wanne ... diesen Monat schon dreimal den Badboden.'::text,'flutete'::text,'flutete'::text,'flutet'::text,'Die Wanne flutete diesen Monat schon dreimal den Badboden.'::text),
(354859,39429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ванна ... підлогу ванної кімнати тричі цього місяця.'::text,'затопила'::text,'затоплювала'::text,'затоплює'::text,'Ванна затопила підлогу ванної кімнати тричі цього місяця.'::text),
(354858,39429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bañera ... el suelo del baño tres veces este mes.'::text,'ha inundado'::text,'ha estado inundando'::text,'inunda'::text,'La bañera ha inundado el suelo del baño tres veces este mes.'::text),
(354857,39429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La baignoire ... le sol de la salle de bain trois fois ce mois-ci.'::text,'a inondé'::text,'a inondé'::text,'inonde'::text,'La baignoire a inondé le sol de la salle de bain trois fois ce mois-ci.'::text),
(354860,39429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küvet bu ay banyo zeminini üç kez ...'::text,'su altında bıraktı'::text,'su altında bırakıyor'::text,'su altında bırakır'::text,'Küvet bu ay banyo zeminini üç kez su altında bıraktı.'::text),
(354861,39429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kád ebben a hónapban háromszor ... a fürdőszoba padlóját.'::text,'árasztotta el'::text,'árasztotta el'::text,'árasztja el'::text,'A kád ebben a hónapban háromszor árasztotta el a fürdőszoba padlóját.'::text),
(354864,39430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er ins Bad kam, ... der Schaum schon den ganzen Boden überflutet.'::text,'hatte'::text,'hat'::text,'hat'::text,'Als er ins Bad kam, hatte der Schaum schon den ganzen Boden überflutet.'::text),
(354868,39430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він дістався до ванної, піна вже ... всю підлогу.'::text,'залила'::text,'залила'::text,'заливає'::text,'Поки він дістався до ванної, піна вже залила всю підлогу.'::text),
(354867,39430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó al baño, la espuma ya ... todo el suelo.'::text,'había inundado'::text,'ha inundado'::text,'inunda'::text,'Para cuando llegó al baño, la espuma ya había inundado todo el suelo.'::text),
(354866,39430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il est arrivé à la salle de bain, la mousse ... tout le sol.'::text,'avait inondé'::text,'a inondé'::text,'inonde'::text,'Quand il est arrivé à la salle de bain, la mousse avait inondé tout le sol.'::text),
(354869,39430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O banyoya vardığında köpük bütün zemini çoktan ...'::text,'kaplamıştı'::text,'kapladı'::text,'kaplar'::text,'O banyoya vardığında köpük bütün zemini çoktan kaplamıştı.'::text),
(354870,39430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a fürdőbe ért, a hab már ... az egész padlót.'::text,'elborította'::text,'elborította'::text,'elborítja'::text,'Mire a fürdőbe ért, a hab már elborította az egész padlót.'::text),
(354882,39432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er einen smarten Wasserhahn, ... die Küche nicht jedes Mal unter Wasser, wenn er geht.'::text,'stünde'::text,'steht'::text,'stand'::text,'Hätte er einen smarten Wasserhahn, stünde die Küche nicht jedes Mal unter Wasser, wenn er geht.'::text),
(354886,39432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього був розумний кран, кухня ... щоразу, коли він іде.'::text,'не затоплювалася б'::text,'не затоплюватиметься'::text,'не затоплювалася'::text,'Якби в нього був розумний кран, кухня не затоплювалася б щоразу, коли він іде.'::text),
(354885,39432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera un grifo inteligente, la cocina no ... cada vez que se va.'::text,'se inundaría'::text,'se inundará'::text,'se inundó'::text,'Si tuviera un grifo inteligente, la cocina no se inundaría cada vez que se va.'::text),
(354884,39432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait un robinet connecté, la cuisine ne ... pas inondée chaque fois qu''il part.'::text,'serait'::text,'sera'::text,'était'::text,'S''il avait un robinet connecté, la cuisine ne serait pas inondée chaque fois qu''il part.'::text),
(354887,39432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akıllı bir musluğu olsa, her çıktığında mutfağı su ...'::text,'basmazdı'::text,'basmayacak'::text,'basmadı'::text,'Akıllı bir musluğu olsa, her çıktığında mutfağı su basmazdı.'::text),
(354888,39432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha okoscsapja lenne, a konyhát nem ... el a víz minden alkalommal, amikor elmegy.'::text,'öntené'::text,'önti'::text,'öntötte'::text,'Ha okoscsapja lenne, a konyhát nem öntené el a víz minden alkalommal, amikor elmegy.'::text),
(354891,39433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... seine ganze Wohnung von einem einzigen Schaumbad überflutet.'::text,'wurde'::text,'hat'::text,'wird'::text,'Okay, also angeblich wurde seine ganze Wohnung von einem einzigen Schaumbad überflutet.'::text),
(354895,39433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, усю його квартиру ... однією ванною з піною.'::text,'затопило'::text,'затопила'::text,'затоплює'::text,'Короче, кажуть, усю його квартиру затопило однією ванною з піною.'::text),
(354894,39433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer todo su piso ... por un solo baño de espuma.'::text,'quedó inundado'::text,'inundó'::text,'se está inundando'::text,'Vale, pues al parecer todo su piso quedó inundado por un solo baño de espuma.'::text),
(354893,39433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment, tout son appart ... par un seul bain moussant.'::text,'a été inondé'::text,'a inondé'::text,'est en train d''inonder'::text,'Bon, apparemment, tout son appart a été inondé par un seul bain moussant.'::text),
(354896,39433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya bütün dairesi tek bir köpük banyosu yüzünden ...'::text,'sular altında kaldı'::text,'su bastı'::text,'su basıyor'::text,'Tamam, güya bütün dairesi tek bir köpük banyosu yüzünden sular altında kaldı.'::text),
(354897,39433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag az egész lakását ... egyetlen habfürdő.'::text,'elárasztotta'::text,'elárasztotta'::text,'árasztja el'::text,'Oké, szóval állítólag az egész lakását elárasztotta egyetlen habfürdő.'::text),
(354900,39434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die überlaufende Badewanne ... den Fliesenboden mit weißem Schaum.'::text,'überflutete'::text,'wurde überflutet'::text,'überfluten'::text,'Die überlaufende Badewanne überflutete den Fliesenboden mit weißem Schaum.'::text),
(354904,39434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Переповнена ванна ... кахельну підлогу білою піною.'::text,'залила'::text,'була залита'::text,'заливання'::text,'Переповнена ванна залила кахельну підлогу білою піною.'::text),
(354903,39434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bañera desbordada ... el suelo de baldosas de espuma blanca.'::text,'inundó'::text,'fue inundada'::text,'inundando'::text,'La bañera desbordada inundó el suelo de baldosas de espuma blanca.'::text),
(354902,39434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La baignoire qui débordait ... le carrelage de mousse blanche.'::text,'a inondé'::text,'a été inondée'::text,'inondant'::text,'La baignoire qui débordait a inondé le carrelage de mousse blanche.'::text),
(354905,39434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taşan küvet fayans zemini beyaz köpükle ...'::text,'kapladı'::text,'kaplandı'::text,'kaplama'::text,'Taşan küvet fayans zemini beyaz köpükle kapladı.'::text),
(354906,39434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túlcsorduló kád ... a csempés padlót fehér habbal.'::text,'elárasztotta'::text,'el lett árasztva'::text,'elárasztás'::text,'A túlcsorduló kád elárasztotta a csempés padlót fehér habbal.'::text),
(354918,39436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 17 Uhr wird der Schaum den gesamten Flur ..., so der Bericht der Haustechnik.'::text,'überflutet haben'::text,'überfluten'::text,'überflutet'::text,'Bis 17 Uhr wird der Schaum den gesamten Flur überflutet haben, so der Bericht der Haustechnik.'::text),
(354922,39436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 17:00 піна ... весь коридор, зазначено у звіті служби експлуатації.'::text,'затопить'::text,'затоплюватиме'::text,'затоплює'::text,'До 17:00 піна затопить весь коридор, зазначено у звіті служби експлуатації.'::text),
(354921,39436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 17:00, la espuma ... todo el pasillo, según el informe de mantenimiento.'::text,'habrá inundado'::text,'inundará'::text,'inunda'::text,'Para las 17:00, la espuma habrá inundado todo el pasillo, según el informe de mantenimiento.'::text),
(354920,39436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 17 h, la mousse ... tout le couloir, selon le rapport des services techniques.'::text,'aura inondé'::text,'inondera'::text,'inonde'::text,'D''ici 17 h, la mousse aura inondé tout le couloir, selon le rapport des services techniques.'::text),
(354923,39436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 17:00''ye kadar köpük tüm koridoru ..., diyor tesis raporu.'::text,'kaplamış olacak'::text,'kaplayacak'::text,'kaplıyor'::text,'Saat 17:00''ye kadar köpük tüm koridoru kaplamış olacak, diyor tesis raporu.'::text),
(354924,39436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délután 5-re a hab ... az egész folyosót, áll a létesítménygazdálkodási jelentésben.'::text,'el fogja árasztani'::text,'elárasztja'::text,'árasztja el'::text,'Délután 5-re a hab el fogja árasztani az egész folyosót, áll a létesítménygazdálkodási jelentésben.'::text),
(367572,40842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... den letzten Kilometer dieses Marathons, völlig am Ende!'::text,'laufe ich gerade'::text,'laufe ich'::text,'laufe ich'::text,'Morgen um diese Zeit laufe ich gerade den letzten Kilometer dieses Marathons, völlig am Ende!'::text),
(367576,40842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час я ... останній кілометр цього марафону, повністю розбитий!'::text,'бігтиму'::text,'пробіжу'::text,'біжу'::text,'Завтра в цей час я бігтиму останній кілометр цього марафону, повністю розбитий!'::text),
(367575,40842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... el último kilómetro de este maratón, completamente destrozado!'::text,'estaré corriendo'::text,'correré'::text,'corro'::text,'¡Mañana a esta hora estaré corriendo el último kilómetro de este maratón, completamente destrozado!'::text),
(367574,40842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, je ... le dernier kilomètre de ce marathon, complètement détruit !'::text,'serai en train de courir'::text,'courrai'::text,'cours'::text,'Demain à la même heure, je serai en train de courir le dernier kilomètre de ce marathon, complètement détruit !'::text),
(367577,40842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde bu maratonun son kilometresini ..., tamamen bitik halde!'::text,'koşuyor olacağım'::text,'koşacağım'::text,'koşarım'::text,'Yarın bu saatlerde bu maratonun son kilometresini koşuyor olacağım, tamamen bitik halde!'::text),
(367578,40842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ennek a maratonnak az utolsó kilométerét ..., teljesen szétesve!'::text,'fogom futni'::text,'futom le'::text,'futom'::text,'Holnap ilyenkor ennek a maratonnak az utolsó kilométerét fogom futni, teljesen szétesve!'::text),
(367581,40843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, ich ... einen Marathon! Meine Beine sind komplett kaputt!'::text,'laufe nie wieder'::text,'laufe nie wieder'::text,'laufe nie'::text,'Ich verspreche, ich laufe nie wieder einen Marathon! Meine Beine sind komplett kaputt!'::text),
(367585,40843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, я ... ще один марафон! Мої ноги повністю вбиті!'::text,'ніколи не побіжу'::text,'ніколи не бігтиму'::text,'ніколи не бігаю'::text,'Обіцяю, я ніколи не побіжу ще один марафон! Мої ноги повністю вбиті!'::text),
(367584,40843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Prometo que ... otro maratón! ¡Mis piernas están completamente destrozadas!'::text,'nunca correré'::text,'nunca estaré corriendo'::text,'nunca corro'::text,'¡Prometo que nunca correré otro maratón! ¡Mis piernas están completamente destrozadas!'::text),
(367583,40843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je promets que je ... un autre marathon ! Mes jambes sont complètement détruites !'::text,'ne courrai plus jamais'::text,'ne serai plus jamais en train de courir'::text,'ne cours jamais'::text,'Je promets que je ne courrai plus jamais un autre marathon ! Mes jambes sont complètement détruites !'::text),
(367586,40843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, bir daha asla maraton ...! Bacaklarım tamamen mahvoldu!'::text,'koşmayacağım'::text,'koşuyor olmayacağım'::text,'koşmam'::text,'Söz veriyorum, bir daha asla maraton koşmayacağım! Bacaklarım tamamen mahvoldu!'::text),
(367587,40843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, hogy ... még egy maratont! A lábam teljesen tönkrement!'::text,'soha többé nem futok'::text,'soha többé nem fogok futni'::text,'sosem futok'::text,'Megígérem, hogy soha többé nem futok még egy maratont! A lábam teljesen tönkrement!'::text),
(367590,40844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Läufer während eines Marathons kein Wasser ..., werden sie schneller müde.'::text,'trinken'::text,'tranken'::text,'trinken werden'::text,'Wenn Läufer während eines Marathons kein Wasser trinken, werden sie schneller müde.'::text),
(367594,40844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бігуни ... воду під час марафону, вони швидше втомлюються.'::text,'не п''ють'::text,'не пили'::text,'не питимуть'::text,'Якщо бігуни не п''ють воду під час марафону, вони швидше втомлюються.'::text),
(367593,40844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los corredores ... agua durante un maratón, se cansan más rápido.'::text,'no beben'::text,'no bebían'::text,'no beberán'::text,'Si los corredores no beben agua durante un maratón, se cansan más rápido.'::text),
(367592,40844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les coureurs ... pas d''eau pendant un marathon, ils se fatiguent plus vite.'::text,'ne boivent'::text,'ne buvaient'::text,'ne boiront'::text,'Si les coureurs ne boivent pas d''eau pendant un marathon, ils se fatiguent plus vite.'::text),
(367595,40844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucular maraton sırasında su ..., daha çabuk yorulurlar.'::text,'içmezlerse'::text,'içmeselerdi'::text,'içmeyeceklerse'::text,'Koşucular maraton sırasında su içmezlerse, daha çabuk yorulurlar.'::text),
(367596,40844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a futók maraton közben ... vizet, gyorsabban elfáradnak.'::text,'nem isznak'::text,'nem ittak'::text,'nem fognak inni'::text,'Ha a futók maraton közben nem isznak vizet, gyorsabban elfáradnak.'::text),
(367599,40845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Läufer in Blau ... sehr fit sein, denn er setzt sich im Marathon ab.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Der Läufer in Blau muss sehr fit sein, denn er setzt sich im Marathon ab.'::text),
(367603,40845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бігун у синьому ... бути дуже витривалим, бо він вирвається вперед у марафоні.'::text,'має'::text,'не може'::text,'не повинен'::text,'Бігун у синьому має бути дуже витривалим, бо він вирвається вперед у марафоні.'::text),
(367602,40845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El corredor de azul ... estar muy en forma, porque se adelanta en el maratón.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'El corredor de azul debe de estar muy en forma, porque se adelanta en el maratón.'::text),
(367601,40845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coureur en bleu ... être très en forme, parce qu''il prend la tête du marathon.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Le coureur en bleu doit être très en forme, parce qu''il prend la tête du marathon.'::text),
(367604,40845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavili koşucu çok formda ..., çünkü maratonda öne geçiyor.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Mavili koşucu çok formda olmalı, çünkü maratonda öne geçiyor.'::text),
(367605,40845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék mezes futó ... nagyon edzett, mert elhúz a maratonon.'::text,'biztosan'::text,'nem lehet'::text,'nem szabad, hogy'::text,'A kék mezes futó biztosan nagyon edzett, mert elhúz a maratonon.'::text),
(367608,40846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straße, ... der Marathon vorbeiführt, ist von klatschenden Zuschauern gesäumt.'::text,'wo'::text,'welche'::text,'wer'::text,'Die Straße, wo der Marathon vorbeiführt, ist von klatschenden Zuschauern gesäumt.'::text),
(367612,40846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вулиця, ... проходить марафон, заповнена глядачами, які аплодують.'::text,'де'::text,'яка'::text,'хто'::text,'Вулиця, де проходить марафон, заповнена глядачами, які аплодують.'::text),
(367611,40846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calle ... pasa el maratón está llena de espectadores aplaudiendo.'::text,'por donde'::text,'que'::text,'quien'::text,'La calle por donde pasa el maratón está llena de espectadores aplaudiendo.'::text),
(367610,40846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rue ... passe le marathon est bordée de spectateurs qui applaudissent.'::text,'où'::text,'laquelle'::text,'qui'::text,'La rue où passe le marathon est bordée de spectateurs qui applaudissent.'::text),
(367613,40846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maratonun ... sokak, alkışlayan seyircilerle dolu.'::text,'geçtiği'::text,'geçen'::text,'geçen'::text,'Maratonun geçtiği sokak, alkışlayan seyircilerle dolu.'::text),
(367614,40846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utca, ... a maraton halad, tele van tapsoló nézőkkel.'::text,'ahol'::text,'amely'::text,'aki'::text,'Az utca, ahol a maraton halad, tele van tapsoló nézőkkel.'::text),
(367617,40847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... diesen Marathon ohne Training. Toller Plan, offensichtlich.'::text,'schaffe'::text,'schafft'::text,'schafft'::text,'Er sagte, er schaffe diesen Marathon ohne Training. Toller Plan, offensichtlich.'::text),
(367621,40847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... цей марафон без тренувань. Чудовий план, звісно.'::text,'добіжить'::text,'добіжить'::text,'добігає'::text,'Він сказав, що добіжить цей марафон без тренувань. Чудовий план, звісно.'::text),
(367620,40847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... este maratón sin entrenar. Gran plan, obviamente.'::text,'terminaría'::text,'terminará'::text,'termina'::text,'Dijo que terminaría este maratón sin entrenar. Gran plan, obviamente.'::text),
(367619,40847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... ce marathon sans entraînement. Super plan, évidemment.'::text,'finirait'::text,'finira'::text,'finit'::text,'Il a dit qu''il finirait ce marathon sans entraînement. Super plan, évidemment.'::text),
(367622,40847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu maratonu antrenmansız ... söyledi. Harika plan, belli ki.'::text,'bitireceğini'::text,'bitireceğini'::text,'bitirdiğini'::text,'Bu maratonu antrenmansız bitireceğini söyledi. Harika plan, belli ki.'::text),
(367623,40847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy edzés nélkül ... ezt a maratont. Remek terv, nyilván.'::text,'lefutja'::text,'le fogja futni'::text,'futja'::text,'Azt mondta, hogy edzés nélkül lefutja ezt a maratont. Remek terv, nyilván.'::text),
(367635,40849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ich riskiere doch nicht, einen Marathon auf Kopfsteinpflaster zu ...'::text,'laufen'::text,'laufen'::text,'laufen'::text,'Alter, ich riskiere doch nicht, einen Marathon auf Kopfsteinpflaster zu laufen.'::text),
(367639,40849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, я не ризикуватиму ... марафон по бруківці.'::text,'бігти'::text,'бігти'::text,'бігти'::text,'Чувак, я не ризикуватиму бігти марафон по бруківці.'::text),
(367638,40849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, no pienso arriesgarme a ... un maratón sobre adoquines.'::text,'correr'::text,'correr'::text,'correr'::text,'Tío, no pienso arriesgarme a correr un maratón sobre adoquines.'::text),
(367637,40849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, je vais pas risquer de ... un marathon sur des pavés.'::text,'courir'::text,'courir'::text,'courir'::text,'Mec, je vais pas risquer de courir un marathon sur des pavés.'::text),
(367640,40849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, parke taşında maraton ... riskine girmem.'::text,'koşma'::text,'koşma'::text,'koşma'::text,'Kanka, parke taşında maraton koşma riskine girmem.'::text),
(367641,40849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem fogom kockáztatni, hogy macskakövön ... egy maratont.'::text,'fussak'::text,'fussak'::text,'fussak'::text,'Tesó, nem fogom kockáztatni, hogy macskakövön fussak egy maratont.'::text),
(367653,40851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Marathonläufer durch die Altstadt.'::text,'laufen'::text,'laufen'::text,'sind gelaufen'::text,'Gerade laufen die Marathonläufer durch die Altstadt.'::text),
(367657,40851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз марафонці ... старим містом.'::text,'біжать'::text,'бігають'::text,'пробігли'::text,'Саме зараз марафонці біжать старим містом.'::text),
(367656,40851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo los corredores del maratón ... por el casco antiguo.'::text,'están corriendo'::text,'corren'::text,'han corrido'::text,'Ahora mismo los corredores del maratón están corriendo por el casco antiguo.'::text),
(367655,40851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, les marathoniens ... à travers la vieille ville.'::text,'courent'::text,'courent'::text,'ont couru'::text,'En ce moment, les marathoniens courent à travers la vieille ville.'::text),
(367658,40851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda maratoncular eski şehrin içinden ...'::text,'koşuyor'::text,'koşar'::text,'koştu'::text,'Şu anda maratoncular eski şehrin içinden koşuyor.'::text),
(367659,40851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A maratonfutók éppen ... az óvároson.'::text,'futnak át'::text,'futnak át'::text,'futottak át'::text,'A maratonfutók éppen futnak át az óvároson.'::text),
(367662,40852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als dieser Abschnitt des Marathons beobachtet wurde, ... die Läufer gerade durch die Altstadt.'::text,'liefen'::text,'waren gelaufen'::text,'sind gelaufen'::text,'Als dieser Abschnitt des Marathons beobachtet wurde, liefen die Läufer gerade durch die Altstadt.'::text),
(367666,40852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли цю ділянку марафону спостерігали, бігуни ... старим містом.'::text,'бігли'::text,'пробігли'::text,'пробігли'::text,'Коли цю ділянку марафону спостерігали, бігуни бігли старим містом.'::text),
(367665,40852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando se observó este tramo del maratón, los corredores ... por el casco antiguo.'::text,'estaban corriendo'::text,'habían corrido'::text,'han corrido'::text,'Cuando se observó este tramo del maratón, los corredores estaban corriendo por el casco antiguo.'::text),
(367664,40852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lorsque ce tronçon du marathon a été observé, les coureurs ... dans la vieille ville.'::text,'couraient'::text,'avaient couru'::text,'ont couru'::text,'Lorsque ce tronçon du marathon a été observé, les coureurs couraient dans la vieille ville.'::text),
(367667,40852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maratonun bu bölümü gözlemlendiğinde koşucular eski şehrin içinden ...'::text,'koşuyordu'::text,'koşmuştu'::text,'koştu'::text,'Maratonun bu bölümü gözlemlendiğinde koşucular eski şehrin içinden koşuyordu.'::text),
(367668,40852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a maraton ezen szakaszát megfigyelték, a futók éppen ... az óvároson.'::text,'futottak át'::text,'átfutottak'::text,'átfutottak'::text,'Amikor a maraton ezen szakaszát megfigyelték, a futók éppen futottak át az óvároson.'::text),
(369354,41040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann nicht aufhören, die Mischung anzustarren, und ich ...! Das ist wortwörtlich der beste Pfannkuchen!'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Er kann nicht aufhören, die Mischung anzustarren, und ich auch nicht! Das ist wortwörtlich der beste Pfannkuchen!'::text),
(369358,41040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може відірвати погляду від суміші, і я ...! Це буквально найкращий млинець!'::text,'теж не можу'::text,'теж можу'::text,'теж ні'::text,'Він не може відірвати погляду від суміші, і я теж не можу! Це буквально найкращий млинець!'::text),
(369357,41040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él no puede dejar de mirar la mezcla, y ... yo! ¡Es literalmente la mejor tortita!'::text,'tampoco'::text,'también'::text,'tampoco'::text,'¡Él no puede dejar de mirar la mezcla, y tampoco yo! ¡Es literalmente la mejor tortita!'::text),
(369356,41040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrive pas à arrêter de fixer le mélange, et moi ... ! C''est littéralement la meilleure crêpe !'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Il n''arrive pas à arrêter de fixer le mélange, et moi non plus ! C''est littéralement la meilleure crêpe !'::text),
(369359,41040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karışıma bakmayı bırakamıyor, ben de ...! Bu resmen en iyi pankek!'::text,'bırakamıyorum'::text,'bırakabiliyorum'::text,'bırakmıyorum'::text,'Karışıma bakmayı bırakamıyor, ben de bırakamıyorum! Bu resmen en iyi pankek!'::text),
(369360,41040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tud betelni a masszával, és én ...! Ez szó szerint a legjobb palacsinta!'::text,'sem'::text,'is'::text,'sem'::text,'Nem tud betelni a masszával, és én sem! Ez szó szerint a legjobb palacsinta!'::text),
(369363,41041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Butter geschmolzen ist, wird er die ganze Mischung in die Pfanne ...! Totale Katastrophe!'::text,'gekippt haben'::text,'kippen'::text,'gekippt'::text,'Bis die Butter geschmolzen ist, wird er die ganze Mischung in die Pfanne gekippt haben! Totale Katastrophe!'::text),
(369367,41041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки масло розтане, він уже ... всю суміш на сковорідку! Повна катастрофа!'::text,'виллє'::text,'виливатиме'::text,'виливає'::text,'Поки масло розтане, він уже виллє всю суміш на сковорідку! Повна катастрофа!'::text),
(369366,41041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando se derrita la mantequilla, él ya ... toda la mezcla en la sartén! ¡Desastre total!'::text,'habrá echado'::text,'echará'::text,'echa'::text,'¡Para cuando se derrita la mantequilla, él ya habrá echado toda la mezcla en la sartén! ¡Desastre total!'::text),
(369365,41041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que le beurre fonde, il ... tout le mélange dans la poêle ! Désastre total !'::text,'aura versé'::text,'versera'::text,'verse'::text,'D''ici à ce que le beurre fonde, il aura versé tout le mélange dans la poêle ! Désastre total !'::text),
(369368,41041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tereyağı eriyene kadar bütün karışımı tavaya ...! Tam bir felaket!'::text,'dökmüş olacak'::text,'dökecek'::text,'döküyor'::text,'Tereyağı eriyene kadar bütün karışımı tavaya dökmüş olacak! Tam bir felaket!'::text),
(369369,41041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a vaj elolvad, ő már az egész masszát ... a serpenyőbe! Totális katasztrófa!'::text,'beleönti'::text,'bele fogja önteni'::text,'önti'::text,'Mire a vaj elolvad, ő már az egész masszát beleönti a serpenyőbe! Totális katasztrófa!'::text),
(369372,41042,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er die Mischung dünner gemacht, ... der Pfannkuchen nicht so dick geworden.'::text,'wäre'::text,'wird'::text,'war'::text,'Hätte er die Mischung dünner gemacht, wäre der Pfannkuchen nicht so dick geworden.'::text),
(369376,41042,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він зробив суміш рідшою, млинець ... таким товстим.'::text,'не був би'::text,'не буде'::text,'не був'::text,'Якби він зробив суміш рідшою, млинець не був би таким товстим.'::text),
(369375,41042,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera hecho la mezcla más líquida, la tortita no ... tan gruesa.'::text,'habría sido'::text,'será'::text,'era'::text,'Si hubiera hecho la mezcla más líquida, la tortita no habría sido tan gruesa.'::text),
(369374,41042,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait fait le mélange plus liquide, la crêpe ... aussi épaisse.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''était pas'::text,'S''il avait fait le mélange plus liquide, la crêpe n''aurait pas été aussi épaisse.'::text),
(369377,41042,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karışımı daha sulu yapsaydı, pankek bu kadar kalın ...'::text,'olmazdı'::text,'olmayacak'::text,'değildi'::text,'Karışımı daha sulu yapsaydı, pankek bu kadar kalın olmazdı.'::text),
(369378,41042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha hígabbra csinálta volna a masszát, a palacsinta ... ilyen vastag.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha hígabbra csinálta volna a masszát, a palacsinta nem lett volna ilyen vastag.'::text),
(369381,41043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also er hat zugegeben, dass er viel zu viel Mehl in die Mischung ..., hat sie mir erzählt.'::text,'gegeben hat'::text,'geben'::text,'gab'::text,'Okay, also er hat zugegeben, dass er viel zu viel Mehl in die Mischung gegeben hat, hat sie mir erzählt.'::text),
(369385,41043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, він зізнався, що ... забагато борошна в суміш, вона мені розповіла.'::text,'додав'::text,'додати'::text,'додав'::text,'Короче, він зізнався, що додав забагато борошна в суміш, вона мені розповіла.'::text),
(369384,41043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues él admitió ... demasiada harina a la mezcla, me lo dijo ella.'::text,'haber echado'::text,'echar'::text,'echó'::text,'Vale, pues él admitió haber echado demasiada harina a la mezcla, me lo dijo ella.'::text),
(369383,41043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il a avoué ... beaucoup trop de farine dans le mélange, elle me l''a dit.'::text,'avoir mis'::text,'mettre'::text,'a mis'::text,'Bon, il a avoué avoir mis beaucoup trop de farine dans le mélange, elle me l''a dit.'::text),
(369386,41043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, karışıma çok fazla un ... itiraf etmiş, bana o söyledi.'::text,'kattığını'::text,'katmayı'::text,'kattı'::text,'Tamam, karışıma çok fazla un kattığını itiraf etmiş, bana o söyledi.'::text),
(369387,41043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval bevallotta, hogy túl sok lisztet ... a masszához, ő mondta nekem.'::text,'adott'::text,'adni'::text,'adott'::text,'Oké, szóval bevallotta, hogy túl sok lisztet adott a masszához, ő mondta nekem.'::text),
(369390,41044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pfannkuchen ist perfekt, also ... die Mischung nicht zu flüssig gewesen sein.'::text,'kann'::text,'darf'::text,'sollte'::text,'Der Pfannkuchen ist perfekt, also kann die Mischung nicht zu flüssig gewesen sein.'::text),
(369394,41044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Млинець ідеальний, тож суміш ... бути надто рідкою.'::text,'не могла'::text,'не мала права'::text,'не мала'::text,'Млинець ідеальний, тож суміш не могла бути надто рідкою.'::text),
(369393,41044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tortita está perfecta, así que la mezcla ... sido demasiado líquida.'::text,'no puede haber'::text,'no debe haber'::text,'no debería haber'::text,'La tortita está perfecta, así que la mezcla no puede haber sido demasiado líquida.'::text),
(369392,41044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crêpe est parfaite, donc le mélange ... été trop liquide.'::text,'ne peut pas avoir'::text,'ne doit pas avoir'::text,'n''aurait pas dû'::text,'La crêpe est parfaite, donc le mélange ne peut pas avoir été trop liquide.'::text),
(369395,41044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pankek mükemmel, yani karışım çok sulu ...'::text,'olmuş olamaz'::text,'olmamalı'::text,'olmamalıydı'::text,'Pankek mükemmel, yani karışım çok sulu olmuş olamaz.'::text),
(369396,41044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A palacsinta tökéletes, szóval a massza ... túl híg.'::text,'nem lehetett'::text,'nem kellett legyen'::text,'nem kellett volna lennie'::text,'A palacsinta tökéletes, szóval a massza nem lehetett túl híg.'::text),
(369399,41045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ seinen Mitbewohner die Mischung vor dem Frühstück ...'::text,'verquirlen'::text,'verquirlen'::text,'verquirlt'::text,'Er ließ seinen Mitbewohner die Mischung vor dem Frühstück verquirlen.'::text),
(369403,41045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він попросив сусіда по квартирі ... суміш перед сніданком.'::text,'збити'::text,'збити'::text,'збиту'::text,'Він попросив сусіда по квартирі збити суміш перед сніданком.'::text),
(369402,41045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizo que su compañero de piso ... la mezcla antes del desayuno.'::text,'batiera'::text,'batiera'::text,'batida'::text,'Hizo que su compañero de piso batiera la mezcla antes del desayuno.'::text),
(369401,41045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a fait ... le mélange à son coloc avant le petit-déj.'::text,'fouetter'::text,'fouetter'::text,'fouetté'::text,'Il a fait fouetter le mélange à son coloc avant le petit-déj.'::text),
(369404,41045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşına karışımı kahvaltıdan önce ...'::text,'çırptırdı'::text,'çırptırdı'::text,'çırpılmış'::text,'Ev arkadaşına karışımı kahvaltıdan önce çırptırdı.'::text),
(369405,41045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lakótársával ... fel a masszát reggeli előtt.'::text,'veretette'::text,'veretette'::text,'felvert'::text,'A lakótársával veretette fel a masszát reggeli előtt.'::text),
(369408,41046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass er mehr Pfannkuchenteig für einen zweiten Pfannkuchen ...'::text,'gemacht hätte'::text,'machte'::text,'machen würde'::text,'Er wünscht sich, dass er mehr Pfannkuchenteig für einen zweiten Pfannkuchen gemacht hätte.'::text),
(369412,41046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому б хотілося, щоб він ... більше тіста на другий млинець.'::text,'зробив'::text,'зробив'::text,'зробив би'::text,'Йому б хотілося, щоб він зробив більше тіста на другий млинець.'::text),
(369411,41046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... más masa para una segunda tortita.'::text,'haber hecho'::text,'hacer'::text,'hacer'::text,'Desearía haber hecho más masa para una segunda tortita.'::text),
(369410,41046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... plus de pâte pour une deuxième crêpe.'::text,'avoir fait'::text,'faire'::text,'faire'::text,'Il aimerait avoir fait plus de pâte pour une deuxième crêpe.'::text),
(369413,41046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke ikinci bir pankek için daha fazla karışım ... diye düşünüyor.'::text,'yapsaydı'::text,'yapsa'::text,'yapacak olsa'::text,'Keşke ikinci bir pankek için daha fazla karışım yapsaydı diye düşünüyor.'::text),
(369414,41046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha több palacsintatésztát ... egy második palacsintához.'::text,'csinált volna'::text,'csinálna'::text,'csinálna'::text,'Azt szeretné, ha több palacsintatésztát csinált volna egy második palacsintához.'::text),
(369417,41047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Mischung, ... du so langsam gegossen hast, wurde zu einem perfekten Pfannkuchen.'::text,'die'::text,'wer'::text,'wo'::text,'Ehrlich, die Mischung, die du so langsam gegossen hast, wurde zu einem perfekten Pfannkuchen.'::text),
(369421,41047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, суміш, ... ти так повільно наливав, перетворилася на ідеальний млинець.'::text,'яку'::text,'хто'::text,'де'::text,'Чесно, суміш, яку ти так повільно наливав, перетворилася на ідеальний млинець.'::text),
(369420,41047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, la mezcla ... echaste tan despacio se convirtió en una tortita perfecta.'::text,'que'::text,'quien'::text,'donde'::text,'La verdad, la mezcla que echaste tan despacio se convirtió en una tortita perfecta.'::text),
(369419,41047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, le mélange ... tu as versé si lentement est devenu une crêpe parfaite.'::text,'que'::text,'qui'::text,'où'::text,'Franchement, le mélange que tu as versé si lentement est devenu une crêpe parfaite.'::text),
(369422,41047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o kadar yavaş ... karışım mükemmel bir pankeke dönüştü.'::text,'döktüğün'::text,'döken'::text,'döktüğün yerdeki'::text,'Açıkçası, o kadar yavaş döktüğün karışım mükemmel bir pankeke dönüştü.'::text),
(369423,41047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a massza, ... olyan lassan öntöttél, tökéletes palacsintává vált.'::text,'amit'::text,'aki'::text,'ahol'::text,'Őszintén, a massza, amit olyan lassan öntöttél, tökéletes palacsintává vált.'::text),
(369435,41049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... all der Butter bleibt die Mischung irgendwie gesund, ganz klar.'::text,'Trotz'::text,'Obwohl'::text,'Dank'::text,'Trotz all der Butter bleibt die Mischung irgendwie gesund, ganz klar.'::text),
(369439,41049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... все це масло, суміш якось залишається здоровою, звісно.'::text,'Попри'::text,'Хоча'::text,'Завдяки'::text,'Попри все це масло, суміш якось залишається здоровою, звісно.'::text),
(369438,41049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... toda esa mantequilla, la mezcla sigue siendo sana de algún modo, obviamente.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de toda esa mantequilla, la mezcla sigue siendo sana de algún modo, obviamente.'::text),
(369437,41049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tout ce beurre, le mélange reste sain, d''une manière ou d''une autre, évidemment.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré tout ce beurre, le mélange reste sain, d''une manière ou d''une autre, évidemment.'::text),
(369440,41049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün o tereyağına ..., karışım bir şekilde sağlıklı kalıyor, tabii ki.'::text,'rağmen'::text,'rağmen'::text,'sayesinde'::text,'Bütün o tereyağına rağmen, karışım bir şekilde sağlıklı kalıyor, tabii ki.'::text),
(369441,41049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az összes vaj ..., a massza valahogy egészséges marad, nyilván.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Az összes vaj ellenére, a massza valahogy egészséges marad, nyilván.'::text),
(384150,42684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du nicht so laut geschrien hättest, ... du jetzt nicht der Star dieses Videos.'::text,'wärst'::text,'wärst gewesen'::text,'wirst sein'::text,'Ehrlich, wenn du nicht so laut geschrien hättest, wärst du jetzt nicht der Star dieses Videos.'::text),
(384154,42684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не кричав так голосно, ти ... зараз зіркою цього відео.'::text,'не був би'::text,'не був би'::text,'не будеш'::text,'Чесно, якби ти не кричав так голосно, ти не був би зараз зіркою цього відео.'::text),
(384153,42684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si no hubieras gritado tan fuerte, ahora ... la estrella de este vídeo.'::text,'no serías'::text,'no habrías sido'::text,'no serás'::text,'La verdad, si no hubieras gritado tan fuerte, ahora no serías la estrella de este vídeo.'::text),
(384152,42684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas crié si fort, tu ... pas la star de cette vidéo maintenant.'::text,'ne serais'::text,'n''aurais'::text,'ne seras'::text,'Franchement, si tu n''avais pas crié si fort, tu ne serais pas la star de cette vidéo maintenant.'::text),
(384155,42684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o kadar yüksek sesle bağırmasaydın, şimdi bu videonun yıldızı ...'::text,'olmazdın'::text,'olmazdın'::text,'olmayacaksın'::text,'Açıkçası, o kadar yüksek sesle bağırmasaydın, şimdi bu videonun yıldızı olmazdın.'::text),
(384156,42684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nem sikítottál volna ilyen hangosan, most nem ... ennek a videónak a sztárja.'::text,'lennél'::text,'lettél volna'::text,'leszel'::text,'Őszintén, ha nem sikítottál volna ilyen hangosan, most nem lennél ennek a videónak a sztárja.'::text),
(384159,42685,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, das Einfrierspiel ... von sehr ruhigen Leuten erfunden worden. Klar, niemand schreit.'::text,'sei'::text,'werde'::text,'werdend'::text,'Man glaubt, das Einfrierspiel sei von sehr ruhigen Leuten erfunden worden. Klar, niemand schreit.'::text),
(384163,42685,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що гру «Завмри» ... дуже спокійні люди. Очевидно, ніхто не кричить.'::text,'вигадали'::text,'вигадують'::text,'вигадуючи'::text,'Вважається, що гру «Завмри» вигадали дуже спокійні люди. Очевидно, ніхто не кричить.'::text),
(384162,42685,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el juego de las estatuas ... inventado por gente muy tranquila. Está claro, nadie grita.'::text,'fue'::text,'es'::text,'siendo'::text,'Se cree que el juego de las estatuas fue inventado por gente muy tranquila. Está claro, nadie grita.'::text),
(384161,42685,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le jeu de la statue ... inventé par des gens très calmes. Clairement, personne ne crie.'::text,'a été'::text,'est'::text,'étant'::text,'On pense que le jeu de la statue a été inventé par des gens très calmes. Clairement, personne ne crie.'::text),
(384164,42685,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heykel oyununun çok sakin insanlar tarafından ... düşünülüyor. Belli ki kimse bağırmıyor.'::text,'icat edilmiş olduğu'::text,'icat edildiği'::text,'icat edilen'::text,'Heykel oyununun çok sakin insanlar tarafından icat edilmiş olduğu düşünülüyor. Belli ki kimse bağırmıyor.'::text),
(384165,42685,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, a szoborjátékot nagyon nyugodt emberek ..., egyértelmű, senki sem sikít.'::text,'találták ki'::text,'találják ki'::text,'kitalálva'::text,'Úgy tartják, a szoborjátékot nagyon nyugodt emberek találták ki, egyértelmű, senki sem sikít.'::text),
(384168,42686,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann in Weiß stritt ab, überhaupt ... zu haben. Eindeutig der ruhigste Schrei im Park.'::text,'geschrien'::text,'geschrien'::text,'geschrien'::text,'Der Mann in Weiß stritt ab, überhaupt geschrien zu haben. Eindeutig der ruhigste Schrei im Park.'::text),
(384172,42686,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у білому заперечував, що ... взагалі. Очевидно, найспокійніший крик у парку.'::text,'кричав'::text,'кричати'::text,'кричить'::text,'Чоловік у білому заперечував, що кричав взагалі. Очевидно, найспокійніший крик у парку.'::text),
(384171,42686,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de blanco negó ... en absoluto. Claramente, el grito más tranquilo del parque.'::text,'haber gritado'::text,'gritar'::text,'gritar'::text,'El hombre de blanco negó haber gritado en absoluto. Claramente, el grito más tranquilo del parque.'::text),
(384170,42686,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme en blanc a nié ... du tout. Clairement le cri le plus calme du parc.'::text,'avoir crié'::text,'crier'::text,'crier'::text,'L''homme en blanc a nié avoir crié du tout. Clairement le cri le plus calme du parc.'::text),
(384173,42686,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyazlı adam hiç ... inkâr etti. Belli ki parktaki en sakin çığlık.'::text,'bağırdığını'::text,'bağırmayı'::text,'bağır'::text,'Beyazlı adam hiç bağırdığını inkâr etti. Belli ki parktaki en sakin çığlık.'::text),
(384174,42686,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér pólós férfi tagadta, hogy ... egy kicsit is. Egyértelműen a legnyugodtabb sikoly a parkban.'::text,'sikított'::text,'sikítani'::text,'sikít'::text,'A fehér pólós férfi tagadta, hogy sikított egy kicsit is. Egyértelműen a legnyugodtabb sikoly a parkban.'::text),
(384177,42687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... so laut schreien sollen, der ganze Park hat sie gehört, echt.'::text,'hätte nicht'::text,'durfte nicht'::text,'konnte nicht'::text,'Alter, sie hätte nicht so laut schreien sollen, der ganze Park hat sie gehört, echt.'::text),
(384181,42687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, їй ... так голосно кричати, весь парк її чув, реально.'::text,'не варто було'::text,'не можна було'::text,'не вдалося'::text,'Бро, їй не варто було так голосно кричати, весь парк її чув, реально.'::text),
(384180,42687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella no ... gritado tan fuerte, todo el parque la oyó, en serio.'::text,'debería haber'::text,'debe haber'::text,'pudo'::text,'Tío, ella no debería haber gritado tan fuerte, todo el parque la oyó, en serio.'::text),
(384179,42687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... crié aussi fort, tout le parc l''a entendue, sérieux.'::text,'n''aurait pas dû'::text,'n''a pas dû'::text,'ne pouvait pas'::text,'Frère, elle n''aurait pas dû crié aussi fort, tout le parc l''a entendue, sérieux.'::text),
(384182,42687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kadar yüksek sesle ..., bütün park onu duydu, cidden.'::text,'bağırmamalıydı'::text,'bağırmamış olmalı'::text,'bağıramazdı'::text,'Kanka, o kadar yüksek sesle bağırmamalıydı, bütün park onu duydu, cidden.'::text),
(384183,42687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem ... ilyen hangosan sikítania, az egész park hallotta, komolyan.'::text,'kellett volna'::text,'kellett'::text,'tudott'::text,'Tesó, nem kellett volna ilyen hangosan sikítania, az egész park hallotta, komolyan.'::text),
(384186,42688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... so laut in einem ruhigen Park.'::text,'schreien Leute'::text,'Leute schreien'::text,'schreien Leute'::text,'Selten schreien Leute so laut in einem ruhigen Park.'::text),
(384190,42688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... так голосно в тихому парку.'::text,'кричать люди'::text,'люди кричать'::text,'кричать люди'::text,'Рідко кричать люди так голосно в тихому парку.'::text),
(384189,42688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... tan fuerte en un parque tranquilo.'::text,'grita la gente'::text,'la gente grita'::text,'grita la gente'::text,'Rara vez grita la gente tan fuerte en un parque tranquilo.'::text),
(384188,42688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... aussi fort dans un parc calme.'::text,'les gens crient-ils'::text,'les gens crient'::text,'les gens crient-ils'::text,'Rarement les gens crient-ils aussi fort dans un parc calme.'::text),
(384191,42688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sessiz bir parkta insanlar nadiren bu kadar yüksek sesle ...'::text,'bağırır'::text,'bağırır'::text,'bağırır'::text,'Sessiz bir parkta insanlar nadiren bu kadar yüksek sesle bağırır.'::text),
(384192,42688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ilyen hangosan az emberek egy csendes parkban.'::text,'sikítanak'::text,'sikítanak'::text,'sikítanak'::text,'Ritkán sikítanak ilyen hangosan az emberek egy csendes parkban.'::text),
(384195,42689,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann in Weiß brachte seine Freunde dazu, jedes Mal zu ..., wenn er auftaute.'::text,'schreien'::text,'schreien'::text,'schreien'::text,'Der Mann in Weiß brachte seine Freunde dazu, jedes Mal zu schreien, wenn er auftaute.'::text),
(384199,42689,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у білому змушував друзів ... щоразу, коли він «розморожувався».'::text,'кричати'::text,'кричати'::text,'крик'::text,'Чоловік у білому змушував друзів кричати щоразу, коли він «розморожувався».'::text),
(384198,42689,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de blanco hacía que sus amigos ... cada vez que se descongelaba.'::text,'gritaran'::text,'gritaran'::text,'gritando'::text,'El hombre de blanco hacía que sus amigos gritaran cada vez que se descongelaba.'::text),
(384197,42689,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme en blanc faisait ... ses amis à chaque fois qu''il se débloquait.'::text,'crier'::text,'crier'::text,'criant'::text,'L''homme en blanc faisait crier ses amis à chaque fois qu''il se débloquait.'::text),
(384200,42689,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyazlı adam, her çözüldüğünde arkadaşlarını ...'::text,'bağırttı'::text,'bağırttı'::text,'bağırarak'::text,'Beyazlı adam, her çözüldüğünde arkadaşlarını bağırttı.'::text),
(384201,42689,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér pólós férfi rávette a barátait, hogy ... minden alkalommal, amikor kiolvadt.'::text,'sikítsanak'::text,'sikítsanak'::text,'sikítás'::text,'A fehér pólós férfi rávette a barátait, hogy sikítsanak minden alkalommal, amikor kiolvadt.'::text),
(384204,42690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann in Weiß wünscht sich, dass er vor der Kamera nicht so laut ...'::text,'geschrien hätte'::text,'schriee'::text,'schreien würde'::text,'Der Mann in Weiß wünscht sich, dass er vor der Kamera nicht so laut geschrien hätte.'::text),
(384208,42690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у білому хотів би, щоб він не ... так голосно перед камерою.'::text,'кричав'::text,'кричав'::text,'кричав би'::text,'Чоловік у білому хотів би, щоб він не кричав так голосно перед камерою.'::text),
(384207,42690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de blanco desearía no ... tan fuerte delante de la cámara.'::text,'haber gritado'::text,'gritar'::text,'gritar'::text,'El hombre de blanco desearía no haber gritado tan fuerte delante de la cámara.'::text),
(384206,42690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme en blanc regrette ... aussi fort devant la caméra.'::text,'d''avoir crié'::text,'de crier'::text,'de crier'::text,'L''homme en blanc regrette d''avoir crié aussi fort devant la caméra.'::text),
(384209,42690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyazlı adam keşke kameranın önünde bu kadar yüksek sesle ... diye düşünüyor.'::text,'bağırmasaydı'::text,'bağırmasa'::text,'bağırmayacak olsa'::text,'Beyazlı adam keşke kameranın önünde bu kadar yüksek sesle bağırmasaydı diye düşünüyor.'::text),
(384210,42690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér pólós férfi azt szeretné, ha nem ... ilyen hangosan a kamera előtt.'::text,'sikított volna'::text,'sikítana'::text,'sikítana'::text,'A fehér pólós férfi azt szeretné, ha nem sikított volna ilyen hangosan a kamera előtt.'::text),
(384222,42692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrien und tanzten weiter, ... der Leute, die auf dem Weg vorbeigingen.'::text,'ungeachtet'::text,'im Falle'::text,'aufgrund'::text,'Sie schrien und tanzten weiter, ungeachtet der Leute, die auf dem Weg vorbeigingen.'::text),
(384226,42692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони далі кричали й танцювали, ... людей, які проходили повз стежкою.'::text,'незважаючи на'::text,'у разі'::text,'через'::text,'Вони далі кричали й танцювали, незважаючи на людей, які проходили повз стежкою.'::text),
(384225,42692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguieron gritando y bailando ... la gente que pasaba por el camino.'::text,'sin importar'::text,'en caso de'::text,'debido a'::text,'Siguieron gritando y bailando sin importar la gente que pasaba por el camino.'::text),
(384224,42692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont continué à crier et à danser ... des gens qui passaient sur le chemin.'::text,'sans se soucier'::text,'en cas'::text,'en raison'::text,'Ils ont continué à crier et à danser sans se soucier des gens qui passaient sur le chemin.'::text),
(384227,42692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yoldan geçen insanlara ... bağırıp dans etmeye devam ettiler.'::text,'aldırmadan'::text,'durumunda'::text,'sayesinde'::text,'Yoldan geçen insanlara aldırmadan bağırıp dans etmeye devam ettiler.'::text),
(384228,42692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tovább sikítottak és táncoltak, ... az ösvényen elhaladó emberekkel.'::text,'nem törődve'::text,'arra az esetre'::text,'miatt'::text,'Tovább sikítottak és táncoltak, nem törődve az ösvényen elhaladó emberekkel.'::text),
(384231,42693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat mir gesagt, er wusste, seine Freunde ..., sobald er einfriert.'::text,'würden schreien'::text,'werden schreien'::text,'schreien'::text,'Hör mal, er hat mir gesagt, er wusste, seine Freunde würden schreien, sobald er einfriert.'::text),
(384235,42693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що знав, що друзі ... тієї ж секунди, як він завмре.'::text,'закричать'::text,'закричать'::text,'кричать'::text,'Слухай, він сказав мені, що знав, що друзі закричать тієї ж секунди, як він завмре.'::text),
(384234,42693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que sabía que sus amigos ... en cuanto él se congelara.'::text,'gritarían'::text,'gritarán'::text,'están gritando'::text,'Escucha, me dijo que sabía que sus amigos gritarían en cuanto él se congelara.'::text),
(384233,42693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il savait que ses amis ... dès qu''il se figerait.'::text,'crieraient'::text,'crieront'::text,'crient'::text,'Écoute, il m''a dit qu''il savait que ses amis crieraient dès qu''il se figerait.'::text),
(384236,42693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana donduğu an arkadaşlarının ... bildiğini söyledi.'::text,'bağıracağını'::text,'bağıracağını'::text,'bağırdığını'::text,'Dinle, bana donduğu an arkadaşlarının bağıracağını bildiğini söyledi.'::text),
(384237,42693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, tudta, hogy a barátai ... abban a pillanatban, amikor megdermed.'::text,'sikítani fognak'::text,'sikítani fognak'::text,'sikítanak'::text,'Figyelj, azt mondta, tudta, hogy a barátai sikítani fognak abban a pillanatban, amikor megdermed.'::text),
(384240,42694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... jedes Mal, wenn du auftaust. Ikonische Energie.'::text,'schreist'::text,'schreist'::text,'hast geschrien'::text,'Ehrlich, du schreist jedes Mal, wenn du auftaust. Ikonische Energie.'::text),
(384244,42694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... щоразу, коли розмерзаєшся. Культова енергія.'::text,'кричиш'::text,'кричиш'::text,'закричав'::text,'Чесно, ти кричиш щоразу, коли розмерзаєшся. Культова енергія.'::text),
(384243,42694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... cada vez que te descongelas. Energía icónica.'::text,'gritas'::text,'estás gritando'::text,'has gritado'::text,'La verdad, gritas cada vez que te descongelas. Energía icónica.'::text),
(384242,42694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... chaque fois que tu te dégèles. Énergie iconique.'::text,'cries'::text,'cries'::text,'as crié'::text,'Franchement, tu cries chaque fois que tu te dégèles. Énergie iconique.'::text),
(384245,42694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, her çözüldüğünde ... resmen. İkonik enerji.'::text,'bağırıyorsun'::text,'bağırıyorsun'::text,'bağırdın'::text,'Açıkçası, her çözüldüğünde bağırıyorsun resmen. İkonik enerji.'::text),
(384246,42694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, minden alkalommal ..., amikor kiolvadsz. Ikonikus energia.'::text,'sikítasz'::text,'sikítasz'::text,'sikítottál'::text,'Őszintén, minden alkalommal sikítasz, amikor kiolvadsz. Ikonikus energia.'::text),
(389487,43277,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... sich gerade in diese winzige Lücke, als das Auto hinter ihr anfing zu hupen, echt.'::text,'quetschte'::text,'quetschte'::text,'hat gequetscht'::text,'Yo, sie quetschte sich gerade in diese winzige Lücke, als das Auto hinter ihr anfing zu hupen, echt.'::text),
(389491,43277,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона ... в це крихітне місце, коли машина позаду почала сигналити, реально.'::text,'втискалася'::text,'втиснулася'::text,'втиснулася'::text,'Йо, вона втискалася в це крихітне місце, коли машина позаду почала сигналити, реально.'::text),
(389490,43277,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella ... en ese hueco diminuto cuando el coche de atrás empezó a pitar, en serio.'::text,'se estaba metiendo'::text,'se metió'::text,'se ha metido'::text,'Oye, ella se estaba metiendo en ese hueco diminuto cuando el coche de atrás empezó a pitar, en serio.'::text),
(389489,43277,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle ... dans cette place minuscule quand la voiture derrière a commencé à klaxonner, sérieux.'::text,'se faufilait'::text,'s''est faufilée'::text,'s''est faufilée'::text,'Yo, elle se faufilait dans cette place minuscule quand la voiture derrière a commencé à klaxonner, sérieux.'::text),
(389492,43277,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, arkadaki araba korna çalmaya başladığında o minicik boşluğa ..., cidden.'::text,'sıkışıyordu'::text,'sıkıştı'::text,'sıkıştı'::text,'Kanka, arkadaki araba korna çalmaya başladığında o minicik boşluğa sıkışıyordu, cidden.'::text),
(389493,43277,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, éppen ... abba a pici helyre, amikor a mögötte álló autó dudálni kezdett, komolyan.'::text,'préselődött be'::text,'bepréselődött'::text,'bepréselődött'::text,'Figyu, éppen préselődött be abba a pici helyre, amikor a mögötte álló autó dudálni kezdett, komolyan.'::text),
(389496,43278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit 25 Minuten nach einem Parkplatz, deutlich über dem Ziel.'::text,'sucht'::text,'sucht'::text,'sucht'::text,'Sie sucht seit 25 Minuten nach einem Parkplatz, deutlich über dem Ziel.'::text),
(389500,43278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... паркомісце вже 25 хвилин, значно понад ціль.'::text,'шукає'::text,'шукає'::text,'шукає'::text,'Вона шукає паркомісце вже 25 хвилин, значно понад ціль.'::text),
(389499,43278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una plaza de aparcamiento durante 25 minutos, muy por encima del objetivo.'::text,'Ha estado buscando'::text,'Está buscando'::text,'Busca'::text,'Ha estado buscando una plaza de aparcamiento durante 25 minutos, muy por encima del objetivo.'::text),
(389498,43278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une place de parking depuis 25 minutes, bien au-dessus de l''objectif.'::text,'cherche'::text,'cherche'::text,'cherche'::text,'Elle cherche une place de parking depuis 25 minutes, bien au-dessus de l''objectif.'::text),
(389501,43278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'25 dakikadır park yeri ..., hedefin çok üstünde.'::text,'arıyor'::text,'arıyor'::text,'arar'::text,'25 dakikadır park yeri arıyor, hedefin çok üstünde.'::text),
(389502,43278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'25 perce ... parkolóhelyet, jóval a cél felett.'::text,'keres'::text,'keres'::text,'keres'::text,'25 perce keres parkolóhelyet, jóval a cél felett.'::text),
(389505,43279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Auto in die Lücke, stieg aus und schlug die Tür zu.'::text,'manövrierte'::text,'manövrierte gerade'::text,'hat manövriert'::text,'Sie manövrierte das Auto in die Lücke, stieg aus und schlug die Tür zu.'::text),
(389509,43279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... машину на місце, вийшла й зачинила двері.'::text,'обережно завела'::text,'обережно заводила'::text,'обережно завела'::text,'Вона обережно завела машину на місце, вийшла й зачинила двері.'::text),
(389508,43279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el coche en el hueco, bajó y cerró la puerta.'::text,'Metió despacio'::text,'Estaba metiendo despacio'::text,'Ha metido despacio'::text,'Metió despacio el coche en el hueco, bajó y cerró la puerta.'::text),
(389507,43279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la voiture dans la place, est sortie et a claqué la portière.'::text,'a glissé doucement'::text,'glissait doucement'::text,'a glissé doucement'::text,'Elle a glissé doucement la voiture dans la place, est sortie et a claqué la portière.'::text),
(389510,43279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabayı yavaşça park yerine ..., indi ve kapıyı kapattı.'::text,'soktu'::text,'sokuyordu'::text,'soktu'::text,'Arabayı yavaşça park yerine soktu, indi ve kapıyı kapattı.'::text),
(389511,43279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Óvatosan ... az autóval a helyre, kiszállt és becsukta az ajtót.'::text,'beállt'::text,'éppen beállt'::text,'beállt'::text,'Óvatosan beállt az autóval a helyre, kiszállt és becsukta az ajtót.'::text),
(389514,43280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... diese Woche zweimal in dieser engen Lücke.'::text,'parkte'::text,'parkte'::text,'parkt'::text,'Sie parkte diese Woche zweimal in dieser engen Lücke.'::text),
(389518,43280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього тижня вона ... на цьому тісному місці двічі.'::text,'паркувалася'::text,'паркувалася'::text,'паркується'::text,'Цього тижня вона паркувалася на цьому тісному місці двічі.'::text),
(389517,43280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... en este hueco estrecho dos veces esta semana.'::text,'Ha aparcado'::text,'Ha estado aparcando'::text,'Está aparcando'::text,'Ha aparcado en este hueco estrecho dos veces esta semana.'::text),
(389516,43280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans cette place étroite deux fois cette semaine.'::text,'s''est garée'::text,'s''est garée'::text,'se gare'::text,'Elle s''est garée dans cette place étroite deux fois cette semaine.'::text),
(389519,43280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu hafta bu dar yere iki kez ...'::text,'park etti'::text,'park ediyor'::text,'park ediyor'::text,'Bu hafta bu dar yere iki kez park etti.'::text),
(389520,43280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen a héten kétszer ... ezen a szűk helyen.'::text,'parkolt'::text,'parkolt'::text,'parkol'::text,'Ezen a héten kétszer parkolt ezen a szűk helyen.'::text),
(389532,43282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie beim ersten Versuch in die Lücke passt, ... sie eine Medaille. Ganz klar.'::text,'verdient'::text,'würde verdienen'::text,'verdiente'::text,'Wenn sie beim ersten Versuch in die Lücke passt, verdient sie eine Medaille. Ganz klar.'::text),
(389536,43282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона влізе на це місце з першої спроби, вона ... медаль. Очевидно.'::text,'заслужить'::text,'заслужила б'::text,'заслужила'::text,'Якщо вона влізе на це місце з першої спроби, вона заслужить медаль. Очевидно.'::text),
(389535,43282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si entra en ese hueco a la primera, ... una medalla. Obviamente.'::text,'merecerá'::text,'merecería'::text,'mereció'::text,'Si entra en ese hueco a la primera, merecerá una medalla. Obviamente.'::text),
(389534,43282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle rentre dans cette place du premier coup, elle ... une médaille. Évidemment.'::text,'méritera'::text,'mériterait'::text,'méritait'::text,'Si elle rentre dans cette place du premier coup, elle méritera une médaille. Évidemment.'::text),
(389537,43282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yere ilk seferde sığarsa bir madalyayı ..., tabii ki.'::text,'hak edecek'::text,'hak ederdi'::text,'hak etti'::text,'O yere ilk seferde sığarsa bir madalyayı hak edecek, tabii ki.'::text),
(389538,43282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elsőre befér arra a helyre, ... egy érmet. Nyilván.'::text,'megérdemel'::text,'megérdemelne'::text,'megérdemelt'::text,'Ha elsőre befér arra a helyre, megérdemel egy érmet. Nyilván.'::text),
(389541,43283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gäbe es noch einen Platz in dieser Straße, ... mein Leben nicht so komplett ruiniert!'::text,'wäre'::text,'wird'::text,'ist'::text,'Gäbe es noch einen Platz in dieser Straße, wäre mein Leben nicht so komplett ruiniert!'::text),
(389545,43283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на цій вулиці було ще одне місце, моє життя ... таким повністю зруйнованим!'::text,'не було б'::text,'не буде'::text,'не є'::text,'Якби на цій вулиці було ще одне місце, моє життя не було б таким повністю зруйнованим!'::text),
(389544,43283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si hubiera un sitio más en esta calle, mi vida no ... tan completamente arruinada!'::text,'estaría'::text,'estará'::text,'está'::text,'¡Si hubiera un sitio más en esta calle, mi vida no estaría tan completamente arruinada!'::text),
(389543,43283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il y avait une place de plus dans cette rue, ma vie ... pas aussi complètement fichue !'::text,'ne serait'::text,'ne sera'::text,'n''est'::text,'S''il y avait une place de plus dans cette rue, ma vie ne serait pas aussi complètement fichue !'::text),
(389546,43283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sokakta bir yer daha olsaydı, hayatım bu kadar mahvolmuş ...!'::text,'olmazdı'::text,'olmayacak'::text,'değil'::text,'Bu sokakta bir yer daha olsaydı, hayatım bu kadar mahvolmuş olmazdı!'::text),
(389547,43283,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lenne még egy hely ebben az utcában, az életem nem ... ennyire tönkretéve!'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha lenne még egy hely ebben az utcában, az életem nem lenne ennyire tönkretéve!'::text),
(389550,43284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der letzte Platz in der Straße ... von einem winzigen blauen Auto besetzt! Absolut unglaublich!'::text,'wurde'::text,'nahm'::text,'wurde gerade'::text,'Der letzte Platz in der Straße wurde von einem winzigen blauen Auto besetzt! Absolut unglaublich!'::text),
(389554,43284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Останнє місце на вулиці ... крихітним синім авто! Абсолютно неймовірно!'::text,'було зайняте'::text,'зайняло'::text,'займало'::text,'Останнє місце на вулиці було зайняте крихітним синім авто! Абсолютно неймовірно!'::text),
(389553,43284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El último sitio de la calle ... por un coche azul diminuto! ¡Absolutamente increíble!'::text,'fue ocupado'::text,'ocupó'::text,'estaba ocupando'::text,'¡El último sitio de la calle fue ocupado por un coche azul diminuto! ¡Absolutamente increíble!'::text),
(389552,43284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dernière place de la rue ... par une minuscule voiture bleue ! Absolument incroyable !'::text,'a été prise'::text,'a pris'::text,'prenait'::text,'La dernière place de la rue a été prise par une minuscule voiture bleue ! Absolument incroyable !'::text),
(389555,43284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokaktaki son yer minicik mavi bir araba tarafından ...! Kesinlikle inanılmaz!'::text,'kapıldı'::text,'kaptı'::text,'kapıyordu'::text,'Sokaktaki son yer minicik mavi bir araba tarafından kapıldı! Kesinlikle inanılmaz!'::text),
(389556,43284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utca utolsó helyét ... egy pici kék autó! Hihetetlen!'::text,'elfoglalta'::text,'elfoglalta'::text,'foglalta el éppen'::text,'Az utca utolsó helyét elfoglalta egy pici kék autó! Hihetetlen!'::text),
(389559,43285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beste, angeblich war ..., auf dem sie geparkt hat, der letzte in der Straße.'::text,'der Platz'::text,'ein Platz'::text,'Platz'::text,'Beste, angeblich war der Platz, auf dem sie geparkt hat, der letzte in der Straße.'::text),
(389563,43285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ... місце, де вона припаркувалася, було останнім на вулиці.'::text,''::text,NULL::text,NULL::text,'Подруго, кажуть, місце, де вона припаркувалася, було останнім на вулиці.'::text),
(389562,43285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... donde aparcó era el último de la calle.'::text,'el sitio'::text,'un sitio'::text,'sitio'::text,'Amiga, al parecer el sitio donde aparcó era el último de la calle.'::text),
(389561,43285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ... où elle s''est garée était la dernière de la rue.'::text,'la place'::text,'une place'::text,'place'::text,'Ma belle, apparemment la place où elle s''est garée était la dernière de la rue.'::text),
(389564,43285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya onun park ettiği ... yer sokaktaki son yermiş.'::text,''::text,'bir'::text,NULL::text,'Kanka, güya onun park ettiği yer sokaktaki son yermiş.'::text),
(389565,43285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ..., ahol parkolt, volt az utolsó az utcában.'::text,'a hely'::text,'egy hely'::text,'hely'::text,'Csajszi, állítólag a hely, ahol parkolt, volt az utolsó az utcában.'::text),
(389568,43286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, sie ... ewig um den Block gefahren, bevor sie den Platz gefunden hat.'::text,'sei'::text,'fuhr'::text,'ist'::text,'Mädel, ich hab gehört, sie sei ewig um den Block gefahren, bevor sie den Platz gefunden hat.'::text),
(389572,43286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вона ... навколо кварталу цілу вічність, перш ніж знайшла те місце.'::text,'кружляла'::text,'кружляла'::text,'кружляє'::text,'Подруго, я чула, що вона кружляла навколо кварталу цілу вічність, перш ніж знайшла те місце.'::text),
(389571,43286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que ... dando vueltas a la manzana siglos antes de encontrar ese sitio.'::text,'había estado'::text,'estaba'::text,'ha estado'::text,'Tía, he oído que había estado dando vueltas a la manzana siglos antes de encontrar ese sitio.'::text),
(389570,43286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu qu''elle ... autour du pâté de maisons pendant une éternité avant de trouver cette place.'::text,'avait tourné'::text,'tournait'::text,'a tourné'::text,'Meuf, j''ai entendu qu''elle avait tourné autour du pâté de maisons pendant une éternité avant de trouver cette place.'::text),
(389573,43286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki o yeri bulmadan önce çok uzun süre mahallenin etrafında ...'::text,'dönüp durmuş'::text,'dönüyormuş'::text,'dönüp duruyor'::text,'Kızım, duydum ki o yeri bulmadan önce çok uzun süre mahallenin etrafında dönüp durmuş.'::text),
(389574,43286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy egy örökkévalóságig ... a háztömb körül, mielőtt megtalálta azt a helyet.'::text,'körözött'::text,'körözött'::text,'köröz'::text,'Csajszi, azt hallottam, hogy egy örökkévalóságig körözött a háztömb körül, mielőtt megtalálta azt a helyet.'::text),
(372846,41428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Parlament ... seit drei Wochen über dasselbe Gesetz.'::text,'debattiert'::text,'debattiert'::text,'debattiert'::text,'Dieses Parlament debattiert seit drei Wochen über dasselbe Gesetz.'::text),
(372850,41428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей парламент ... той самий закон уже три тижні.'::text,'обговорює'::text,'обговорює'::text,'обговорює'::text,'Цей парламент обговорює той самий закон уже три тижні.'::text),
(372849,41428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este parlamento ... el mismo proyecto de ley desde hace tres semanas.'::text,'ha estado debatiendo'::text,'está debatiendo'::text,'debate'::text,'Este parlamento ha estado debatiendo el mismo proyecto de ley desde hace tres semanas.'::text),
(372848,41428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce parlement ... de la même loi depuis trois semaines.'::text,'débat'::text,'débat'::text,'débat'::text,'Ce parlement débat de la même loi depuis trois semaines.'::text),
(372851,41428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu meclis üç haftadır aynı yasayı ...'::text,'tartışıyor'::text,'tartışıyor'::text,'tartışır'::text,'Bu meclis üç haftadır aynı yasayı tartışıyor.'::text),
(372852,41428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a parlament már három hete ... ugyanarról a törvényről.'::text,'vitázik'::text,'vitázik'::text,'vitázik'::text,'Ez a parlament már három hete vitázik ugyanarról a törvényről.'::text),
(372855,41429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ganze Parlament ... auf und applaudierte, sobald die Abstimmung vorbei war.'::text,'stand'::text,'stand gerade'::text,'ist gestanden'::text,'Das ganze Parlament stand auf und applaudierte, sobald die Abstimmung vorbei war.'::text),
(372859,41429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Увесь парламент ... й зааплодував, щойно голосування закінчилося.'::text,'підвівся'::text,'стояв'::text,'підвівся'::text,'Увесь парламент підвівся й зааплодував, щойно голосування закінчилося.'::text),
(372858,41429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el parlamento ... y aplaudió en cuanto terminó la votación.'::text,'se levantó'::text,'estaba de pie'::text,'se ha levantado'::text,'Todo el parlamento se levantó y aplaudió en cuanto terminó la votación.'::text),
(372857,41429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le parlement ... et a applaudi dès la fin du vote.'::text,'s''est levé'::text,'était debout'::text,'s''est levé'::text,'Tout le parlement s''est levé et a applaudi dès la fin du vote.'::text),
(372860,41429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oylama biter bitmez bütün meclis ... ve alkışladı.'::text,'ayağa kalktı'::text,'ayakta duruyordu'::text,'ayağa kalktı'::text,'Oylama biter bitmez bütün meclis ayağa kalktı ve alkışladı.'::text),
(372861,41429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész parlament ... és tapsolt, amint véget ért a szavazás.'::text,'felállt'::text,'állt'::text,'felállt'::text,'Az egész parlament felállt és tapsolt, amint véget ért a szavazás.'::text),
(372864,41430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... heute viermal im Parlament die Hand gehoben, Respekt.'::text,'hast'::text,'hast'::text,'hebst'::text,'Du hast heute viermal im Parlament die Hand gehoben, Respekt.'::text),
(372868,41430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сьогодні ... руку в парламенті чотири рази, респект.'::text,'підняла'::text,'піднімала'::text,'піднімаєш'::text,'Ти сьогодні підняла руку в парламенті чотири рази, респект.'::text),
(372867,41430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... la mano en el parlamento cuatro veces, respeto.'::text,'has levantado'::text,'has estado levantando'::text,'levantas'::text,'Hoy has levantado la mano en el parlamento cuatro veces, respeto.'::text),
(372866,41430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la main quatre fois au parlement aujourd''hui, respect.'::text,'as levé'::text,'as levé'::text,'lèves'::text,'Tu as levé la main quatre fois au parlement aujourd''hui, respect.'::text),
(372869,41430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün mecliste dört kez el ..., saygı.'::text,'kaldırdın'::text,'kaldırıyorsun'::text,'kaldırırsın'::text,'Bugün mecliste dört kez el kaldırdın, saygı.'::text),
(372870,41430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma már négyszer ... fel a kezed a parlamentben, le a kalappal.'::text,'tetted'::text,'tetted'::text,'teszed'::text,'Ma már négyszer tetted fel a kezed a parlamentben, le a kalappal.'::text),
(372873,41431,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er sprach, ... das Parlament schon abgestimmt. Tolles Timing, offensichtlich.'::text,'hatte'::text,'hat'::text,'war'::text,'Als er sprach, hatte das Parlament schon abgestimmt. Tolles Timing, offensichtlich.'::text),
(372877,41431,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він заговорив, парламент ... проголосував. Чудовий таймінг, звісно.'::text,'уже'::text,'уже'::text,'був уже'::text,'Коли він заговорив, парламент уже проголосував. Чудовий таймінг, звісно.'::text),
(372876,41431,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando habló, el parlamento ya ... votado. Qué buen momento, obviamente.'::text,'había'::text,'ha'::text,'era'::text,'Cuando habló, el parlamento ya había votado. Qué buen momento, obviamente.'::text),
(372875,41431,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a parlé, le parlement ... déjà voté. Timing parfait, évidemment.'::text,'avait'::text,'a'::text,'était'::text,'Quand il a parlé, le parlement avait déjà voté. Timing parfait, évidemment.'::text),
(372878,41431,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O konuştuğunda meclis oylamayı çoktan ..., harika zamanlama, belli ki.'::text,'yapmıştı'::text,'yaptı'::text,'idi'::text,'O konuştuğunda meclis oylamayı çoktan yapmıştı, harika zamanlama, belli ki.'::text),
(372879,41431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megszólalt, a parlament már ... a szavazással. Remek időzítés, nyilván.'::text,'végzett'::text,'végzett'::text,'kész volt'::text,'Mire megszólalt, a parlament már végzett a szavazással. Remek időzítés, nyilván.'::text),
(372882,41432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Redner noch eine Stunde spricht, ... das Parlament natürlich wach.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn der Redner noch eine Stunde spricht, bleibt das Parlament natürlich wach.'::text),
(372886,41432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо промовець говоритиме ще годину, парламент, звісно, ... бадьорим.'::text,'залишиться'::text,'залишився б'::text,'залишився'::text,'Якщо промовець говоритиме ще годину, парламент, звісно, залишиться бадьорим.'::text),
(372885,41432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el orador habla una hora más, el parlamento ... despierto, claro.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si el orador habla una hora más, el parlamento seguirá despierto, claro.'::text),
(372884,41432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''orateur parle encore une heure, le parlement ... éveillé, bien sûr.'::text,'restera'::text,'resterait'::text,'est resté'::text,'Si l''orateur parle encore une heure, le parlement restera éveillé, bien sûr.'::text),
(372887,41432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konuşmacı bir saat daha konuşursa meclis uyanık ..., tabii ki.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Konuşmacı bir saat daha konuşursa meclis uyanık kalacak, tabii ki.'::text),
(372888,41432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szónok még egy órát beszél, a parlament ... ébren, persze.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha a szónok még egy órát beszél, a parlament marad ébren, persze.'::text),
(372891,41433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber wenn ich im Parlament ..., würde ich auch lowkey alles beklatschen.'::text,'säße'::text,'sitze'::text,'sitzen würde'::text,'Okay, aber wenn ich im Parlament säße, würde ich auch lowkey alles beklatschen.'::text),
(372895,41433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ок, але якби я ... в парламенті, я б теж тихенько всьому плескав.'::text,'сидів'::text,'сиджу'::text,'сидів би'::text,'Ок, але якби я сидів в парламенті, я б теж тихенько всьому плескав.'::text),
(372894,41433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero si yo ... en el parlamento, en el fondo también aplaudiría todo.'::text,'estuviera'::text,'estoy'::text,'estaría'::text,'Vale, pero si yo estuviera en el parlamento, en el fondo también aplaudiría todo.'::text),
(372893,41433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, mais si je ... au parlement, moi aussi j''applaudirais tout, discret.'::text,'siégeais'::text,'siège'::text,'siégerais'::text,'Ok, mais si je siégeais au parlement, moi aussi j''applaudirais tout, discret.'::text),
(372896,41433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam da mecliste ..., ben de açıkçası her şeyi alkışlardım.'::text,'otursam'::text,'oturuyorum'::text,'otururdum'::text,'Tamam da mecliste otursam, ben de açıkçası her şeyi alkışlardım.'::text),
(372897,41433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de ha én ... a parlamentben, én is simán tapsolnék mindenre.'::text,'ülnék'::text,'ülök'::text,'ülnék'::text,'Oké, de ha én ülnék a parlamentben, én is simán tapsolnék mindenre.'::text),
(372900,41434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das neue Gesetz ... nach der Abstimmung vom Parlament verabschiedet.'::text,'wurde'::text,'hat'::text,'wird gerade'::text,'Das neue Gesetz wurde nach der Abstimmung vom Parlament verabschiedet.'::text),
(372904,41434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Новий закон ... парламентом після голосування.'::text,'був ухвалений'::text,'ухвалив'::text,'ухвалює'::text,'Новий закон був ухвалений парламентом після голосування.'::text),
(372903,41434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nueva ley ... por el parlamento después de la votación.'::text,'fue aprobada'::text,'aprobó'::text,'está aprobando'::text,'La nueva ley fue aprobada por el parlamento después de la votación.'::text),
(372902,41434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nouvelle loi ... par le parlement après le vote.'::text,'a été adoptée'::text,'a adopté'::text,'est en train d''adopter'::text,'La nouvelle loi a été adoptée par le parlement après le vote.'::text),
(372905,41434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni yasa oylamadan sonra meclis tarafından ...'::text,'kabul edildi'::text,'kabul etti'::text,'kabul ediyor'::text,'Yeni yasa oylamadan sonra meclis tarafından kabul edildi.'::text),
(372906,41434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új törvényt a szavazás után ... a parlament.'::text,'elfogadta'::text,'elfogadta'::text,'fogadja el'::text,'Az új törvényt a szavazás után elfogadta a parlament.'::text),
(372909,41435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Parlament ... den Haushalt 2027 mit klarer Mehrheit.'::text,'verabschiedete'::text,'wurde verabschiedet'::text,'verabschiedend'::text,'Das Parlament verabschiedete den Haushalt 2027 mit klarer Mehrheit.'::text),
(372913,41435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парламент ... бюджет на 2027 рік чіткою більшістю.'::text,'затвердив'::text,'був затверджений'::text,'затвердження'::text,'Парламент затвердив бюджет на 2027 рік чіткою більшістю.'::text),
(372912,41435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El parlamento ... el presupuesto de 2027 por clara mayoría.'::text,'aprobó'::text,'fue aprobado'::text,'aprobando'::text,'El parlamento aprobó el presupuesto de 2027 por clara mayoría.'::text),
(372911,41435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le parlement ... le budget 2027 à une nette majorité.'::text,'a approuvé'::text,'a été approuvé'::text,'approuvant'::text,'Le parlement a approuvé le budget 2027 à une nette majorité.'::text),
(372914,41435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meclis 2027 bütçesini açık bir çoğunlukla ...'::text,'onayladı'::text,'onaylandı'::text,'onaylama'::text,'Meclis 2027 bütçesini açık bir çoğunlukla onayladı.'::text),
(372915,41435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parlament egyértelmű többséggel ... a 2027-es költségvetést.'::text,'jóváhagyta'::text,'jóvá lett hagyva'::text,'jóváhagyás'::text,'A parlament egyértelmű többséggel jóváhagyta a 2027-es költségvetést.'::text),
(372918,41436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle im Parlament applaudieren, also ... das Ergebnis eine gute Nachricht sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Alle im Parlament applaudieren, also muss das Ergebnis eine gute Nachricht sein.'::text),
(372922,41436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі в парламенті аплодують, тож результат ... бути гарною новиною.'::text,'має'::text,'не може'::text,'не повинен'::text,'Усі в парламенті аплодують, тож результат має бути гарною новиною.'::text),
(372921,41436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todos en el parlamento aplauden, así que el resultado ... ser una buena noticia.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Todos en el parlamento aplauden, así que el resultado debe de ser una buena noticia.'::text),
(372920,41436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le parlement applaudit, donc le résultat ... être une bonne nouvelle.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Tout le parlement applaudit, donc le résultat doit être une bonne nouvelle.'::text),
(372923,41436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mecliste herkes alkışlıyor, yani sonuç iyi bir haber ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Mecliste herkes alkışlıyor, yani sonuç iyi bir haber olmalı.'::text),
(372924,41436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parlamentben mindenki tapsol, szóval az eredmény ... jó hír.'::text,'biztosan'::text,'biztosan nem'::text,'nem szabad, hogy'::text,'A parlamentben mindenki tapsol, szóval az eredmény biztosan jó hír.'::text),
(330060,36674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, um 18 Uhr ... er seit zehn Stunden am Stück Leute durch, ohne Witz.'::text,'lässt'::text,'lässt'::text,'lässt'::text,'Alter, um 18 Uhr lässt er seit zehn Stunden am Stück Leute durch, ohne Witz.'::text),
(330064,36674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, до 18:00 він уже десять годин поспіль ... людей, без брехні.'::text,'пропускатиме'::text,'пропустить'::text,'пропускатиме'::text,'Чувак, до 18:00 він уже десять годин поспіль пропускатиме людей, без брехні.'::text),
(330063,36674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, a las 18:00 ya ... a gente diez horas seguidas, sin mentir.'::text,'habrá estado dejando pasar'::text,'dejará pasar'::text,'estará dejando pasar'::text,'Tío, a las 18:00 ya habrá estado dejando pasar a gente diez horas seguidas, sin mentir.'::text),
(330062,36674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, à 18 h, ça ... dix heures d''affilée qu''il laisse passer les gens, sans mentir.'::text,'fera'::text,'fera'::text,'fera'::text,'Mec, à 18 h, ça fera dix heures d''affilée qu''il laisse passer les gens, sans mentir.'::text),
(330065,36674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, saat 18:00''de on saattir aralıksız insanları ..., yalan yok.'::text,'geçiriyor olacak'::text,'geçirecek'::text,'geçiriyor olacak'::text,'Kanka, saat 18:00''de on saattir aralıksız insanları geçiriyor olacak, yalan yok.'::text),
(330066,36674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, este 6-kor már tíz órája ... egyfolytában az embereket, nem kamu.'::text,'engedi át'::text,'átengedi'::text,'engedi át'::text,'Tesó, este 6-kor már tíz órája engedi át egyfolytában az embereket, nem kamu.'::text),
(330069,36675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Beamte sie nicht reingelassen, ... das Meeting um 9 Uhr ohne sie begonnen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Hätte der Beamte sie nicht reingelassen, hätte das Meeting um 9 Uhr ohne sie begonnen.'::text),
(330073,36675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби офіцер її не пропустив, нарада о 9:00 ... без неї.'::text,'почалася б'::text,'почнеться'::text,'почалася'::text,'Якби офіцер її не пропустив, нарада о 9:00 почалася б без неї.'::text),
(330072,36675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el agente no la hubiera dejado entrar, la reunión de las 9:00 ... sin ella.'::text,'habría empezado'::text,'empezará'::text,'empezó'::text,'Si el agente no la hubiera dejado entrar, la reunión de las 9:00 habría empezado sin ella.'::text),
(330071,36675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''agent ne l''avait pas laissée entrer, la réunion de 9 h ... sans elle.'::text,'aurait commencé'::text,'commencera'::text,'a commencé'::text,'Si l''agent ne l''avait pas laissée entrer, la réunion de 9 h aurait commencé sans elle.'::text),
(330074,36675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur onu içeri almasaydı, sabah 9 toplantısı onsuz ...'::text,'başlamış olurdu'::text,'başlayacak'::text,'başladı'::text,'Memur onu içeri almasaydı, sabah 9 toplantısı onsuz başlamış olurdu.'::text),
(330075,36675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tiszt nem engedte volna be, a 9 órás megbeszélés ... nélküle.'::text,'elkezdődött volna'::text,'elkezdődik'::text,'elkezdődött'::text,'Ha a tiszt nem engedte volna be, a 9 órás megbeszélés elkezdődött volna nélküle.'::text),
(330078,36676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Beamte sie nicht durchgelassen, ... sie jetzt noch in der Schlange.'::text,'stünde'::text,'hätte gestanden'::text,'wird stehen'::text,'Hätte der Beamte sie nicht durchgelassen, stünde sie jetzt noch in der Schlange.'::text),
(330082,36676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби офіцер її не пропустив, вона ... у черзі зараз.'::text,'досі стояла б'::text,'стояла б'::text,'стоятиме'::text,'Якби офіцер її не пропустив, вона досі стояла б у черзі зараз.'::text),
(330081,36676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el agente no la hubiera dejado pasar, ahora ... en la cola.'::text,'seguiría esperando'::text,'habría esperado'::text,'esperará'::text,'Si el agente no la hubiera dejado pasar, ahora seguiría esperando en la cola.'::text),
(330080,36676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''agent ne l''avait pas laissée passer, elle ... encore dans la file maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si l''agent ne l''avait pas laissée passer, elle serait encore dans la file maintenant.'::text),
(330083,36676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur onu geçirmeseydi, şu an hâlâ sırada ...'::text,'bekliyor olurdu'::text,'beklemiş olurdu'::text,'bekleyecek'::text,'Memur onu geçirmeseydi, şu an hâlâ sırada bekliyor olurdu.'::text),
(330084,36676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tiszt nem engedte volna át, most is ... a sorban.'::text,'állna'::text,'állt volna'::text,'állni fog'::text,'Ha a tiszt nem engedte volna át, most is állna a sorban.'::text),
(330087,36677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vom Reisenden wird angenommen, dass er sofort ..., wie es typischerweise der Fall ist.'::text,'durchgelassen wurde'::text,'durchließ'::text,'durchlassend'::text,'Vom Reisenden wird angenommen, dass er sofort durchgelassen wurde, wie es typischerweise der Fall ist.'::text),
(330091,36677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що мандрівника ... одразу, як це зазвичай буває.'::text,'пропустили'::text,'пропустити'::text,'пропускаючи'::text,'Вважається, що мандрівника пропустили одразу, як це зазвичай буває.'::text),
(330090,36677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que al viajero ... pasar de inmediato, como suele ocurrir.'::text,'le dejaron'::text,'dejar'::text,'dejando'::text,'Se cree que al viajero le dejaron pasar de inmediato, como suele ocurrir.'::text),
(330089,36677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le voyageur ... passer immédiatement, comme c''est généralement le cas.'::text,'a été autorisé à'::text,'autoriser à'::text,'autorisant à'::text,'On pense que le voyageur a été autorisé à passer immédiatement, comme c''est généralement le cas.'::text),
(330092,36677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolcunun, genellikle olduğu gibi, hemen geçişine ... düşünülüyor.'::text,'izin verilmiş olduğu'::text,'izin vermek'::text,'izin veren'::text,'Yolcunun, genellikle olduğu gibi, hemen geçişine izin verilmiş olduğu düşünülüyor.'::text),
(330093,36677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, hogy az utast azonnal ..., ahogy az jellemzően lenni szokott.'::text,'átengedték'::text,'átengedni'::text,'átengedve'::text,'Úgy vélik, hogy az utast azonnal átengedték, ahogy az jellemzően lenni szokott.'::text),
(330096,36678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte weigerte sich zuerst, sie ...! Ein absoluter Albtraum!'::text,'durchzulassen'::text,'durchzulassen'::text,'ließ durch'::text,'Der Beamte weigerte sich zuerst, sie durchzulassen! Ein absoluter Albtraum!'::text),
(330100,36678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер спочатку відмовився ... її! Абсолютний жах!'::text,'пропустити'::text,'пропускання'::text,'пропустив'::text,'Офіцер спочатку відмовився пропустити її! Абсолютний жах!'::text),
(330099,36678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El agente se negó a ... al principio! ¡Una pesadilla absoluta!'::text,'dejarla pasar'::text,'dejarla pasar'::text,'la dejó pasar'::text,'¡El agente se negó a dejarla pasar al principio! ¡Una pesadilla absoluta!'::text),
(330098,36678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent a d''abord refusé de la ... passer ! Un vrai cauchemar !'::text,'laisser'::text,'laisser'::text,'a laissé'::text,'L''agent a d''abord refusé de la laisser passer ! Un vrai cauchemar !'::text),
(330101,36678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur önce onu ... reddetti! Tam bir kâbus!'::text,'geçirmeyi'::text,'geçirmeyi'::text,'geçirdi'::text,'Memur önce onu geçirmeyi reddetti! Tam bir kâbus!'::text),
(330102,36678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt először nem volt hajlandó ... őt! Abszolút rémálom!'::text,'átengedni'::text,'átengedni'::text,'átengedte'::text,'A tiszt először nem volt hajlandó átengedni őt! Abszolút rémálom!'::text),
(330105,36679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist völlig frei! Der Beamte ... sie durchgelassen haben!'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Sie ist völlig frei! Der Beamte muss sie durchgelassen haben!'::text),
(330109,36679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона абсолютно вільна! Офіцер ... її пропустив!'::text,'точно'::text,'мав би'::text,'не міг'::text,'Вона абсолютно вільна! Офіцер точно її пропустив!'::text),
(330108,36679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Está totalmente libre! ¡El agente ... dejado pasar!'::text,'debe de haberla'::text,'debería haberla'::text,'no puede haberla'::text,'¡Está totalmente libre! ¡El agente debe de haberla dejado pasar!'::text),
(330107,36679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est totalement libre ! L''agent ... la laisser passer !'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Elle est totalement libre ! L''agent a dû la laisser passer !'::text),
(330110,36679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamamen serbest! Memur onu geçirmiş ...!'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Tamamen serbest! Memur onu geçirmiş olmalı!'::text),
(330111,36679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen szabad! A tiszt ... átengedte őt!'::text,'biztosan'::text,'jobb lett volna, ha'::text,'nem lehet, hogy'::text,'Teljesen szabad! A tiszt biztosan átengedte őt!'::text),
(330114,36680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... jemanden so schnell durchgelassen! Absolut unglaublich!'::text,'hatte er'::text,'er hatte'::text,'hat er'::text,'Noch nie hatte er jemanden so schnell durchgelassen! Absolut unglaublich!'::text),
(330118,36680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи раніше ... нікого так швидко! Абсолютно неймовірно!'::text,'не пропускав він'::text,'він не пропускав'::text,'не пропустив він'::text,'Ніколи раніше не пропускав він нікого так швидко! Абсолютно неймовірно!'::text),
(330117,36680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... pasar a nadie tan rápido! ¡Absolutamente increíble!'::text,'había dejado él'::text,'él había dejado'::text,'dejó él'::text,'¡Nunca había dejado él pasar a nadie tan rápido! ¡Absolutamente increíble!'::text),
(330116,36680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... passer qui que ce soit aussi vite ! Absolument incroyable !'::text,'n''avait-il laissé'::text,'il n''avait laissé'::text,'n''a-t-il laissé'::text,'Jamais n''avait-il laissé passer qui que ce soit aussi vite ! Absolument incroyable !'::text),
(330119,36680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç kimseyi bu kadar hızlı ...! Kesinlikle inanılmaz!'::text,'geçirmemişti'::text,'geçirmemişti'::text,'geçirmedi'::text,'Hiç kimseyi bu kadar hızlı geçirmemişti! Kesinlikle inanılmaz!'::text),
(330120,36680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... át senkit ilyen gyorsan! Hihetetlen!'::text,'nem engedett'::text,'nem engedett'::text,'nem engedett'::text,'Soha nem engedett át senkit ilyen gyorsan! Hihetetlen!'::text),
(330123,36681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte ließ seinen Kollegen den Pass ..., bevor er sie durchließ.'::text,'prüfen'::text,'prüfen'::text,'prüfend'::text,'Der Beamte ließ seinen Kollegen den Pass prüfen, bevor er sie durchließ.'::text),
(330127,36681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер попросив колегу ... паспорт, перш ніж пропустив її.'::text,'перевірити'::text,'перевірити'::text,'перевіряючи'::text,'Офіцер попросив колегу перевірити паспорт, перш ніж пропустив її.'::text),
(330126,36681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agente hizo que su compañero ... el pasaporte antes de dejarla pasar.'::text,'revisara'::text,'revisara'::text,'revisando'::text,'El agente hizo que su compañero revisara el pasaporte antes de dejarla pasar.'::text),
(330125,36681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent a fait ... le passeport par son collègue avant de la laisser passer.'::text,'vérifier'::text,'vérifier'::text,'vérifiant'::text,'L''agent a fait vérifier le passeport par son collègue avant de la laisser passer.'::text),
(330128,36681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur onu geçirmeden önce pasaportu meslektaşına ...'::text,'kontrol ettirdi'::text,'kontrol ettirdi'::text,'kontrol ederek'::text,'Memur onu geçirmeden önce pasaportu meslektaşına kontrol ettirdi.'::text),
(330129,36681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt ... a kollégájával az útlevelet, mielőtt átengedte a nőt.'::text,'ellenőriztette'::text,'ellenőriztette'::text,'ellenőrizve'::text,'A tiszt ellenőriztette a kollégájával az útlevelet, mielőtt átengedte a nőt.'::text),
(330132,36682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reisenden in der Schlange wünschen sich, der Beamte ... sie schneller durch.'::text,'ließe'::text,'wird lassen'::text,'lässt'::text,'Die Reisenden in der Schlange wünschen sich, der Beamte ließe sie schneller durch.'::text),
(330136,36682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мандрівники в черзі хотіли б, щоб офіцер ... їх швидше.'::text,'пропускав'::text,'пропускатиме'::text,'пропускає'::text,'Мандрівники в черзі хотіли б, щоб офіцер пропускав їх швидше.'::text),
(330135,36682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los viajeros de la cola desearían que el agente los ... pasar más rápido.'::text,'dejara'::text,'dejará'::text,'deja'::text,'Los viajeros de la cola desearían que el agente los dejara pasar más rápido.'::text),
(330134,36682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les voyageurs dans la file aimeraient que l''agent les ... passer plus vite.'::text,'laisse'::text,'laissera'::text,'laisse'::text,'Les voyageurs dans la file aimeraient que l''agent les laisse passer plus vite.'::text),
(330137,36682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıradaki yolcular memurun onları daha hızlı ... istiyor.'::text,'geçirmesini'::text,'geçireceğini'::text,'geçirdiğini'::text,'Sıradaki yolcular memurun onları daha hızlı geçirmesini istiyor.'::text),
(330138,36682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sorban állók azt szeretnék, ha a tiszt gyorsabban ... át őket.'::text,'engedné'::text,'fogja engedni'::text,'engedi'::text,'A sorban állók azt szeretnék, ha a tiszt gyorsabban engedné át őket.'::text),
(330141,36683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte, ... Stempel sie durchgelassen hat, gibt den Pass zurück.'::text,'dessen'::text,'welcher'::text,'der'::text,'Der Beamte, dessen Stempel sie durchgelassen hat, gibt den Pass zurück.'::text),
(330145,36683,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер, ... печатка дозволила їй пройти, повертає паспорт.'::text,'чия'::text,'який'::text,'що'::text,'Офіцер, чия печатка дозволила їй пройти, повертає паспорт.'::text),
(330144,36683,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agente, ... sello le permitió pasar, devuelve el pasaporte.'::text,'cuyo'::text,'el cual'::text,'que'::text,'El agente, cuyo sello le permitió pasar, devuelve el pasaporte.'::text),
(330143,36683,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent, ... le tampon lui a permis de passer, rend le passeport.'::text,'dont'::text,'lequel'::text,'que'::text,'L''agent, dont le tampon lui a permis de passer, rend le passeport.'::text),
(330146,36683,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damgası onun geçmesine izin ... memur pasaportu geri veriyor.'::text,'veren'::text,'veren'::text,'veren'::text,'Damgası onun geçmesine izin veren memur pasaportu geri veriyor.'::text),
(330147,36683,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt, ... pecsétje átengedte a nőt, visszaadja az útlevelet.'::text,'akinek a'::text,'amely'::text,'ami'::text,'A tiszt, akinek a pecsétje átengedte a nőt, visszaadja az útlevelet.'::text),
(370803,41201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die ganze Nachbarschaft ... Fahnen auf, während der Typ auf seiner Leiter stand.'::text,'hängte gerade'::text,'hängte'::text,'hat aufgehängt'::text,'Bro, die ganze Nachbarschaft hängte gerade Fahnen auf, während der Typ auf seiner Leiter stand.'::text),
(370807,41201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, весь район ... прапори, поки цей чувак був на драбині.'::text,'вивішував'::text,'вивісив'::text,'вивісив'::text,'Бро, весь район вивішував прапори, поки цей чувак був на драбині.'::text),
(370806,41201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, todo el barrio ... banderas mientras este tío estaba en su escalera.'::text,'estaba colgando'::text,'colgó'::text,'ha colgado'::text,'Bro, todo el barrio estaba colgando banderas mientras este tío estaba en su escalera.'::text),
(370805,41201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, tout le quartier ... des drapeaux pendant que ce mec était sur son échelle.'::text,'accrochait'::text,'a accroché'::text,'a accroché'::text,'Frère, tout le quartier accrochait des drapeaux pendant que ce mec était sur son échelle.'::text),
(370808,41201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu adam merdivendeyken bütün mahalle bayrak ...'::text,'asıyordu'::text,'astı'::text,'astı'::text,'Kanka, bu adam merdivendeyken bütün mahalle bayrak asıyordu.'::text),
(370809,41201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az egész környék ... a zászlókat, amíg ez a csávó a létráján volt.'::text,'rakta ki'::text,'kirakta'::text,'kirakta'::text,'Tesó, az egész környék rakta ki a zászlókat, amíg ez a csávó a létráján volt.'::text),
(370812,41202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nachbarschaft ... sich laut Projektzeitplan seit 3 Wochen für die Parade.'::text,'schmückt'::text,'schmückt'::text,'schmückt'::text,'Die Nachbarschaft schmückt sich laut Projektzeitplan seit 3 Wochen für die Parade.'::text),
(370816,41202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Район ... до параду вже 3 тижні, згідно з графіком проєкту.'::text,'прикрашається'::text,'прикрашається'::text,'прикрашається'::text,'Район прикрашається до параду вже 3 тижні, згідно з графіком проєкту.'::text),
(370815,41202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barrio ... para el desfile desde hace 3 semanas, según el cronograma del proyecto.'::text,'se ha estado decorando'::text,'se está decorando'::text,'se decora'::text,'El barrio se ha estado decorando para el desfile desde hace 3 semanas, según el cronograma del proyecto.'::text),
(370814,41202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le quartier ... pour la parade depuis 3 semaines, selon le calendrier du projet.'::text,'se décore'::text,'se décore'::text,'se décore'::text,'Le quartier se décore pour la parade depuis 3 semaines, selon le calendrier du projet.'::text),
(370817,41202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Proje takvimine göre mahalle 3 haftadır geçit töreni için ...'::text,'süsleniyor'::text,'süsleniyor'::text,'süslenir'::text,'Proje takvimine göre mahalle 3 haftadır geçit töreni için süsleniyor.'::text),
(370818,41202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A környék a projekt ütemterve szerint már 3 hete ... a felvonulásra.'::text,'díszíti magát'::text,'díszíti magát'::text,'díszíti magát'::text,'A környék a projekt ütemterve szerint már 3 hete díszíti magát a felvonulásra.'::text),
(370821,41203,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Wimpel an seine Veranda, also bekam die Nachbarschaft Wimpel.'::text,'hängte'::text,'hängte gerade'::text,'hat gehängt'::text,'Er hängte Wimpel an seine Veranda, also bekam die Nachbarschaft Wimpel.'::text),
(370825,41203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... прапорці на ґанок, тож район отримав прапорці.'::text,'повісив'::text,'вішав'::text,'повісив'::text,'Він повісив прапорці на ґанок, тож район отримав прапорці.'::text),
(370824,41203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... banderines en su porche, así que el barrio tuvo banderines.'::text,'colgó'::text,'estaba colgando'::text,'ha colgado'::text,'Él colgó banderines en su porche, así que el barrio tuvo banderines.'::text),
(370823,41203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des fanions sur sa véranda, donc le quartier a eu des fanions.'::text,'a accroché'::text,'accrochait'::text,'a accroché'::text,'Il a accroché des fanions sur sa véranda, donc le quartier a eu des fanions.'::text),
(370826,41203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Verandasına flama ..., böylece mahalle flama sahibi oldu.'::text,'astı'::text,'asıyordu'::text,'astı'::text,'Verandasına flama astı, böylece mahalle flama sahibi oldu.'::text),
(370827,41203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... zászlófüzért a verandájára, így a környék zászlófüzért kapott.'::text,'Felakasztott'::text,'Éppen akasztott'::text,'Felakasztott'::text,'Felakasztott zászlófüzért a verandájára, így a környék zászlófüzért kapott.'::text),
(370830,41204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nachbarschaft ... fast an jedem Haus Fahnen, was auf einen Nationalfeiertag hindeutet.'::text,'hisste'::text,'hisste'::text,'hisst'::text,'Die Nachbarschaft hisste fast an jedem Haus Fahnen, was auf einen Nationalfeiertag hindeutet.'::text),
(370834,41204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Район ... прапори майже на кожен будинок, що вказує на національне свято.'::text,'вивісив'::text,'вивішував'::text,'вивішує'::text,'Район вивісив прапори майже на кожен будинок, що вказує на національне свято.'::text),
(370833,41204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barrio ... banderas en casi todas las casas, lo que indica una fiesta nacional.'::text,'ha puesto'::text,'ha estado poniendo'::text,'pone'::text,'El barrio ha puesto banderas en casi todas las casas, lo que indica una fiesta nacional.'::text),
(370832,41204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le quartier ... des drapeaux sur presque chaque maison, ce qui indique une fête nationale.'::text,'a mis'::text,'a mis'::text,'met'::text,'Le quartier a mis des drapeaux sur presque chaque maison, ce qui indique une fête nationale.'::text),
(370835,41204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mahalle neredeyse her eve bayrak ..., bu da ulusal bir bayramı işaret ediyor.'::text,'astı'::text,'asıyor'::text,'asar'::text,'Mahalle neredeyse her eve bayrak astı, bu da ulusal bir bayramı işaret ediyor.'::text),
(370836,41204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A környék szinte minden házra ... zászlót, ami nemzeti ünnepre utal.'::text,'kitett'::text,'rakott ki'::text,'kitesz'::text,'A környék szinte minden házra kitett zászlót, ami nemzeti ünnepre utal.'::text),
(370839,41205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er runterkletterte, ... sich die Nachbarschaft schon rot-weiß-blau gefärbt! Absolut episch!'::text,'hatte'::text,'hat'::text,'färbt'::text,'Als er runterkletterte, hatte sich die Nachbarschaft schon rot-weiß-blau gefärbt! Absolut episch!'::text),
(370843,41205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він зліз, район уже ... червоно-біло-синім! Абсолютно епічно!'::text,'став'::text,'став'::text,'стає'::text,'Поки він зліз, район уже став червоно-біло-синім! Абсолютно епічно!'::text),
(370842,41205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuando bajó, el barrio ya ... de rojo, blanco y azul! ¡Absolutamente épico!'::text,'se había teñido'::text,'se ha teñido'::text,'se tiñe'::text,'¡Cuando bajó, el barrio ya se había teñido de rojo, blanco y azul! ¡Absolutamente épico!'::text),
(370841,41205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il est descendu, le quartier ... en rouge, blanc et bleu ! Absolument épique !'::text,'s''était paré'::text,'s''est paré'::text,'se pare'::text,'Quand il est descendu, le quartier s''était paré en rouge, blanc et bleu ! Absolument épique !'::text),
(370844,41205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O aşağı inene kadar mahalle kırmızı, beyaz ve maviye ...! Kesinlikle efsane!'::text,'bürünmüştü'::text,'büründü'::text,'bürünüyor'::text,'O aşağı inene kadar mahalle kırmızı, beyaz ve maviye bürünmüştü! Kesinlikle efsane!'::text),
(370845,41205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire lemászott, a környék ... piros-fehér-kékbe! Abszolút epikus!'::text,'öltözött'::text,'öltözött'::text,'öltözik'::text,'Mire lemászott, a környék öltözött piros-fehér-kékbe! Abszolút epikus!'::text),
(370848,41206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist die Nachbarschaft, ... er seit fünfzig Jahren lebt, und er bleibt für immer!'::text,'wo'::text,'welche'::text,'wer'::text,'Das ist die Nachbarschaft, wo er seit fünfzig Jahren lebt, und er bleibt für immer!'::text),
(370852,41206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це район, ... він живе вже п''ятдесят років, і він залишиться тут назавжди!'::text,'де'::text,'який'::text,'хто'::text,'Це район, де він живе вже п''ятдесят років, і він залишиться тут назавжди!'::text),
(370851,41206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este es el barrio ... ha vivido cincuenta años, y se quedará para siempre!'::text,'donde'::text,'que'::text,'quien'::text,'¡Este es el barrio donde ha vivido cincuenta años, y se quedará para siempre!'::text),
(370850,41206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le quartier ... il vit depuis cinquante ans, et il y restera pour toujours !'::text,'où'::text,'que'::text,'qui'::text,'C''est le quartier où il vit depuis cinquante ans, et il y restera pour toujours !'::text),
(370853,41206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burası onun elli yıldır ... mahalle ve sonsuza dek kalacak!'::text,'yaşadığı'::text,'yaşayan'::text,'yaşayan'::text,'Burası onun elli yıldır yaşadığı mahalle ve sonsuza dek kalacak!'::text),
(370854,41206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az a környék, ... ötven éve él, és örökre itt marad!'::text,'ahol'::text,'amely'::text,'aki'::text,'Ez az a környék, ahol ötven éve él, és örökre itt marad!'::text),
(370857,41207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, die Nachbarschaft ... die Straße am Tag davor geschmückt.'::text,'habe'::text,'hat'::text,'schmücke'::text,'Er sagte, die Nachbarschaft habe die Straße am Tag davor geschmückt.'::text),
(370861,41207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що район ... вулицю напередодні.'::text,'прикрасив'::text,'прикрасив'::text,'прикрашає'::text,'Він сказав, що район прикрасив вулицю напередодні.'::text),
(370860,41207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el barrio ... la calle el día anterior.'::text,'había decorado'::text,'ha decorado'::text,'decora'::text,'Dijo que el barrio había decorado la calle el día anterior.'::text),
(370859,41207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que le quartier ... la rue la veille.'::text,'avait décoré'::text,'a décoré'::text,'décore'::text,'Il a dit que le quartier avait décoré la rue la veille.'::text),
(370862,41207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mahallenin sokağı bir gün önce ... söyledi.'::text,'süslediğini'::text,'süslediğini'::text,'süslediğini'::text,'Mahallenin sokağı bir gün önce süslediğini söyledi.'::text),
