(370870,41208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Район ... тихішим, поки всі сусіди не почали прикрашати.'::text,'раніше був'::text,'раніше був'::text,'звик бути'::text,'Район раніше був тихішим, поки всі сусіди не почали прикрашати.'::text),
