(370884,41210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich eine ruhige Nachbarschaft: alle ... seit dem Frühstück Fahnen auf.'::text,'hängen'::text,'hängen'::text,'hängen'::text,'Offensichtlich eine ruhige Nachbarschaft: alle hängen seit dem Frühstück Fahnen auf.'::text),
(370888,41210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, тихий район: усі ... прапори зі сніданку.'::text,'вішають'::text,'вішають'::text,'вішають'::text,'Звісно, тихий район: усі вішають прапори зі сніданку.'::text),
(370887,41210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente un barrio tranquilo: todos ... banderas desde el desayuno.'::text,'llevan colgando'::text,'están colgando'::text,'cuelgan'::text,'Obviamente un barrio tranquilo: todos llevan colgando banderas desde el desayuno.'::text),
