(348964,38774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки ..., коли раптом сотні голубів вибухнули вгору!'::text,'обіймалися'::text,'обнялися'::text,'обнялися'::text,'Чоловіки обіймалися, коли раптом сотні голубів вибухнули вгору!'::text),
(348963,38774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los hombres ... cuando cientos de palomas estallaron de repente hacia arriba!'::text,'se estaban abrazando'::text,'se abrazaron'::text,'se han abrazado'::text,'¡Los hombres se estaban abrazando cuando cientos de palomas estallaron de repente hacia arriba!'::text),
