(349000,38778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Голубів випустили, ... відсвяткувати зустріч двох чоловіків.'::text,'щоб'::text,'щоб'::text,'щоб'::text,'Голубів випустили, щоб відсвяткувати зустріч двох чоловіків.'::text),
(348999,38778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las palomas fueron liberadas ... celebrar el encuentro de los dos hombres.'::text,'a fin de'::text,'para que'::text,'para'::text,'Las palomas fueron liberadas a fin de celebrar el encuentro de los dos hombres.'::text),
(348998,38778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les colombes ont été lâchées ... célébrer la rencontre des deux hommes.'::text,'afin de'::text,'pour que'::text,'pour'::text,'Les colombes ont été lâchées afin de célébrer la rencontre des deux hommes.'::text),
(349001,38778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki adamın buluşmasını kutlamak ... güvercinler salındı.'::text,'için'::text,'diye'::text,'amacıyla'::text,'İki adamın buluşmasını kutlamak için güvercinler salındı.'::text),
(349002,38778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A galambokat azért engedték szabadon, ... megünnepeljék a két férfi találkozását.'::text,'hogy'::text,'hogy'::text,'hogy'::text,'A galambokat azért engedték szabadon, hogy megünnepeljék a két férfi találkozását.'::text),
(349005,38779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, keiner wusste, dass die Tauben alle auf einmal so rausfliegen ..., echt.'::text,'würden'::text,'werden'::text,'werden'::text,'Alter, keiner wusste, dass die Tauben alle auf einmal so rausfliegen würden, echt.'::text),
(349009,38779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ніхто не знав, що голуби ... отак усі разом, реально.'::text,'вилетять'::text,'вилетять'::text,'збираються вилетіти'::text,'Бро, ніхто не знав, що голуби вилетять отак усі разом, реально.'::text),
(349008,38779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, nadie sabía que las palomas ... salir volando todas a la vez así, en serio.'::text,'iban a'::text,'van a'::text,'están yendo a'::text,'Tío, nadie sabía que las palomas iban a salir volando todas a la vez así, en serio.'::text),
(349007,38779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, personne ne savait que les colombes ... s''envoler toutes d''un coup comme ça, sérieux.'::text,'allaient'::text,'vont'::text,'sont en train de'::text,'Frère, personne ne savait que les colombes allaient s''envoler toutes d''un coup comme ça, sérieux.'::text),
(349010,38779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kimse güvercinlerin hepsinin birden öyle ... bilmiyordu, cidden.'::text,'uçacağını'::text,'uçacağını'::text,'uçmak üzere olduğunu'::text,'Kanka, kimse güvercinlerin hepsinin birden öyle uçacağını bilmiyordu, cidden.'::text),
(349011,38779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, senki sem tudta, hogy a galambok mind egyszerre így ... ki, komolyan.'::text,'repülnek'::text,'fognak repülni'::text,'repülnek'::text,'Tesó, senki sem tudta, hogy a galambok mind egyszerre így repülnek ki, komolyan.'::text),
(349014,38780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aktuell ... 200 Tauben über dem Denkmal, laut Event-Roadmap.'::text,'fliegen'::text,'fliegen'::text,'sind geflogen'::text,'Aktuell fliegen 200 Tauben über dem Denkmal, laut Event-Roadmap.'::text),
(349018,38780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз 200 голубів ... над пам''ятником, згідно з планом заходу.'::text,'летять'::text,'літають'::text,'пролетіли'::text,'Зараз 200 голубів летять над пам''ятником, згідно з планом заходу.'::text),
(349017,38780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, 200 palomas ... sobre el monumento, según la hoja de ruta del evento.'::text,'están volando'::text,'vuelan'::text,'han volado'::text,'Ahora mismo, 200 palomas están volando sobre el monumento, según la hoja de ruta del evento.'::text),
(349016,38780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, 200 colombes ... au-dessus du monument, conformément à la feuille de route de l''événement.'::text,'volent'::text,'volent'::text,'ont volé'::text,'En ce moment, 200 colombes volent au-dessus du monument, conformément à la feuille de route de l''événement.'::text),
(349019,38780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Etkinlik yol haritasına göre şu anda 200 güvercin anıtın üzerinde ...'::text,'uçuyor'::text,'uçar'::text,'uçtu'::text,'Etkinlik yol haritasına göre şu anda 200 güvercin anıtın üzerinde uçuyor.'::text),
(349020,38780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg 200 galamb ... az emlékmű fölött, az esemény ütemterve szerint.'::text,'repül'::text,'repül'::text,'repült'::text,'Jelenleg 200 galamb repül az emlékmű fölött, az esemény ütemterve szerint.'::text),
(349023,38781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tauben ... eine Stunde in den Körben gesessen, bevor die Mädchen sie rausließen.'::text,'hatten'::text,'haben'::text,'sitzen'::text,'Die Tauben hatten eine Stunde in den Körben gesessen, bevor die Mädchen sie rausließen.'::text),
(349027,38781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Голуби ... в кошиках годину, перш ніж дівчата їх випустили.'::text,'сиділи'::text,'сидять'::text,'сидять'::text,'Голуби сиділи в кошиках годину, перш ніж дівчата їх випустили.'::text),
(349026,38781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las palomas ... en las cestas una hora antes de que las chicas las soltaran.'::text,'habían estado'::text,'han estado'::text,'están'::text,'Las palomas habían estado en las cestas una hora antes de que las chicas las soltaran.'::text),
(349025,38781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les colombes ... dans les paniers depuis une heure quand les filles les ont libérées.'::text,'étaient'::text,'sont'::text,'sont'::text,'Les colombes étaient dans les paniers depuis une heure quand les filles les ont libérées.'::text),
(349028,38781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızlar onları salmadan önce güvercinler bir saattir sepetlerde ...'::text,'oturuyordu'::text,'oturuyor'::text,'oturuyor'::text,'Kızlar onları salmadan önce güvercinler bir saattir sepetlerde oturuyordu.'::text),
(349029,38781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A galambok egy órán át ... a kosarakban, mielőtt a lányok kiengedték őket.'::text,'ültek'::text,'ülnek'::text,'ülnek'::text,'A galambok egy órán át ültek a kosarakban, mielőtt a lányok kiengedték őket.'::text),
(393015,43669,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder einen endlosen Streifen Apfelschale! Es hört nie, nie auf!'::text,'schält'::text,'schält'::text,'schält'::text,'Morgen um diese Zeit schält sie wieder einen endlosen Streifen Apfelschale! Es hört nie, nie auf!'::text),
(393019,43669,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... ще одну нескінченну смужку яблучної шкірки! Це ніколи, ніколи не закінчиться!'::text,'зрізатиме'::text,'зріже'::text,'зрізає'::text,'Завтра в цей час вона зрізатиме ще одну нескінченну смужку яблучної шкірки! Це ніколи, ніколи не закінчиться!'::text),
(393018,43669,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... otra tira interminable de piel de manzana! ¡Nunca, jamás se acaba!'::text,'estará pelando'::text,'pelará'::text,'pela'::text,'¡Mañana a esta hora estará pelando otra tira interminable de piel de manzana! ¡Nunca, jamás se acaba!'::text),
(393017,43669,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore une bande interminable de peau de pomme ! Ça ne finit jamais, jamais !'::text,'sera en train d''éplucher'::text,'épluchera'::text,'épluche'::text,'Demain à la même heure, elle sera en train d''éplucher encore une bande interminable de peau de pomme ! Ça ne finit jamais, jamais !'::text),
(393020,43669,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine bitmek bilmeyen bir elma kabuğu şeridi ...! Hiç ama hiç bitmiyor!'::text,'soyuyor olacak'::text,'soyacak'::text,'soyar'::text,'Yarın bu saatlerde yine bitmek bilmeyen bir elma kabuğu şeridi soyuyor olacak! Hiç ama hiç bitmiyor!'::text),
(393021,43669,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint egy végtelen almahéjcsíkot ...! Soha, de soha nem ér véget!'::text,'fog hámozni'::text,'hámoz le'::text,'hámoz'::text,'Holnap ilyenkor megint egy végtelen almahéjcsíkot fog hámozni! Soha, de soha nem ér véget!'::text),
(393033,43671,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du den Apfel langsam drehst, ... die Schale in einem langen Streifen ab.'::text,'geht'::text,'ging'::text,'würde gehen'::text,'Wenn du den Apfel langsam drehst, geht die Schale in einem langen Streifen ab.'::text),
(393037,43671,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо повільно крутити яблуко, шкірка ... однією довгою смужкою.'::text,'знімається'::text,'знялася'::text,'знімалася б'::text,'Якщо повільно крутити яблуко, шкірка знімається однією довгою смужкою.'::text),
(393036,43671,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si giras la manzana despacio, la piel ... en una sola tira larga.'::text,'sale'::text,'salió'::text,'saldría'::text,'Si giras la manzana despacio, la piel sale en una sola tira larga.'::text),
(393035,43671,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu tournes la pomme lentement, la peau ... en une seule longue bande.'::text,'se détache'::text,'s''est détachée'::text,'se détacherait'::text,'Si tu tournes la pomme lentement, la peau se détache en une seule longue bande.'::text),
(393038,43671,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elmayı yavaşça çevirirsen kabuk tek uzun bir şerit halinde ...'::text,'çıkar'::text,'çıktı'::text,'çıkardı'::text,'Elmayı yavaşça çevirirsen kabuk tek uzun bir şerit halinde çıkar.'::text),
(393039,43671,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lassan forgatod az almát, a héj egy hosszú csíkban ... le.'::text,'jön'::text,'jött'::text,'jönne'::text,'Ha lassan forgatod az almát, a héj egy hosszú csíkban jön le.'::text),
(393042,43672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... mit einem kleinen Messer einen langen Streifen Schale vom Apfel.'::text,'schnitt'::text,'wurde geschnitten'::text,'schneidend'::text,'Die Frau schnitt mit einem kleinen Messer einen langen Streifen Schale vom Apfel.'::text),
(393046,43672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... з яблука довгу смужку шкірки маленьким ножем.'::text,'зрізала'::text,'була зрізана'::text,'зрізання'::text,'Жінка зрізала з яблука довгу смужку шкірки маленьким ножем.'::text),
(393045,43672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... una larga tira de piel de la manzana con un cuchillo pequeño.'::text,'cortó'::text,'fue cortada'::text,'cortando'::text,'La mujer cortó una larga tira de piel de la manzana con un cuchillo pequeño.'::text),
(393044,43672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... une longue bande de peau de la pomme avec un petit couteau.'::text,'a coupé'::text,'a été coupée'::text,'coupant'::text,'La femme a coupé une longue bande de peau de la pomme avec un petit couteau.'::text),
(393047,43672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın küçük bir bıçakla elmadan uzun bir kabuk şeridi ...'::text,'kesti'::text,'kesildi'::text,'kesme'::text,'Kadın küçük bir bıçakla elmadan uzun bir kabuk şeridi kesti.'::text),
(393048,43672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő egy kis késsel ... egy hosszú héjcsíkot az almáról.'::text,'levágott'::text,'le lett vágva'::text,'levágás'::text,'A nő egy kis késsel levágott egy hosszú héjcsíkot az almáról.'::text),
(393051,43673,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Streifen berührt fast den Boden, also ... er sehr lang sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Der Streifen berührt fast den Boden, also muss er sehr lang sein.'::text),
(393055,43673,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Смужка майже торкається підлоги, тож вона ... бути дуже довгою.'::text,'має'::text,'не може'::text,'не повинна'::text,'Смужка майже торкається підлоги, тож вона має бути дуже довгою.'::text),
(393054,43673,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tira casi toca el suelo, así que ... ser muy larga.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'La tira casi toca el suelo, así que debe de ser muy larga.'::text),
(393053,43673,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bande touche presque le sol, donc elle ... être très longue.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'La bande touche presque le sol, donc elle doit être très longue.'::text),
(393056,43673,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şerit neredeyse yere değiyor, yani çok uzun ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Şerit neredeyse yere değiyor, yani çok uzun olmalı.'::text),
(393057,43673,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csík majdnem a földet éri, szóval ... nagyon hosszú.'::text,'biztosan'::text,'biztosan nem'::text,'nem szabad, hogy'::text,'A csík majdnem a földet éri, szóval biztosan nagyon hosszú.'::text),
(393060,43674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, der Streifen, ... du heute geschält hast, ist länger als deine Schürze. Beeindruckend.'::text,'den'::text,'wer'::text,'dessen'::text,'Ehrlich, der Streifen, den du heute geschält hast, ist länger als deine Schürze. Beeindruckend.'::text),
(393064,43674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, смужка, ... ти сьогодні зрізала, довша за твій фартух. Вражає.'::text,'яку'::text,'хто'::text,'чия'::text,'Чесно, смужка, яку ти сьогодні зрізала, довша за твій фартух. Вражає.'::text),
(393063,43674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, la tira ... pelaste hoy es más larga que tu delantal. Impresionante.'::text,'que'::text,'quien'::text,'cuya'::text,'La verdad, la tira que pelaste hoy es más larga que tu delantal. Impresionante.'::text),
(393062,43674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la bande ... tu as épluchée aujourd''hui est plus longue que ton tablier. Impressionnant.'::text,'que'::text,'qui'::text,'dont'::text,'Franchement, la bande que tu as épluchée aujourd''hui est plus longue que ton tablier. Impressionnant.'::text),
(393065,43674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bugün ... şerit önlüğünden daha uzun. Etkileyici.'::text,'soyduğun'::text,'soyan'::text,'soyduğun'::text,'Açıkçası, bugün soyduğun şerit önlüğünden daha uzun. Etkileyici.'::text),
(393066,43674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a csík, ... ma lehámoztál, hosszabb, mint a köténted. Lenyűgöző.'::text,'amit'::text,'aki'::text,'akinek a'::text,'Őszintén, a csík, amit ma lehámoztál, hosszabb, mint a köténted. Lenyűgöző.'::text),
(393069,43675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... den ganzen Apfel in einem Streifen, und das hast du auch gemacht. Respekt.'::text,'schälst'::text,'schälst'::text,'schälst'::text,'Du hast gesagt, du schälst den ganzen Apfel in einem Streifen, und das hast du auch gemacht. Respekt.'::text),
(393073,43675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказала, що ... все яблуко однією смужкою, і так і зробила. Респект.'::text,'почистиш'::text,'почистиш'::text,'чистиш'::text,'Ти сказала, що почистиш все яблуко однією смужкою, і так і зробила. Респект.'::text),
(393072,43675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... la manzana entera en una sola tira, y lo hiciste. Respeto.'::text,'pelarías'::text,'pelarás'::text,'pelas'::text,'Dijiste que pelarías la manzana entera en una sola tira, y lo hiciste. Respeto.'::text),
(393071,43675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... toute la pomme en une seule bande, et tu l''as fait. Respect.'::text,'éplucherais'::text,'éplucheras'::text,'épluches'::text,'Tu as dit que tu éplucherais toute la pomme en une seule bande, et tu l''as fait. Respect.'::text),
(393074,43675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün elmayı tek şeritte ... söyledin ve yaptın. Saygı.'::text,'soyacağını'::text,'soyacağını'::text,'soyduğunu'::text,'Bütün elmayı tek şeritte soyacağını söyledin ve yaptın. Saygı.'::text),
(393075,43675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy egy csíkban ... az egész almát, és meg is csináltad. Le a kalappal.'::text,'meghámozod'::text,'meg fogod hámozni'::text,'hámozod'::text,'Azt mondtad, hogy egy csíkban meghámozod az egész almát, és meg is csináltad. Le a kalappal.'::text),
(393078,43676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich hat sie Äpfel ... in winzigen Stücken geschält, nie in einem Streifen.'::text,'früher'::text,'gewohnheitsmäßig'::text,'früher'::text,'Natürlich hat sie Äpfel früher in winzigen Stücken geschält, nie in einem Streifen.'::text),
(393082,43676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, вона ... чистила яблука дрібними шматочками, ніколи однією смужкою.'::text,'раніше'::text,'звикла'::text,'раніше'::text,'Звісно, вона раніше чистила яблука дрібними шматочками, ніколи однією смужкою.'::text),
(393081,43676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, ella ... pelar manzanas en trocitos, nunca en una sola tira.'::text,'solía'::text,'estaba acostumbrada a'::text,'solía'::text,'Claro, ella solía pelar manzanas en trocitos, nunca en una sola tira.'::text),
(393080,43676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, elle ... les pommes en tout petits morceaux, jamais en une seule bande.'::text,'épluchait autrefois'::text,'avait l''habitude d''éplucher'::text,'épluchait autrefois'::text,'Bien sûr, elle épluchait autrefois les pommes en tout petits morceaux, jamais en une seule bande.'::text),
(393083,43676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, elmaları eskiden minik parçalar halinde ..., asla tek şeritte değil.'::text,'soyardı'::text,'soymaya alışkındı'::text,'soyardı'::text,'Tabii ki, elmaları eskiden minik parçalar halinde soyardı, asla tek şeritte değil.'::text),
(393084,43676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, ő régen apró darabokban ... az almát, sosem egy csíkban.'::text,'szokta hámozni'::text,'hozzá volt szokva, hogy hámozza'::text,'szokta hámozni'::text,'Persze, ő régen apró darabokban szokta hámozni az almát, sosem egy csíkban.'::text),
(393087,43677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie muss einfach ... auf diesen Streifen. Natürlich nichts Besonderes.'::text,'starren'::text,'starren'::text,'starren'::text,'Sie muss einfach starren auf diesen Streifen. Natürlich nichts Besonderes.'::text),
(393091,43677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не може не ... на цю смужку. Звісно, нічого особливого.'::text,'дивитися'::text,'дивитися'::text,'дивитися'::text,'Вона не може не дивитися на цю смужку. Звісно, нічого особливого.'::text),
(393090,43677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede evitar ... esa tira. Obviamente, nada especial.'::text,'mirar fijamente'::text,'mirar fijamente'::text,'mirar fijamente'::text,'No puede evitar mirar fijamente esa tira. Obviamente, nada especial.'::text),
(393089,43677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ne peut pas s''empêcher de ... cette bande. Évidemment, rien de spécial.'::text,'fixer'::text,'fixer'::text,'fixer'::text,'Elle ne peut pas s''empêcher de fixer cette bande. Évidemment, rien de spécial.'::text),
(393092,43677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şeride ... kendini alamıyor. Tabii ki özel bir şey yok.'::text,'bakmaktan'::text,'bakmaktan'::text,'bakmaktan'::text,'O şeride bakmaktan kendini alamıyor. Tabii ki özel bir şey yok.'::text),
(393093,43677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudja megállni, hogy ne ... azt a csíkot. Nyilván semmi különös.'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'Nem tudja megállni, hogy ne bámulja azt a csíkot. Nyilván semmi különös.'::text),
(393096,43678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Streifen bis unter ihre Knie. Offensichtlich ein ganz gewöhnlicher Apfel.'::text,'hängt'::text,'hängt'::text,'hing'::text,'Gerade hängt der Streifen bis unter ihre Knie. Offensichtlich ein ganz gewöhnlicher Apfel.'::text),
(393100,43678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз смужка ... нижче її колін. Звісно, цілком звичайне яблуко.'::text,'звисає'::text,'звисає'::text,'звисла'::text,'Саме зараз смужка звисає нижче її колін. Звісно, цілком звичайне яблуко.'::text),
(393099,43678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo la tira ... por debajo de sus rodillas. Obviamente, una manzana normalísima.'::text,'está colgando'::text,'cuelga'::text,'ha colgado'::text,'Ahora mismo la tira está colgando por debajo de sus rodillas. Obviamente, una manzana normalísima.'::text),
(393098,43678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la bande ... sous ses genoux. Évidemment, une pomme tout à fait ordinaire.'::text,'pend'::text,'pend'::text,'a pendu'::text,'En ce moment, la bande pend sous ses genoux. Évidemment, une pomme tout à fait ordinaire.'::text),
(393101,43678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda şerit dizlerinin altına kadar ..., tabii ki çok sıradan bir elma.'::text,'sarkıyor'::text,'sarkar'::text,'sarktı'::text,'Şu anda şerit dizlerinin altına kadar sarkıyor, tabii ki çok sıradan bir elma.'::text),
(393102,43678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen most a csík ... a térde alá. Nyilván egy teljesen hétköznapi alma.'::text,'lóg'::text,'lóg'::text,'lógott'::text,'Éppen most a csík lóg a térde alá. Nyilván egy teljesen hétköznapi alma.'::text),
(376347,41817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt: Ich verspreche, ich ... mein Rezept diesen Monat pünktlich ab.'::text,'hole'::text,'hole'::text,'hole'::text,'Hör zu, er hat mir gesagt: Ich verspreche, ich hole mein Rezept diesen Monat pünktlich ab.'::text),
(376351,41817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені: обіцяю, цього місяця я ... свій рецепт вчасно.'::text,'заберу'::text,'забиратиму'::text,'забираю'::text,'Слухай, він сказав мені: обіцяю, цього місяця я заберу свій рецепт вчасно.'::text),
(376350,41817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo: te prometo que este mes ... mi receta a tiempo.'::text,'recogeré'::text,'estaré recogiendo'::text,'recojo'::text,'Escucha, me dijo: te prometo que este mes recogeré mi receta a tiempo.'::text),
(376349,41817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit : je promets que ce mois-ci, je ... mon ordonnance à temps.'::text,'récupérerai'::text,'serai en train de récupérer'::text,'récupère'::text,'Écoute, il m''a dit : je promets que ce mois-ci, je récupérerai mon ordonnance à temps.'::text),
(376352,41817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki: Söz veriyorum, bu ay reçetemi zamanında ...'::text,'alacağım'::text,'alıyor olacağım'::text,'alırım'::text,'Dinle, bana dedi ki: Söz veriyorum, bu ay reçetemi zamanında alacağım.'::text),
(376353,41817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta: megígérem, hogy ebben a hónapban időben ... a receptemet.'::text,'kiváltom'::text,'ki fogom váltani'::text,'váltom ki'::text,'Figyelj, azt mondta: megígérem, hogy ebben a hónapban időben kiváltom a receptemet.'::text),
(376356,41818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du so ein ordentliches Rezept mitbringst, ... dir die Apotheker sofort. Smooth.'::text,'helfen'::text,'halfen'::text,'würden helfen'::text,'Wenn du so ein ordentliches Rezept mitbringst, helfen dir die Apotheker sofort. Smooth.'::text),
(376360,41818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти приносиш такий акуратний рецепт, фармацевти ... тобі одразу. Стильно.'::text,'допомагають'::text,'допомогли'::text,'допомогли б'::text,'Якщо ти приносиш такий акуратний рецепт, фармацевти допомагають тобі одразу. Стильно.'::text),
(376359,41818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si traes una receta tan ordenada, los farmacéuticos te ... enseguida. Qué estilo.'::text,'ayudan'::text,'ayudaron'::text,'ayudarían'::text,'Si traes una receta tan ordenada, los farmacéuticos te ayudan enseguida. Qué estilo.'::text),
(376358,41818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu apportes une ordonnance aussi nette, les pharmaciens ... tout de suite. La classe.'::text,'t''aident'::text,'t''ont aidé'::text,'t''aideraient'::text,'Si tu apportes une ordonnance aussi nette, les pharmaciens t''aident tout de suite. La classe.'::text),
(376361,41818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle düzgün bir reçete getirirsen eczacılar sana hemen ..., havalı.'::text,'yardım eder'::text,'yardım etti'::text,'yardım ederdi'::text,'Böyle düzgün bir reçete getirirsen eczacılar sana hemen yardım eder, havalı.'::text),
(376362,41818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ilyen rendes receptet hozol, a gyógyszerészek azonnal ... neked. Laza.'::text,'segítenek'::text,'segítettek'::text,'segítenének'::text,'Ha ilyen rendes receptet hozol, a gyógyszerészek azonnal segítenek neked. Laza.'::text),
(376365,41819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du das Rezept so selbstbewusst rüberreichst, ... sie die Packung schnell. Respekt.'::text,'findet'::text,'fände'::text,'fand'::text,'Wenn du das Rezept so selbstbewusst rüberreichst, findet sie die Packung schnell. Respekt.'::text),
(376369,41819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти подаси рецепт так упевнено, вона ... коробку швидко. Респект.'::text,'знайде'::text,'знайшла б'::text,'знайшла'::text,'Якщо ти подаси рецепт так упевнено, вона знайде коробку швидко. Респект.'::text),
(376368,41819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si entregas la receta con esa seguridad, ella ... la caja rápido. Respeto.'::text,'encontrará'::text,'encontraría'::text,'encontró'::text,'Si entregas la receta con esa seguridad, ella encontrará la caja rápido. Respeto.'::text),
(376367,41819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu tends l''ordonnance avec cette assurance, elle ... la boîte vite. Respect.'::text,'trouvera'::text,'trouverait'::text,'a trouvé'::text,'Si tu tends l''ordonnance avec cette assurance, elle trouvera la boîte vite. Respect.'::text),
(376370,41819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reçeteyi o özgüvenle uzatırsan kutuyu hızlıca ..., saygı.'::text,'bulacak'::text,'bulurdu'::text,'buldu'::text,'Reçeteyi o özgüvenle uzatırsan kutuyu hızlıca bulacak, saygı.'::text),
(376371,41819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ilyen magabiztosan adod át a receptet, gyorsan ... a dobozt. Le a kalappal.'::text,'megtalálja'::text,'megtalálná'::text,'megtalálta'::text,'Ha ilyen magabiztosan adod át a receptet, gyorsan megtalálja a dobozt. Le a kalappal.'::text),
(376374,41820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Rezept leserlich geschrieben ..., würde sie die Packung sofort finden, natürlich.'::text,'wäre'::text,'ist'::text,'sein würde'::text,'Wenn das Rezept leserlich geschrieben wäre, würde sie die Packung sofort finden, natürlich.'::text),
(376378,41820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби рецепт ... написаний розбірливо, вона б знайшла коробку миттєво, звісно.'::text,'був'::text,'є'::text,'був би'::text,'Якби рецепт був написаний розбірливо, вона б знайшла коробку миттєво, звісно.'::text),
(376377,41820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la receta ... escrita con letra clara, ella encontraría la caja al instante, claro.'::text,'estuviera'::text,'está'::text,'estaría'::text,'Si la receta estuviera escrita con letra clara, ella encontraría la caja al instante, claro.'::text),
(376376,41820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''ordonnance ... écrite lisiblement, elle trouverait la boîte tout de suite, bien sûr.'::text,'était'::text,'est'::text,'serait'::text,'Si l''ordonnance était écrite lisiblement, elle trouverait la boîte tout de suite, bien sûr.'::text),
(376379,41820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reçete okunaklı yazılmış ..., kutuyu anında bulurdu, tabii ki.'::text,'olsa'::text,'ise'::text,'olurdu'::text,'Reçete okunaklı yazılmış olsa, kutuyu anında bulurdu, tabii ki.'::text),
(376380,41820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a recept olvasható kézírással ... írva, azonnal megtalálná a dobozt, persze.'::text,'lenne'::text,'van'::text,'lenne'::text,'Ha a recept olvasható kézírással lenne írva, azonnal megtalálná a dobozt, persze.'::text),
(376383,41821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Arbeit, Doktor: Dieses Rezept ... in etwa vier Sekunden geschrieben.'::text,'wurde'::text,'schrieb'::text,'schreibt'::text,'Super Arbeit, Doktor: Dieses Rezept wurde in etwa vier Sekunden geschrieben.'::text),
(376387,41821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, лікарю: цей рецепт ... приблизно за чотири секунди.'::text,'був написаний'::text,'написав'::text,'пише'::text,'Чудова робота, лікарю: цей рецепт був написаний приблизно за чотири секунди.'::text),
(376386,41821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, doctor: esta receta ... en unos cuatro segundos.'::text,'fue escrita'::text,'escribió'::text,'está escribiendo'::text,'Buen trabajo, doctor: esta receta fue escrita en unos cuatro segundos.'::text),
(376385,41821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, docteur : cette ordonnance ... en quatre secondes environ.'::text,'a été écrite'::text,'a écrit'::text,'est en train d''écrire'::text,'Bravo, docteur : cette ordonnance a été écrite en quatre secondes environ.'::text),
(376388,41821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, doktor: bu reçete yaklaşık dört saniyede ...'::text,'yazıldı'::text,'yazdı'::text,'yazıyor'::text,'Harika iş, doktor: bu reçete yaklaşık dört saniyede yazıldı.'::text),
(376389,41821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, doktor úr: ezt a receptet nagyjából négy másodperc alatt ...'::text,'írták meg'::text,'megírta'::text,'írja'::text,'Szép munka, doktor úr: ezt a receptet nagyjából négy másodperc alatt írták meg.'::text),
(376392,41822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Apothekerin ... das Rezept sorgfältig, bevor sie sich zu den Regalen umdrehte.'::text,'las'::text,'wurde gelesen'::text,'lesend'::text,'Die Apothekerin las das Rezept sorgfältig, bevor sie sich zu den Regalen umdrehte.'::text),
(376396,41822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фармацевтка уважно ... рецепт, перш ніж повернулася до полиць.'::text,'прочитала'::text,'була прочитана'::text,'читання'::text,'Фармацевтка уважно прочитала рецепт, перш ніж повернулася до полиць.'::text),
(376395,41822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La farmacéutica ... la receta con atención antes de volverse hacia las estanterías.'::text,'leyó'::text,'fue leída'::text,'leyendo'::text,'La farmacéutica leyó la receta con atención antes de volverse hacia las estanterías.'::text),
(376394,41822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pharmacienne ... l''ordonnance attentivement avant de se tourner vers les étagères.'::text,'a lu'::text,'a été lue'::text,'lisant'::text,'La pharmacienne a lu l''ordonnance attentivement avant de se tourner vers les étagères.'::text),
(376397,41822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eczacı raflara dönmeden önce reçeteyi dikkatlice ...'::text,'okudu'::text,'okundu'::text,'okuma'::text,'Eczacı raflara dönmeden önce reçeteyi dikkatlice okudu.'::text),
(376398,41822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyógyszerész figyelmesen ... a receptet, mielőtt a polcok felé fordult.'::text,'elolvasta'::text,'el lett olvasva'::text,'olvasás'::text,'A gyógyszerész figyelmesen elolvasta a receptet, mielőtt a polcok felé fordult.'::text),
(376401,41823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, das Rezept ... für was Kleines sein, er grinst doch, echt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Nee, das Rezept muss für was Kleines sein, er grinst doch, echt.'::text),
(376405,41823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, цей рецепт ... бути на щось дрібне, він же усміхається, реально.'::text,'має'::text,'не може'::text,'повинен'::text,'Не, цей рецепт має бути на щось дрібне, він же усміхається, реально.'::text),
(376404,41823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, esa receta ... ser para algo pequeño, está sonriendo, en serio.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Qué va, esa receta debe de ser para algo pequeño, está sonriendo, en serio.'::text),
(376403,41823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, cette ordonnance ... être pour un truc léger, il sourit, sérieux.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Nan, cette ordonnance doit être pour un truc léger, il sourit, sérieux.'::text),
(376406,41823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, o reçete ufak bir şey için ..., adam gülümsüyor, cidden.'::text,'olmalı'::text,'olamaz'::text,'olsa gerek'::text,'Yok ya, o reçete ufak bir şey için olmalı, adam gülümsüyor, cidden.'::text),
(376407,41823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, az a recept ... valami apróságra szól, hiszen mosolyog, komolyan.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'Á, az a recept biztosan valami apróságra szól, hiszen mosolyog, komolyan.'::text),
(376410,41824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Apothekerin, ... Ziel 80 Rezepte pro Schicht sind, fand seine Packung schnell.'::text,'deren'::text,'die'::text,'welche'::text,'Die Apothekerin, deren Ziel 80 Rezepte pro Schicht sind, fand seine Packung schnell.'::text),
(376414,41824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фармацевтка, ... ціль — 80 рецептів за зміну, швидко знайшла його коробку.'::text,'чия'::text,'яка'::text,'котра'::text,'Фармацевтка, чия ціль — 80 рецептів за зміну, швидко знайшла його коробку.'::text),
(376413,41824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La farmacéutica, ... objetivo es de 80 recetas por turno, encontró su caja rápido.'::text,'cuyo'::text,'quien'::text,'la cual'::text,'La farmacéutica, cuyo objetivo es de 80 recetas por turno, encontró su caja rápido.'::text),
(376412,41824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pharmacienne, ... l''objectif est de 80 ordonnances par service, a vite trouvé sa boîte.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La pharmacienne, dont l''objectif est de 80 ordonnances par service, a vite trouvé sa boîte.'::text),
(376415,41824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefi vardiya başına 80 reçete ... eczacı onun kutusunu hızla buldu.'::text,'olan'::text,'olan'::text,'olan'::text,'Hedefi vardiya başına 80 reçete olan eczacı onun kutusunu hızla buldu.'::text),
(376416,41824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyógyszerész, ... célja műszakonként 80 recept, gyorsan megtalálta a dobozát.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A gyógyszerész, akinek a célja műszakonként 80 recept, gyorsan megtalálta a dobozát.'::text),
(376419,41825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Apothekerin sagte, das Rezept ... am Tag davor von seinem Arzt gekommen.'::text,'sei'::text,'ist'::text,'war'::text,'Die Apothekerin sagte, das Rezept sei am Tag davor von seinem Arzt gekommen.'::text),
(376423,41825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фармацевтка сказала, що рецепт ... від його лікаря напередодні.'::text,'надійшов'::text,'надійшов'::text,'надходить'::text,'Фармацевтка сказала, що рецепт надійшов від його лікаря напередодні.'::text),
(376422,41825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La farmacéutica dijo que la receta ... de su médico el día anterior.'::text,'había llegado'::text,'ha llegado'::text,'llega'::text,'La farmacéutica dijo que la receta había llegado de su médico el día anterior.'::text),
(376421,41825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pharmacienne a dit que l''ordonnance ... de son médecin la veille.'::text,'était arrivée'::text,'est arrivée'::text,'arrive'::text,'La pharmacienne a dit que l''ordonnance était arrivée de son médecin la veille.'::text),
(376424,41825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eczacı, reçetenin bir gün önce doktorundan ... söyledi.'::text,'geldiğini'::text,'geldiğini'::text,'geldiğini'::text,'Eczacı, reçetenin bir gün önce doktorundan geldiğini söyledi.'::text),
(376425,41825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyógyszerész azt mondta, hogy a recept előző nap ... az orvosától.'::text,'jött'::text,'jött'::text,'jön'::text,'A gyógyszerész azt mondta, hogy a recept előző nap jött az orvosától.'::text),
(376428,41826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Teenager ... er jede Woche Rezepte für seine Oma ab.'::text,'holte'::text,'holte'::text,'holte'::text,'Als Teenager holte er jede Woche Rezepte für seine Oma ab.'::text),
(376432,41826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підлітком він ... щотижня забирати рецепти для бабусі.'::text,'ходив'::text,'мав звичку'::text,'звик'::text,'Підлітком він ходив щотижня забирати рецепти для бабусі.'::text),
(376431,41826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De adolescente, ... recoger recetas para su abuela cada semana.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'De adolescente, solía recoger recetas para su abuela cada semana.'::text),
(376430,41826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ado, il ... chercher les ordonnances de sa grand-mère chaque semaine.'::text,'allait'::text,'allait'::text,'avait l''habitude d''aller'::text,'Ado, il allait chercher les ordonnances de sa grand-mère chaque semaine.'::text),
(376433,41826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ergenken her hafta büyükannesi için reçete ...'::text,'alırdı'::text,'alırdı'::text,'almaya alışkındı'::text,'Ergenken her hafta büyükannesi için reçete alırdı.'::text),
(376434,41826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tinédzserként minden héten ... a nagymamája receptjeit.'::text,'kiváltotta'::text,'kiváltotta'::text,'megszokta kiváltani'::text,'Tinédzserként minden héten kiváltotta a nagymamája receptjeit.'::text),
(361200,40134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er plant, vor der Deadline noch 50 weitere Zimmerpflanzen in den Raum zu ...'::text,'quetschen'::text,'quetschen'::text,'quetschen'::text,'Er plant, vor der Deadline noch 50 weitere Zimmerpflanzen in den Raum zu quetschen.'::text),
(361204,40134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він планує ... в кімнату ще 50 кімнатних рослин до дедлайну.'::text,'втиснути'::text,'втиснути'::text,'втиснути'::text,'Він планує втиснути в кімнату ще 50 кімнатних рослин до дедлайну.'::text),
(361203,40134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planea ... 50 plantas de interior más en la habitación antes de la fecha límite.'::text,'meter'::text,'meter'::text,'meter'::text,'Planea meter 50 plantas de interior más en la habitación antes de la fecha límite.'::text),
(361202,40134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il prévoit de ... 50 plantes d''intérieur de plus dans la pièce avant la deadline.'::text,'caser'::text,'caser'::text,'caser'::text,'Il prévoit de caser 50 plantes d''intérieur de plus dans la pièce avant la deadline.'::text),
(361205,40134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarihten önce odaya 50 ev bitkisi daha ... planlıyor.'::text,'sığdırmayı'::text,'sığdırmayı'::text,'sığdırmayı'::text,'Son tarihten önce odaya 50 ev bitkisi daha sığdırmayı planlıyor.'::text),
(361206,40134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt tervezi, hogy a határidő előtt még 50 szobanövényt ... a szobába.'::text,'bezsúfol'::text,'bezsúfol'::text,'bezsúfol'::text,'Azt tervezi, hogy a határidő előtt még 50 szobanövényt bezsúfol a szobába.'::text),
(361218,40136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Setzling braucht Wasser, und ... jede Zimmerpflanze im Raum.'::text,'genauso'::text,'genauso'::text,'nicht'::text,'Der Setzling braucht Wasser, und genauso jede Zimmerpflanze im Raum.'::text),
(361222,40136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Паросток потребує води, і ... кожна кімнатна рослина в кімнаті.'::text,'так само'::text,'так само'::text,'ні'::text,'Паросток потребує води, і так само кожна кімнатна рослина в кімнаті.'::text),
(361221,40136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El plantón necesita agua, y ... todas las plantas de interior de la habitación.'::text,'también'::text,'también'::text,'tampoco'::text,'El plantón necesita agua, y también todas las plantas de interior de la habitación.'::text),
(361220,40136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pousse a besoin d''eau, et ... chaque plante d''intérieur de la pièce.'::text,'c''est pareil pour'::text,'c''est pareil pour'::text,'pas plus que'::text,'La pousse a besoin d''eau, et c''est pareil pour chaque plante d''intérieur de la pièce.'::text),
(361223,40136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fidenin suya ihtiyacı var, odadaki her ev bitkisinin ...'::text,'de öyle'::text,'de öyle'::text,'de yok'::text,'Fidenin suya ihtiyacı var, odadaki her ev bitkisinin de öyle.'::text),
(361224,40136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A palántának víz kell, és ... minden szobanövénynek a szobában.'::text,'ugyanígy'::text,'ugyanígy'::text,'sem'::text,'A palántának víz kell, és ugyanígy minden szobanövénynek a szobában.'::text),
(361227,40137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... jahrelang Zimmerpflanzen gezogen, bevor dieser Raum wie ein Dschungel aussah, Respekt.'::text,'hattest'::text,'hast'::text,'wurdest'::text,'Du hattest jahrelang Zimmerpflanzen gezogen, bevor dieser Raum wie ein Dschungel aussah, Respekt.'::text),
(361231,40137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти роками ... кімнатні рослини, поки ця кімната не стала схожа на джунглі, респект.'::text,'вирощував'::text,'вирощуєш'::text,'був вирощений'::text,'Ти роками вирощував кімнатні рослини, поки ця кімната не стала схожа на джунглі, респект.'::text),
(361230,40137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... plantas de interior durante años antes de que esta habitación pareciera una jungla, respeto.'::text,'Habías estado cultivando'::text,'Has estado cultivando'::text,'Fuiste cultivado'::text,'Habías estado cultivando plantas de interior durante años antes de que esta habitación pareciera una jungla, respeto.'::text),
(361229,40137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des plantes d''intérieur pendant des années avant que cette pièce ressemble à une jungle, respect.'::text,'avais cultivé'::text,'as cultivé'::text,'as été cultivé'::text,'Tu avais cultivé des plantes d''intérieur pendant des années avant que cette pièce ressemble à une jungle, respect.'::text),
(361232,40137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu oda ormana dönmeden önce yıllarca ev bitkisi ..., saygı.'::text,'yetiştirmiştin'::text,'yetiştiriyorsun'::text,'yetiştirildin'::text,'Bu oda ormana dönmeden önce yıllarca ev bitkisi yetiştirmiştin, saygı.'::text),
(361233,40137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évekig ... szobanövényeket, mielőtt ez a szoba dzsungelnek nézett ki, le a kalappal.'::text,'nevelgettél'::text,'nevelgetsz'::text,'nevelve lettél'::text,'Évekig nevelgettél szobanövényeket, mielőtt ez a szoba dzsungelnek nézett ki, le a kalappal.'::text),
(361236,40138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum nächsten Frühling ... du aus diesem Setzling eine große Zimmerpflanze gemacht haben, ehrlich.'::text,'wirst'::text,'wirst'::text,'machst'::text,'Bis zum nächsten Frühling wirst du aus diesem Setzling eine große Zimmerpflanze gemacht haben, ehrlich.'::text),
(361240,40138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступної весни ти ... з цього паростка велику кімнатну рослину, чесно.'::text,'виростиш'::text,'вирощуватимеш'::text,'вирощуєш'::text,'До наступної весни ти виростиш з цього паростка велику кімнатну рослину, чесно.'::text),
(361239,40138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la próxima primavera, ... este plantón en una gran planta de interior, en serio.'::text,'habrás convertido'::text,'convertirás'::text,'estás convirtiendo'::text,'Para la próxima primavera, habrás convertido este plantón en una gran planta de interior, en serio.'::text),
(361238,40138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le printemps prochain, tu ... cette pousse en grande plante d''intérieur, franchement.'::text,'auras transformé'::text,'transformeras'::text,'transformes'::text,'D''ici le printemps prochain, tu auras transformé cette pousse en grande plante d''intérieur, franchement.'::text),
(361241,40138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek bahara kadar bu fideyi büyük bir ev bitkisine ..., açıkçası.'::text,'dönüştürmüş olacaksın'::text,'dönüştüreceksin'::text,'dönüştürüyorsun'::text,'Gelecek bahara kadar bu fideyi büyük bir ev bitkisine dönüştürmüş olacaksın, açıkçası.'::text),
(361242,40138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő tavaszra ebből a palántából nagy szobanövényt ..., őszintén.'::text,'nevelsz'::text,'fogsz nevelni'::text,'nevelsz éppen'::text,'Jövő tavaszra ebből a palántából nagy szobanövényt nevelsz, őszintén.'::text),
(361245,40139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Juni ... er seit zehn Jahren Zimmerpflanzen in diesem Raum.'::text,'zieht'::text,'zieht'::text,'zieht'::text,'Im Juni zieht er seit zehn Jahren Zimmerpflanzen in diesem Raum.'::text),
(361249,40139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У червні він ... кімнатні рослини в цій кімнаті вже десять років.'::text,'вирощуватиме'::text,'вирощуватиме'::text,'виростить'::text,'У червні він вирощуватиме кімнатні рослини в цій кімнаті вже десять років.'::text),
(361248,40139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para junio, ... plantas de interior en esta habitación durante diez años.'::text,'habrá estado cultivando'::text,'estará cultivando'::text,'habrá cultivado'::text,'Para junio, habrá estado cultivando plantas de interior en esta habitación durante diez años.'::text),
(361247,40139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En juin, ça ... dix ans qu''il cultive des plantes d''intérieur dans cette pièce.'::text,'fera'::text,'fera'::text,'fera'::text,'En juin, ça fera dix ans qu''il cultive des plantes d''intérieur dans cette pièce.'::text),
(361250,40139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hazirana kadar bu odada on yıldır ev bitkisi ...'::text,'yetiştiriyor olacak'::text,'yetiştiriyor olacak'::text,'yetiştirmiş olacak'::text,'Hazirana kadar bu odada on yıldır ev bitkisi yetiştiriyor olacak.'::text),
(361251,40139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Júniusban lesz tíz éve, hogy ebben a szobában szobanövényeket ...'::text,'nevel'::text,'nevel'::text,'nevel'::text,'Júniusban lesz tíz éve, hogy ebben a szobában szobanövényeket nevel.'::text),
(361254,40140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er sie nicht gegossen, ... die neue Zimmerpflanze bis zum nächsten Morgen verwelkt.'::text,'wäre'::text,'wird'::text,'war'::text,'Hätte er sie nicht gegossen, wäre die neue Zimmerpflanze bis zum nächsten Morgen verwelkt.'::text),
(361258,40140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він її не полив, нова кімнатна рослина ... до ранку.'::text,'зів''яла б'::text,'зів''яне'::text,'зів''яла'::text,'Якби він її не полив, нова кімнатна рослина зів''яла б до ранку.'::text),
(361257,40140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no la hubiera regado, la nueva planta de interior ... para la mañana siguiente.'::text,'se habría marchitado'::text,'se marchitará'::text,'se marchitó'::text,'Si no la hubiera regado, la nueva planta de interior se habría marchitado para la mañana siguiente.'::text),
(361256,40140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne l''avait pas arrosée, la nouvelle plante d''intérieur ... avant le lendemain matin.'::text,'aurait fané'::text,'fanera'::text,'a fané'::text,'S''il ne l''avait pas arrosée, la nouvelle plante d''intérieur aurait fané avant le lendemain matin.'::text),
(361259,40140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu sulamasaydı, yeni ev bitkisi ertesi sabaha kadar ...'::text,'solardı'::text,'solacak'::text,'soldu'::text,'Onu sulamasaydı, yeni ev bitkisi ertesi sabaha kadar solardı.'::text),
(361260,40140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem öntözte volna meg, az új szobanövény másnap reggelre ...'::text,'elhervadt volna'::text,'elhervad'::text,'elhervadt'::text,'Ha nem öntözte volna meg, az új szobanövény másnap reggelre elhervadt volna.'::text),
(361263,40141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er nicht so viele Zimmerpflanzen gekauft, ... der Raum jetzt nicht so grün aus.'::text,'sähe'::text,'hätte ausgesehen'::text,'wird aussehen'::text,'Hätte er nicht so viele Zimmerpflanzen gekauft, sähe der Raum jetzt nicht so grün aus.'::text),
(361267,40141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не купив стільки кімнатних рослин, кімната ... зараз такою зеленою.'::text,'не була б'::text,'не була б'::text,'не буде'::text,'Якби він не купив стільки кімнатних рослин, кімната не була б зараз такою зеленою.'::text),
(361266,40141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera comprado tantas plantas de interior, la habitación no ... tan verde ahora.'::text,'se vería'::text,'se habría visto'::text,'se verá'::text,'Si no hubiera comprado tantas plantas de interior, la habitación no se vería tan verde ahora.'::text),
(361265,40141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas acheté autant de plantes d''intérieur, la pièce ... pas aussi verte maintenant.'::text,'ne serait'::text,'n''aurait'::text,'ne sera'::text,'S''il n''avait pas acheté autant de plantes d''intérieur, la pièce ne serait pas aussi verte maintenant.'::text),
(361268,40141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar çok ev bitkisi almasaydı, oda şimdi bu kadar yeşil ...'::text,'görünmezdi'::text,'görünmezdi'::text,'görünmeyecek'::text,'Bu kadar çok ev bitkisi almasaydı, oda şimdi bu kadar yeşil görünmezdi.'::text),
(361269,40141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem vett volna ennyi szobanövényt, a szoba most nem ... ilyen zöld.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem vett volna ennyi szobanövényt, a szoba most nem lenne ilyen zöld.'::text),
(361272,40142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass der Raum über hundert Zimmerpflanzen ...'::text,'enthält'::text,'enthaltend'::text,'enthalten wird'::text,'Man glaubt, dass der Raum über hundert Zimmerpflanzen enthält.'::text),
(361276,40142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що кімната ... понад сто кімнатних рослин.'::text,'містить'::text,'містячи'::text,'міститься'::text,'Вважається, що кімната містить понад сто кімнатних рослин.'::text),
(361275,40142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la habitación ... más de cien plantas de interior.'::text,'contiene'::text,'conteniendo'::text,'es contenida'::text,'Se cree que la habitación contiene más de cien plantas de interior.'::text),
(361274,40142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la pièce ... plus de cent plantes d''intérieur.'::text,'contient'::text,'contenant'::text,'est contenue'::text,'On pense que la pièce contient plus de cent plantes d''intérieur.'::text),
(361277,40142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odada yüzden fazla ev bitkisi ... düşünülüyor.'::text,'bulunduğu'::text,'bulunarak'::text,'bulundurulduğu'::text,'Odada yüzden fazla ev bitkisi bulunduğu düşünülüyor.'::text),
(361278,40142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy gondolják, hogy a szobában több mint száz szobanövény ...'::text,'van'::text,'lévén'::text,'tartalmazva van'::text,'Úgy gondolják, hogy a szobában több mint száz szobanövény van.'::text),
(361281,40143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat sich geweigert, auch nur eine Zimmerpflanze ..., und jetzt ist es lowkey ein Dschungel, Bro.'::text,'herzugeben'::text,'herzugeben'::text,'gab her'::text,'Er hat sich geweigert, auch nur eine Zimmerpflanze herzugeben, und jetzt ist es lowkey ein Dschungel, Bro.'::text),
(361285,40143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відмовився ... бодай одну кімнатну рослину, і тепер тут реально джунглі, бро.'::text,'віддати'::text,'віддати'::text,'віддав'::text,'Він відмовився віддати бодай одну кімнатну рослину, і тепер тут реально джунглі, бро.'::text),
(361284,40143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se negó a ... ni una sola planta de interior, y ahora es literalmente una jungla, bro.'::text,'regalar'::text,'regalar'::text,'regaló'::text,'Se negó a regalar ni una sola planta de interior, y ahora es literalmente una jungla, bro.'::text),
(361283,40143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a refusé de ... ne serait-ce qu''une plante d''intérieur, et maintenant c''est carrément une jungle, frère.'::text,'donner'::text,'donner'::text,'a donné'::text,'Il a refusé de donner ne serait-ce qu''une plante d''intérieur, et maintenant c''est carrément une jungle, frère.'::text),
(361286,40143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir ev bitkisini bile ... reddetti, şimdi resmen orman oldu, kanka.'::text,'vermeyi'::text,'vermeyi'::text,'verdi'::text,'Tek bir ev bitkisini bile vermeyi reddetti, şimdi resmen orman oldu, kanka.'::text),
(361287,40143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem volt hajlandó egyetlen szobanövényt sem ..., és most lényegében dzsungel, tesó.'::text,'elajándékozni'::text,'elajándékozni'::text,'elajándékozta'::text,'Nem volt hajlandó egyetlen szobanövényt sem elajándékozni, és most lényegében dzsungel, tesó.'::text),
(363477,40387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit fünf Minuten auf diesem Platz und schreit, als wäre es das Ende der Welt!'::text,'kniet'::text,'kniet'::text,'kniet'::text,'Er kniet seit fünf Minuten auf diesem Platz und schreit, als wäre es das Ende der Welt!'::text),
(363481,40387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на цьому полі вже п''ять хвилин і кричить, ніби кінець світу!'::text,'стоїть на колінах'::text,'стоїть на колінах'::text,'стоїть на колінах'::text,'Він стоїть на колінах на цьому полі вже п''ять хвилин і кричить, ніби кінець світу!'::text),
(363480,40387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... en este campo desde hace cinco minutos, gritando como si fuera el fin del mundo!'::text,'Ha estado arrodillado'::text,'Está arrodillado'::text,'Se arrodilla'::text,'¡Ha estado arrodillado en este campo desde hace cinco minutos, gritando como si fuera el fin del mundo!'::text),
(363479,40387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur ce terrain depuis cinq minutes, en hurlant comme si c''était la fin du monde !'::text,'est à genoux'::text,'est à genoux'::text,'s''agenouille'::text,'Il est à genoux sur ce terrain depuis cinq minutes, en hurlant comme si c''était la fin du monde !'::text),
(363482,40387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır bu sahada ... ve dünyanın sonu gelmiş gibi bağırıyor!'::text,'diz çökmüş durumda'::text,'diz çökmüş durumda'::text,'diz çöker'::text,'Beş dakikadır bu sahada diz çökmüş durumda ve dünyanın sonu gelmiş gibi bağırıyor!'::text),
(363483,40387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt perce ... ezen a pályán, és úgy üvölt, mintha itt lenne a világvége!'::text,'térdel'::text,'térdel'::text,'térdel'::text,'Már öt perce térdel ezen a pályán, és úgy üvölt, mintha itt lenne a világvége!'::text),
(363486,40388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... einen Spieler nach einem Tor so schnell auf dem Rasen knien sehen.'::text,'haben die Zuschauer'::text,'die Zuschauer haben'::text,'haben die Zuschauer'::text,'Selten haben die Zuschauer einen Spieler nach einem Tor so schnell auf dem Rasen knien sehen.'::text),
(363490,40388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... гравця, який так швидко стає на коліна на траві після голу.'::text,'бачили глядачі'::text,'глядачі бачили'::text,'бачили глядачі'::text,'Рідко бачили глядачі гравця, який так швидко стає на коліна на траві після голу.'::text),
(363489,40388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... a un jugador arrodillarse en el césped tan rápido tras un gol.'::text,'han visto los espectadores'::text,'los espectadores han visto'::text,'vieron los espectadores'::text,'Pocas veces han visto los espectadores a un jugador arrodillarse en el césped tan rápido tras un gol.'::text),
(363488,40388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement les spectateurs ... un joueur s''agenouiller sur la pelouse si vite après un but.'::text,'ont-ils vu'::text,'ont vu'::text,'ont-ils vu'::text,'Rarement les spectateurs ont-ils vu un joueur s''agenouiller sur la pelouse si vite après un but.'::text),
(363491,40388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seyirciler bir oyuncunun golden sonra çimlere bu kadar hızlı diz çöktüğünü nadiren ...'::text,'görmüştür'::text,'görmüştür'::text,'gördü'::text,'Seyirciler bir oyuncunun golden sonra çimlere bu kadar hızlı diz çöktüğünü nadiren görmüştür.'::text),
(363492,40388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... a nézők játékost, aki gól után ilyen gyorsan térdre esett a füvön.'::text,'láttak'::text,'láttak'::text,'láttak'::text,'Ritkán láttak a nézők játékost, aki gól után ilyen gyorsan térdre esett a füvön.'::text),
(363495,40389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer brachte die Spieler dazu, sich für das Teamfoto auf ein Knie zu ...'::text,'knien'::text,'knien'::text,'kniete'::text,'Der Trainer brachte die Spieler dazu, sich für das Teamfoto auf ein Knie zu knien.'::text),
(363499,40389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер змусив гравців ... на одне коліно для командного фото.'::text,'стати'::text,'стати'::text,'стали'::text,'Тренер змусив гравців стати на одне коліно для командного фото.'::text),
(363498,40389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenador hizo que los jugadores ... sobre una rodilla para la foto del equipo.'::text,'se arrodillaran'::text,'se arrodillaran'::text,'se arrodillaron'::text,'El entrenador hizo que los jugadores se arrodillaran sobre una rodilla para la foto del equipo.'::text),
(363497,40389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraîneur a demandé aux joueurs de ... sur un genou pour la photo d''équipe.'::text,'se mettre'::text,'se mettre'::text,'se sont mis'::text,'L''entraîneur a demandé aux joueurs de se mettre sur un genou pour la photo d''équipe.'::text),
(363500,40389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör takım fotoğrafı için oyuncuları tek dizinin üstüne ...'::text,'çöktürdü'::text,'çöktürdü'::text,'çöktüler'::text,'Antrenör takım fotoğrafı için oyuncuları tek dizinin üstüne çöktürdü.'::text),
(363501,40389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző rávette a játékosokat, hogy ... fél térdre a csapatfotóhoz.'::text,'ereszkedjenek'::text,'ereszkedjenek'::text,'ereszkedtek'::text,'Az edző rávette a játékosokat, hogy ereszkedjenek fél térdre a csapatfotóhoz.'::text),
(363513,40391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stürmer, ... Trikot die Nummer 10 trägt, kniet auf dem Rasen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Stürmer, dessen Trikot die Nummer 10 trägt, kniet auf dem Rasen.'::text),
(363517,40391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нападник, ... футболка має номер 10, стоїть на колінах на траві.'::text,'чия'::text,'який'::text,'котрий'::text,'Нападник, чия футболка має номер 10, стоїть на колінах на траві.'::text),
(363516,40391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El delantero, ... camiseta lleva el número 10, está arrodillado en el césped.'::text,'cuya'::text,'quien'::text,'el cual'::text,'El delantero, cuya camiseta lleva el número 10, está arrodillado en el césped.'::text),
(363515,40391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''attaquant, ... le maillot porte le numéro 10, est à genoux sur la pelouse.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''attaquant, dont le maillot porte le numéro 10, est à genoux sur la pelouse.'::text),
(363518,40391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forması 10 numara ... forvet çimlerde diz çökmüş.'::text,'olan'::text,'olan'::text,'olan'::text,'Forması 10 numara olan forvet çimlerde diz çökmüş.'::text),
(363519,40391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csatár, ... mezén a 10-es szám áll, térdel a füvön.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A csatár, akinek a mezén a 10-es szám áll, térdel a füvön.'::text),
(363522,40392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des harten Bodens kniet er sich zum Feiern auf den Platz.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des harten Bodens kniet er sich zum Feiern auf den Platz.'::text),
(363526,40392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... тверду землю, він стає на коліна на полі, щоб святкувати.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри тверду землю, він стає на коліна на полі, щоб святкувати.'::text),
(363525,40392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el suelo duro, se arrodilla en el campo para celebrarlo.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de el suelo duro, se arrodilla en el campo para celebrarlo.'::text),
(363524,40392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le sol dur, il s''agenouille sur le terrain pour fêter ça.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré le sol dur, il s''agenouille sur le terrain pour fêter ça.'::text),
(363527,40392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sert zemine ..., kutlamak için sahada diz çöküyor.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Sert zemine rağmen, kutlamak için sahada diz çöküyor.'::text),
(363528,40392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kemény talaj ... letérdel a pályán, hogy ünnepeljen.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A kemény talaj ellenére letérdel a pályán, hogy ünnepeljen.'::text),
(363531,40393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem Anpfiff wusste der Stürmer, dass er sich nach Erreichen seines Ziels von 2 Toren ...'::text,'hinknien würde'::text,'hinknien wird'::text,'hinkniete'::text,'Vor dem Anpfiff wusste der Stürmer, dass er sich nach Erreichen seines Ziels von 2 Toren hinknien würde.'::text),
(363535,40393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед стартовим свистком нападник знав, що ... на коліна, щойно виконає свою ціль у 2 голи.'::text,'стане'::text,'стане'::text,'стояв'::text,'Перед стартовим свистком нападник знав, що стане на коліна, щойно виконає свою ціль у 2 голи.'::text),
(363534,40393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del saque inicial, el delantero sabía que ... tras cumplir su objetivo de 2 goles.'::text,'se arrodillaría'::text,'se arrodillará'::text,'se estaba arrodillando'::text,'Antes del saque inicial, el delantero sabía que se arrodillaría tras cumplir su objetivo de 2 goles.'::text),
(363533,40393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le coup d''envoi, l''attaquant savait qu''il ... après avoir atteint son objectif de 2 buts.'::text,'s''agenouillerait'::text,'s''agenouillera'::text,'s''agenouillait'::text,'Avant le coup d''envoi, l''attaquant savait qu''il s''agenouillerait après avoir atteint son objectif de 2 buts.'::text),
(363536,40393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlama vuruşundan önce forvet, 2 gollük hedefine ulaşınca diz ... biliyordu.'::text,'çökeceğini'::text,'çökeceğini'::text,'çöktüğünü'::text,'Başlama vuruşundan önce forvet, 2 gollük hedefine ulaşınca diz çökeceğini biliyordu.'::text),
(363537,40393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezdőrúgás előtt a csatár tudta, hogy a 2 gólos célja teljesítése után ...'::text,'letérdel majd'::text,'le fog térdelni'::text,'térdelt'::text,'A kezdőrúgás előtt a csatár tudta, hogy a 2 gólos célja teljesítése után letérdel majd.'::text),
(363540,40394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Stürmer auf dem Rasen, während sein Mitspieler herüberläuft.'::text,'kniet'::text,'kniet'::text,'hat gekniet'::text,'Gerade kniet der Stürmer auf dem Rasen, während sein Mitspieler herüberläuft.'::text),
(363544,40394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз нападник ... на траві, поки до нього біжить партнер по команді.'::text,'стоїть на колінах'::text,'стоїть на колінах'::text,'став на коліна'::text,'Саме зараз нападник стоїть на колінах на траві, поки до нього біжить партнер по команді.'::text),
(363543,40394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el delantero ... en el césped mientras su compañero se acerca corriendo.'::text,'está arrodillado'::text,'se arrodilla'::text,'se ha arrodillado'::text,'Ahora mismo el delantero está arrodillado en el césped mientras su compañero se acerca corriendo.'::text),
(363542,40394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''attaquant ... sur la pelouse pendant que son coéquipier accourt.'::text,'est à genoux'::text,'s''agenouille'::text,'s''est agenouillé'::text,'En ce moment, l''attaquant est à genoux sur la pelouse pendant que son coéquipier accourt.'::text),
(363545,40394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda forvet çimlerde ..., takım arkadaşı ona doğru koşuyor.'::text,'diz çökmüş'::text,'diz çöker'::text,'diz çöktü'::text,'Şu anda forvet çimlerde diz çökmüş, takım arkadaşı ona doğru koşuyor.'::text),
(363546,40394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen most a csatár ... a füvön, miközben a csapattársa odafut.'::text,'térdel'::text,'térdel'::text,'letérdelt'::text,'Éppen most a csatár térdel a füvön, miközben a csapattársa odafut.'::text),
(363549,40395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler ... das Tor erzielt, bevor er niederkniete, eine im Fußball typischerweise beobachtete Jubelgeste.'::text,'hatte'::text,'hat'::text,'war'::text,'Der Spieler hatte das Tor erzielt, bevor er niederkniete, eine im Fußball typischerweise beobachtete Jubelgeste.'::text),
(363553,40395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець ... гол, перш ніж став на коліна, — святкування, яке типово спостерігається у футболі.'::text,'забив'::text,'забив'::text,'забивав'::text,'Гравець забив гол, перш ніж став на коліна, — святкування, яке типово спостерігається у футболі.'::text),
(363552,40395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador ... el gol antes de arrodillarse, una celebración típicamente observada en el fútbol.'::text,'había marcado'::text,'ha marcado'::text,'estaba marcando'::text,'El jugador había marcado el gol antes de arrodillarse, una celebración típicamente observada en el fútbol.'::text),
(363551,40395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur ... le but avant de s''agenouiller, une célébration typiquement observée dans le football.'::text,'avait marqué'::text,'a marqué'::text,'marquait'::text,'Le joueur avait marqué le but avant de s''agenouiller, une célébration typiquement observée dans le football.'::text),
(363554,40395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu diz çökmeden önce golü ..., futbolda tipik olarak gözlemlenen bir kutlama.'::text,'atmıştı'::text,'attı'::text,'atıyordu'::text,'Oyuncu diz çökmeden önce golü atmıştı, futbolda tipik olarak gözlemlenen bir kutlama.'::text),
(363555,40395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos ... a gólt, mielőtt letérdelt, ez a futballban jellemzően megfigyelhető ünneplés.'::text,'már berúgta'::text,'berúgta'::text,'rúgta éppen'::text,'A játékos már berúgta a gólt, mielőtt letérdelt, ez a futballban jellemzően megfigyelhető ünneplés.'::text),
(363558,40396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Schlusspfiff ... er sich zehnmal auf diesen Rasen gekniet haben! Seine Knie werden zerstört sein!'::text,'wird'::text,'wird'::text,'kniet'::text,'Bis zum Schlusspfiff wird er sich zehnmal auf diesen Rasen gekniet haben! Seine Knie werden zerstört sein!'::text),
(363562,40396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До фінального свистка він ... на цю траву десять разів! Його коліна будуть знищені!'::text,'стане на коліна'::text,'ставатиме на коліна'::text,'стає на коліна'::text,'До фінального свистка він стане на коліна на цю траву десять разів! Його коліна будуть знищені!'::text),
(363561,40396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el pitido final, ... diez veces en este césped! ¡Sus rodillas quedarán destrozadas!'::text,'se habrá arrodillado'::text,'se arrodillará'::text,'se arrodilla'::text,'¡Para el pitido final, se habrá arrodillado diez veces en este césped! ¡Sus rodillas quedarán destrozadas!'::text),
(363560,40396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coup de sifflet final, il ... dix fois sur cette pelouse ! Ses genoux seront détruits !'::text,'se sera agenouillé'::text,'s''agenouillera'::text,'s''agenouille'::text,'D''ici le coup de sifflet final, il se sera agenouillé dix fois sur cette pelouse ! Ses genoux seront détruits !'::text),
(363563,40396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son düdüğe kadar bu çimlere on kez diz ...! Dizleri mahvolacak!'::text,'çökmüş olacak'::text,'çökecek'::text,'çöküyor'::text,'Son düdüğe kadar bu çimlere on kez diz çökmüş olacak! Dizleri mahvolacak!'::text),
(363564,40396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lefújásig tízszer ... ezen a füvön! A térde tönkre fog menni!'::text,'letérdel'::text,'fog letérdelni'::text,'térdel'::text,'A lefújásig tízszer letérdel ezen a füvön! A térde tönkre fog menni!'::text),
(370920,41214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... die ganze Nachbarschaft raus, als er anfing zu jonglieren.'::text,'kam'::text,'kam gerade'::text,'ist gekommen'::text,'Bestie, angeblich kam die ganze Nachbarschaft raus, als er anfing zu jonglieren.'::text),
(370924,41214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, уся околиця ... надвір тієї ж секунди, як він почав жонглювати.'::text,'вийшла'::text,'виходила'::text,'вийшла'::text,'Подруго, кажуть, уся околиця вийшла надвір тієї ж секунди, як він почав жонглювати.'::text),
(370923,41214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer todo el barrio ... en cuanto él empezó a hacer toques.'::text,'salió'::text,'estaba saliendo'::text,'ha salido'::text,'Amiga, al parecer todo el barrio salió en cuanto él empezó a hacer toques.'::text),
(370922,41214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment tout le quartier ... dès qu''il a commencé à jongler.'::text,'est sorti'::text,'sortait'::text,'est sorti'::text,'Ma belle, apparemment tout le quartier est sorti dès qu''il a commencé à jongler.'::text),
(370925,41214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya o top sektirmeye başladığı an bütün mahalle dışarı ...'::text,'çıkmış'::text,'çıkıyormuş'::text,'çıkmış'::text,'Kanka, güya o top sektirmeye başladığı an bütün mahalle dışarı çıkmış.'::text),
(370926,41214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az egész környék ... abban a pillanatban, hogy elkezdett dekázni.'::text,'kijött'::text,'éppen jött ki'::text,'kijött'::text,'Csajszi, állítólag az egész környék kijött abban a pillanatban, hogy elkezdett dekázni.'::text),
(370929,41215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, die Nachbarschaft ... diese Woche schon drei Straßenspiele gespielt.'::text,'hat'::text,'hat'::text,'spielt'::text,'Hör mal, ich hab gehört, die Nachbarschaft hat diese Woche schon drei Straßenspiele gespielt.'::text),
(370933,41215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що околиця цього тижня вже ... три вуличні матчі.'::text,'зіграла'::text,'грала'::text,'грає'::text,'Слухай, я чула, що околиця цього тижня вже зіграла три вуличні матчі.'::text),
(370932,41215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, he oído que el barrio ya ... tres partidos callejeros esta semana.'::text,'ha jugado'::text,'ha estado jugando'::text,'juega'::text,'Escucha, he oído que el barrio ya ha jugado tres partidos callejeros esta semana.'::text),
(370931,41215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que le quartier ... déjà trois matchs de rue cette semaine.'::text,'a joué'::text,'a joué'::text,'joue'::text,'Écoute, j''ai entendu que le quartier a joué déjà trois matchs de rue cette semaine.'::text),
(370934,41215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki mahalle bu hafta şimdiden üç sokak maçı ...'::text,'oynamış'::text,'oynuyormuş'::text,'oynar'::text,'Dinle, duydum ki mahalle bu hafta şimdiden üç sokak maçı oynamış.'::text),
(370935,41215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a környék ezen a héten már három utcai meccset ...'::text,'játszott'::text,'játszott'::text,'játszik'::text,'Figyelj, azt hallottam, hogy a környék ezen a héten már három utcai meccset játszott.'::text),
(370938,41216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Spiel anfing, ... die Nachbarschaft schon Shirts als Tore hingelegt.'::text,'hatte'::text,'hat'::text,'legt'::text,'Als das Spiel anfing, hatte die Nachbarschaft schon Shirts als Tore hingelegt.'::text),
(370942,41216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли матч почався, околиця вже ... футболки як ворота.'::text,'розклала'::text,'розклала'::text,'розкладає'::text,'Коли матч почався, околиця вже розклала футболки як ворота.'::text),
(370941,41216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó el partido, el barrio ya ... camisetas en el suelo como porterías.'::text,'había puesto'::text,'ha puesto'::text,'pone'::text,'Cuando empezó el partido, el barrio ya había puesto camisetas en el suelo como porterías.'::text),
(370940,41216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le match a commencé, le quartier ... des t-shirts par terre comme buts.'::text,'avait déjà posé'::text,'a déjà posé'::text,'pose déjà'::text,'Quand le match a commencé, le quartier avait déjà posé des t-shirts par terre comme buts.'::text),
(370943,41216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maç başladığında mahalle kale olarak tişörtleri çoktan yere ...'::text,'sermişti'::text,'serdi'::text,'serer'::text,'Maç başladığında mahalle kale olarak tişörtleri çoktan yere sermişti.'::text),
(370944,41216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a meccs elkezdődött, a környék már ... a pólókat kapunak.'::text,'lerakta'::text,'lerakta'::text,'lerakja'::text,'Mire a meccs elkezdődött, a környék már lerakta a pólókat kapunak.'::text),
(370947,41217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Ball ein Fenster einschlägt, ... die ganze Nachbarschaft davon.'::text,'erfährt'::text,'erführe'::text,'erfuhr'::text,'Wenn der Ball ein Fenster einschlägt, erfährt die ganze Nachbarschaft davon.'::text),
(370951,41217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо м''яч розіб''є вікно, уся околиця про це ...'::text,'дізнається'::text,'дізналася б'::text,'дізналася'::text,'Якщо м''яч розіб''є вікно, уся околиця про це дізнається.'::text),
(370950,41217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el balón rompe una ventana, todo el barrio se ...'::text,'enterará'::text,'enteraría'::text,'enteró'::text,'Si el balón rompe una ventana, todo el barrio se enterará.'::text),
(370949,41217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le ballon casse une fenêtre, tout le quartier ... au courant.'::text,'sera'::text,'serait'::text,'était'::text,'Si le ballon casse une fenêtre, tout le quartier sera au courant.'::text),
(370952,41217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Top bir camı kırarsa bütün mahalle bunu ...'::text,'duyacak'::text,'duyardı'::text,'duydu'::text,'Top bir camı kırarsa bütün mahalle bunu duyacak.'::text),
(370953,41217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a labda betör egy ablakot, az egész környék ... róla.'::text,'hallani fog'::text,'hallana'::text,'hallott'::text,'Ha a labda betör egy ablakot, az egész környék hallani fog róla.'::text),
(370956,41218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gäbe es auf der Straße keine Autos, ... die Nachbarschaft dort jeden Tag Fußball.'::text,'spielte'::text,'spielt'::text,'spielte'::text,'Gäbe es auf der Straße keine Autos, spielte die Nachbarschaft dort jeden Tag Fußball.'::text),
(370960,41218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на вулиці не було машин, околиця ... там у футбол щодня.'::text,'грала б'::text,'гратиме'::text,'грала'::text,'Якби на вулиці не було машин, околиця грала б там у футбол щодня.'::text),
(370959,41218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la calle no tuviera coches, el barrio ... al fútbol allí todos los días.'::text,'jugaría'::text,'jugará'::text,'jugó'::text,'Si la calle no tuviera coches, el barrio jugaría al fútbol allí todos los días.'::text),
(370958,41218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rue n''avait pas de voitures, le quartier ... au foot là-bas tous les jours.'::text,'jouerait'::text,'jouera'::text,'jouait'::text,'Si la rue n''avait pas de voitures, le quartier jouerait au foot là-bas tous les jours.'::text),
(370961,41218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokakta araba olmasa mahalle orada her gün futbol ...'::text,'oynardı'::text,'oynayacak'::text,'oynadı'::text,'Sokakta araba olmasa mahalle orada her gün futbol oynardı.'::text),
(370962,41218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lennének autók az utcán, a környék minden nap ... ott focit.'::text,'játszana'::text,'fog játszani'::text,'játszott'::text,'Ha nem lennének autók az utcán, a környék minden nap játszana ott focit.'::text),
(370965,41219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straße ... für 90 Minuten für den Verkehr gesperrt, wie die Stakeholder aus der Nachbarschaft vereinbart hatten.'::text,'wurde'::text,'sperrte'::text,'wird gerade'::text,'Die Straße wurde für 90 Minuten für den Verkehr gesperrt, wie die Stakeholder aus der Nachbarschaft vereinbart hatten.'::text),
(370969,41219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вулицю ... для руху на 90 хвилин, як домовилися стейкхолдери околиці.'::text,'перекрили'::text,'перекрила'::text,'перекриває'::text,'Вулицю перекрили для руху на 90 хвилин, як домовилися стейкхолдери околиці.'::text),
(370968,41219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calle ... al tráfico durante 90 minutos, como acordaron los stakeholders del barrio.'::text,'fue cortada'::text,'cortó'::text,'está cortando'::text,'La calle fue cortada al tráfico durante 90 minutos, como acordaron los stakeholders del barrio.'::text),
(370967,41219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rue ... à la circulation pendant 90 minutes, comme convenu par les parties prenantes du quartier.'::text,'a été fermée'::text,'a fermé'::text,'est en train de fermer'::text,'La rue a été fermée à la circulation pendant 90 minutes, comme convenu par les parties prenantes du quartier.'::text),
(370970,41219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mahalledeki paydaşların anlaştığı gibi sokak 90 dakika boyunca trafiğe ...'::text,'kapatıldı'::text,'kapattı'::text,'kapatıyor'::text,'Mahalledeki paydaşların anlaştığı gibi sokak 90 dakika boyunca trafiğe kapatıldı.'::text),
(370971,41219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcát 90 percre ... a forgalom elől, ahogy a környék érintettjei megállapodtak.'::text,'lezárták'::text,'lezárta'::text,'zárja le'::text,'Az utcát 90 percre lezárták a forgalom elől, ahogy a környék érintettjei megállapodtak.'::text),
(370974,41220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nachbarschaft ... ein Spiel auf der Straße, also wurde ein Spiel gespielt.'::text,'spielte'::text,'wurde gespielt'::text,'spielend'::text,'Die Nachbarschaft spielte ein Spiel auf der Straße, also wurde ein Spiel gespielt.'::text),
(370978,41220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Околиця ... матч на вулиці, тож матч був зіграний.'::text,'зіграла'::text,'була зіграна'::text,'граючи'::text,'Околиця зіграла матч на вулиці, тож матч був зіграний.'::text),
(370977,41220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barrio ... un partido en la calle, así que se jugó un partido.'::text,'jugó'::text,'fue jugado'::text,'jugando'::text,'El barrio jugó un partido en la calle, así que se jugó un partido.'::text),
(370976,41220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le quartier ... un match dans la rue, donc un match a été joué.'::text,'a joué'::text,'a été joué'::text,'jouant'::text,'Le quartier a joué un match dans la rue, donc un match a été joué.'::text),
(370979,41220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mahalle sokakta bir maç ..., yani bir maç oynandı.'::text,'oynadı'::text,'oynandı'::text,'oynama'::text,'Mahalle sokakta bir maç oynadı, yani bir maç oynandı.'::text),
(370980,41220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A környék ... egy meccset az utcán, szóval egy meccs le lett játszva.'::text,'játszott'::text,'le lett játszva'::text,'játszás'::text,'A környék játszott egy meccset az utcán, szóval egy meccs le lett játszva.'::text),
(370983,41221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Verhalten deutet darauf hin, dass sich die Nachbarschaft gut kennen ...'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Dieses Verhalten deutet darauf hin, dass sich die Nachbarschaft gut kennen muss.'::text),
(370987,41221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Така поведінка вказує на те, що жителі околиці ... добре знати одне одного.'::text,'мають'::text,'не можуть'::text,'повинні'::text,'Така поведінка вказує на те, що жителі околиці мають добре знати одне одного.'::text),
(370986,41221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este comportamiento indica que en el barrio ... conocerse bien.'::text,'deben de'::text,'no pueden'::text,'deberían'::text,'Este comportamiento indica que en el barrio deben de conocerse bien.'::text),
(370985,41221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce comportement indique que les gens du quartier ... bien se connaître.'::text,'doivent'::text,'ne peuvent pas'::text,'devraient'::text,'Ce comportement indique que les gens du quartier doivent bien se connaître.'::text),
(370988,41221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu davranış, mahalledekilerin birbirini iyi tanıyor ... gösteriyor.'::text,'olması gerektiğini'::text,'olamayacağını'::text,'olması gerektiğini'::text,'Bu davranış, mahalledekilerin birbirini iyi tanıyor olması gerektiğini gösteriyor.'::text),
(370989,41221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a viselkedés arra utal, hogy a környékbeliek ... jól ismerik egymást.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'Ez a viselkedés arra utal, hogy a környékbeliek biztosan jól ismerik egymást.'::text),
(370992,41222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist die Nachbarschaft, ... alle für Fußball alles stehen und liegen lassen! Absolut episch!'::text,'wo'::text,'die'::text,'deren'::text,'Das ist die Nachbarschaft, wo alle für Fußball alles stehen und liegen lassen! Absolut episch!'::text),
(370996,41222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це околиця, ... всі кидають усе заради футболу! Абсолютно епічно!'::text,'де'::text,'яка'::text,'чия'::text,'Це околиця, де всі кидають усе заради футболу! Абсолютно епічно!'::text),
(370995,41222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este es el barrio ... todos lo dejan todo por el fútbol! ¡Absolutamente épico!'::text,'donde'::text,'que'::text,'cuyo'::text,'¡Este es el barrio donde todos lo dejan todo por el fútbol! ¡Absolutamente épico!'::text),
(370994,41222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le quartier ... tout le monde lâche tout pour le foot ! Absolument épique !'::text,'où'::text,'que'::text,'dont'::text,'C''est le quartier où tout le monde lâche tout pour le foot ! Absolument épique !'::text),
(370997,41222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burası herkesin futbol için her şeyi ... mahalle! Kesinlikle efsane!'::text,'bıraktığı'::text,'bırakan'::text,'bırakanın'::text,'Burası herkesin futbol için her şeyi bıraktığı mahalle! Kesinlikle efsane!'::text),
(370998,41222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az a környék, ... mindenki mindent félbehagy a fociért! Abszolút epikus!'::text,'ahol'::text,'amely'::text,'amelynek'::text,'Ez az a környék, ahol mindenki mindent félbehagy a fociért! Abszolút epikus!'::text),
(341994,38000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den letzten Stecker einsteckt, ... der Monitor an. Ein echter Visionär, ganz klar.'::text,'geht'::text,'ginge'::text,'ging'::text,'Wenn er den letzten Stecker einsteckt, geht der Monitor an. Ein echter Visionär, ganz klar.'::text),
(341998,38000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він під''єднає останню вилку, ... монітор. Справжній візіонер, ясно.'::text,'увімкнеться'::text,'увімкнувся б'::text,'увімкнувся'::text,'Якщо він під''єднає останню вилку, увімкнеться монітор. Справжній візіонер, ясно.'::text),
(341997,38000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si conecta el último enchufe, ... el monitor. Un verdadero visionario, claramente.'::text,'se encenderá'::text,'se encendería'::text,'se encendió'::text,'Si conecta el último enchufe, se encenderá el monitor. Un verdadero visionario, claramente.'::text),
(341996,38000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il branche la dernière prise, l''écran ... en marche. Un vrai visionnaire, clairement.'::text,'se mettra'::text,'se mettrait'::text,'s''est mis'::text,'S''il branche la dernière prise, l''écran se mettra en marche. Un vrai visionnaire, clairement.'::text),
(341999,38000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son fişi takarsa monitör ..., gerçek bir vizyoner, belli ki.'::text,'açılacak'::text,'açılırdı'::text,'açıldı'::text,'Son fişi takarsa monitör açılacak, gerçek bir vizyoner, belli ki.'::text),
(342000,38000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha bedugja az utolsó csatlakozót, a monitor ... be. Igazi látnok, egyértelműen.'::text,'kapcsol'::text,'kapcsolna'::text,'kapcsolt'::text,'Ha bedugja az utolsó csatlakozót, a monitor kapcsol be. Igazi látnok, egyértelműen.'::text),
(342003,38001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Kabel bei eingeschaltetem Licht anschließen würde, ... er die richtigen Anschlüsse schneller.'::text,'fände'::text,'findet'::text,'findet'::text,'Wenn er die Kabel bei eingeschaltetem Licht anschließen würde, fände er die richtigen Anschlüsse schneller.'::text),
(342007,38001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він під''єднував кабелі при увімкненому світлі, він ... правильні порти швидше.'::text,'знайшов би'::text,'знайде'::text,'знаходить'::text,'Якби він під''єднував кабелі при увімкненому світлі, він знайшов би правильні порти швидше.'::text),
(342006,38001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si conectara los cables con la luz encendida, ... los puertos correctos más rápido.'::text,'encontraría'::text,'encontrará'::text,'encuentra'::text,'Si conectara los cables con la luz encendida, encontraría los puertos correctos más rápido.'::text),
(342005,38001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il branchait les câbles avec la lumière allumée, il ... les bons ports plus vite.'::text,'trouverait'::text,'trouvera'::text,'trouve'::text,'S''il branchait les câbles avec la lumière allumée, il trouverait les bons ports plus vite.'::text),
(342008,38001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kabloları ışık açıkken bağlasa doğru girişleri daha hızlı ...'::text,'bulurdu'::text,'bulacak'::text,'bulur'::text,'Kabloları ışık açıkken bağlasa doğru girişleri daha hızlı bulurdu.'::text),
(342009,38001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha villanyfénynél kötné be a kábeleket, gyorsabban ... a megfelelő portokat.'::text,'megtalálná'::text,'meg fogja találni'::text,'megtalálja'::text,'Ha villanyfénynél kötné be a kábeleket, gyorsabban megtalálná a megfelelő portokat.'::text),
(342012,38002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Kabel ... an die Rückseite des Monitors angeschlossen, bevor der Bildschirm aufleuchtete.'::text,'wurde'::text,'wird'::text,'war'::text,'Jedes Kabel wurde an die Rückseite des Monitors angeschlossen, bevor der Bildschirm aufleuchtete.'::text),
(342016,38002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен кабель ... до задньої панелі монітора, перш ніж засвітився екран.'::text,'був під''єднаний'::text,'під''єднаний'::text,'під''єднувався'::text,'Кожен кабель був під''єднаний до задньої панелі монітора, перш ніж засвітився екран.'::text),
(342015,38002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada cable ... a la parte trasera del monitor antes de que se encendiera la pantalla.'::text,'fue conectado'::text,'está conectado'::text,'estaba conectando'::text,'Cada cable fue conectado a la parte trasera del monitor antes de que se encendiera la pantalla.'::text),
(342014,38002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque câble ... à l''arrière du moniteur avant que l''écran s''allume.'::text,'a été branché'::text,'est branché'::text,'branchait'::text,'Chaque câble a été branché à l''arrière du moniteur avant que l''écran s''allume.'::text),
(342017,38002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekran yanmadan önce her kablo monitörün arkasına ...'::text,'bağlandı'::text,'bağlı'::text,'bağlanıyordu'::text,'Ekran yanmadan önce her kablo monitörün arkasına bağlandı.'::text),
(342018,38002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden kábelt ... a monitor hátuljához, mielőtt a képernyő felvillant.'::text,'bekötötték'::text,'be van kötve'::text,'éppen kötötték be'::text,'Minden kábelt bekötötték a monitor hátuljához, mielőtt a képernyő felvillant.'::text),
(342021,38003,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... er das Switch-Dock mit einem schwarzen Kabel an den Monitor an.'::text,'schloss'::text,'wurde angeschlossen'::text,'anschließend'::text,'Gestern Abend schloss er das Switch-Dock mit einem schwarzen Kabel an den Monitor an.'::text),
(342025,38003,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері він ... док Switch до монітора чорним кабелем.'::text,'під''єднав'::text,'був під''єднаний'::text,'під''єднання'::text,'Учора ввечері він під''єднав док Switch до монітора чорним кабелем.'::text),
(342024,38003,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche ... el dock de la Switch al monitor con un cable negro.'::text,'conectó'::text,'fue conectado'::text,'conectando'::text,'Anoche conectó el dock de la Switch al monitor con un cable negro.'::text),
(342023,38003,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, il ... le dock de la Switch à l''écran avec un câble noir.'::text,'a branché'::text,'a été branché'::text,'branchant'::text,'Hier soir, il a branché le dock de la Switch à l''écran avec un câble noir.'::text),
(342026,38003,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam Switch dock''unu siyah bir kabloyla monitöre ...'::text,'bağladı'::text,'bağlandı'::text,'bağlama'::text,'Dün akşam Switch dock''unu siyah bir kabloyla monitöre bağladı.'::text),
(342027,38003,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este egy fekete kábellel ... a Switch dokkolót a monitorhoz.'::text,'csatlakoztatta'::text,'csatlakoztatva lett'::text,'csatlakoztatás'::text,'Tegnap este egy fekete kábellel csatlakoztatta a Switch dokkolót a monitorhoz.'::text),
(342030,38004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bildschirm leuchtet sofort auf, also ... das Kabel richtig angeschlossen sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Der Bildschirm leuchtet sofort auf, also muss das Kabel richtig angeschlossen sein.'::text),
(342034,38004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екран одразу засвічується, тож кабель ... бути під''єднаний правильно.'::text,'має'::text,'не може'::text,'не повинен'::text,'Екран одразу засвічується, тож кабель має бути під''єднаний правильно.'::text),
(342033,38004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pantalla se enciende enseguida, así que el cable ... estar bien conectado.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'La pantalla se enciende enseguida, así que el cable debe de estar bien conectado.'::text),
(342032,38004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''écran s''allume tout de suite, donc le câble ... être bien branché.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'L''écran s''allume tout de suite, donc le câble doit être bien branché.'::text),
(342035,38004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekran hemen yanıyor, yani kablo doğru bağlanmış ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Ekran hemen yanıyor, yani kablo doğru bağlanmış olmalı.'::text),
(342036,38004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képernyő azonnal felvillan, szóval a kábel ... jól van bekötve.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg nem'::text,'A képernyő azonnal felvillan, szóval a kábel biztosan jól van bekötve.'::text),
(342039,38005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kabel, ... das Dock mit dem Monitor verbindet, ist typischerweise ein HDMI-Kabel.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Kabel, das das Dock mit dem Monitor verbindet, ist typischerweise ein HDMI-Kabel.'::text),
(342043,38005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кабель, ... з''єднує док із монітором, — це, як правило, кабель HDMI.'::text,'який'::text,'хто'::text,'чий'::text,'Кабель, який з''єднує док із монітором, — це, як правило, кабель HDMI.'::text),
(342042,38005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cable ... conecta el dock con el monitor suele ser un cable HDMI.'::text,'que'::text,'quien'::text,'cuyo'::text,'El cable que conecta el dock con el monitor suele ser un cable HDMI.'::text),
(342041,38005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le câble ... relie le dock à l''écran est généralement un câble HDMI.'::text,'qui'::text,'qui'::text,'dont'::text,'Le câble qui relie le dock à l''écran est généralement un câble HDMI.'::text),
(342044,38005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dock''u monitöre ... kablo genellikle bir HDMI kablosudur.'::text,'bağlayan'::text,'bağlayan'::text,'bağladığı'::text,'Dock''u monitöre bağlayan kablo genellikle bir HDMI kablosudur.'::text),
(342045,38005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kábel, ... a dokkolót a monitorhoz köti, jellemzően egy HDMI-kábel.'::text,'amely'::text,'aki'::text,'amelynek a'::text,'A kábel, amely a dokkolót a monitorhoz köti, jellemzően egy HDMI-kábel.'::text),
(342057,38007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... Kabel früher im Dunkeln ein, aber jetzt machst du das Licht an.'::text,'stecktest'::text,'stecktest gewohnheitsmäßig'::text,'stecktest'::text,'Ehrlich gesagt, du stecktest Kabel früher im Dunkeln ein, aber jetzt machst du das Licht an.'::text),
(342061,38007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, раніше ти ... кабелі в темряві, а тепер вмикаєш світло.'::text,'під''єднував'::text,'звик під''єднувати'::text,'під''єднував'::text,'Не брешу, раніше ти під''єднував кабелі в темряві, а тепер вмикаєш світло.'::text),
(342060,38007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... conectar cables a oscuras, pero ahora enciendes la luz.'::text,'solías'::text,'estás acostumbrado a'::text,'solías'::text,'No voy a mentir, solías conectar cables a oscuras, pero ahora enciendes la luz.'::text),
(342059,38007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... brancher les câbles dans le noir, mais maintenant tu allumes la lumière.'::text,'avais l''habitude de'::text,'as l''habitude de'::text,'avais l''habitude de'::text,'Sans mentir, tu avais l''habitude de brancher les câbles dans le noir, mais maintenant tu allumes la lumière.'::text),
(342062,38007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, eskiden kabloları karanlıkta ..., ama artık ışığı açıyorsun.'::text,'bağlardın'::text,'bağlamaya alışkınsın'::text,'bağlardın'::text,'Yalan yok, eskiden kabloları karanlıkta bağlardın, ama artık ışığı açıyorsun.'::text),
(342063,38007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, régen sötétben ... a kábeleket, de most felkapcsolod a villanyt.'::text,'kötötted be'::text,'szoktad bekötni'::text,'kötötted be'::text,'Nem hazudok, régen sötétben kötötted be a kábeleket, de most felkapcsolod a villanyt.'::text),
(342066,38008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dir macht es offensichtlich Spaß, all die Kabel selbst ...'::text,'anzuschließen'::text,'anzuschließen'::text,'anschließen'::text,'Ehrlich, dir macht es offensichtlich Spaß, all die Kabel selbst anzuschließen.'::text),
(342070,38008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, тобі явно подобається ... всі ці кабелі самому.'::text,'під''єднувати'::text,'під''єднувати'::text,'під''єднувати'::text,'Чесно, тобі явно подобається під''єднувати всі ці кабелі самому.'::text),
(342069,38008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, está claro que te encanta ... todos esos cables tú mismo.'::text,'conectar'::text,'conectar'::text,'conectar'::text,'La verdad, está claro que te encanta conectar todos esos cables tú mismo.'::text),
(342068,38008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, t''adores clairement ... tous ces câbles toi-même.'::text,'brancher'::text,'brancher'::text,'brancher'::text,'Franchement, t''adores clairement brancher tous ces câbles toi-même.'::text),
(342071,38008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bütün o kabloları kendin ... bayağı seviyorsun.'::text,'bağlamayı'::text,'bağlamayı'::text,'bağla'::text,'Açıkçası, bütün o kabloları kendin bağlamayı bayağı seviyorsun.'::text),
(342072,38008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, láthatóan élvezed, hogy magad ... be az összes kábelt.'::text,'kötöd'::text,'kötöd'::text,'kötöd'::text,'Őszintén, láthatóan élvezed, hogy magad kötöd be az összes kábelt.'::text),
(342084,38010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Monitor aufleuchtete, ... er jedes Kabel angeschlossen. Ein kleines Wunder.'::text,'hatte'::text,'hat'::text,'war'::text,'Als der Monitor aufleuchtete, hatte er jedes Kabel angeschlossen. Ein kleines Wunder.'::text),
(342088,38010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки монітор засвітився, він уже ... кожен кабель. Маленьке диво.'::text,'під''єднав'::text,'під''єднав'::text,'під''єднував'::text,'Поки монітор засвітився, він уже під''єднав кожен кабель. Маленьке диво.'::text),
(342087,38010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se encendió el monitor, ya ... cada cable. Un pequeño milagro.'::text,'había conectado'::text,'conectó'::text,'estaba conectando'::text,'Para cuando se encendió el monitor, ya había conectado cada cable. Un pequeño milagro.'::text),
(342086,38010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''écran s''est allumé, il ... chaque câble. Un petit miracle.'::text,'avait branché'::text,'a branché'::text,'branchait'::text,'Quand l''écran s''est allumé, il avait branché chaque câble. Un petit miracle.'::text),
(342089,38010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Monitör yandığında her kabloyu çoktan ..., küçük bir mucize.'::text,'bağlamıştı'::text,'bağladı'::text,'bağlıyordu'::text,'Monitör yandığında her kabloyu çoktan bağlamıştı, küçük bir mucize.'::text),
(342090,38010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a monitor felvillant, ... minden kábelt. Egy kis csoda.'::text,'bekötötte'::text,'bekötötte'::text,'éppen kötötte be'::text,'Mire a monitor felvillant, bekötötte minden kábelt. Egy kis csoda.'::text),
(338772,37642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder über den Platz vor der Kathedrale.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Morgen um diese Zeit läuft er wieder über den Platz vor der Kathedrale.'::text),
(338776,37642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... площею перед собором.'::text,'йтиме'::text,'пройде'::text,'йде'::text,'Завтра в цей час він знову йтиме площею перед собором.'::text),
(338775,37642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez por la plaza frente a la catedral.'::text,'estará caminando'::text,'caminará'::text,'camina'::text,'Mañana a esta hora estará caminando otra vez por la plaza frente a la catedral.'::text),
(338774,37642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... de nouveau sur la place devant la cathédrale.'::text,'sera en train de marcher'::text,'marchera'::text,'marche'::text,'Demain à la même heure, il sera en train de marcher de nouveau sur la place devant la cathédrale.'::text),
(338777,37642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine katedralin önündeki meydanda ...'::text,'yürüyor olacak'::text,'yürüyecek'::text,'yürür'::text,'Yarın bu saatlerde yine katedralin önündeki meydanda yürüyor olacak.'::text),
(338778,37642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a téren a katedrális előtt.'::text,'sétálni fog'::text,'sétál'::text,'sétál'::text,'Holnap ilyenkor megint sétálni fog a téren a katedrális előtt.'::text),
(338781,37643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich ikonisch: nächste Woche um diese Zeit ... du in dieser orangen Jacke an der nächsten Kathedrale vorbei.'::text,'läufst'::text,'läufst'::text,'läufst'::text,'Ziemlich ikonisch: nächste Woche um diese Zeit läufst du in dieser orangen Jacke an der nächsten Kathedrale vorbei.'::text),
(338785,37643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить культово: наступного тижня в цей час ти ... повз ще один собор у цій помаранчевій куртці.'::text,'йтимеш'::text,'пройдеш'::text,'ідеш'::text,'Досить культово: наступного тижня в цей час ти йтимеш повз ще один собор у цій помаранчевій куртці.'::text),
(338784,37643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico: la semana que viene a esta hora ... junto a otra catedral con esa chaqueta naranja.'::text,'estarás paseando'::text,'pasearás'::text,'estás paseando'::text,'Bastante icónico: la semana que viene a esta hora estarás paseando junto a otra catedral con esa chaqueta naranja.'::text),
(338783,37643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt iconique : la semaine prochaine à la même heure, tu ... devant une autre cathédrale avec cette veste orange.'::text,'seras en train de passer'::text,'passeras'::text,'passes'::text,'Plutôt iconique : la semaine prochaine à la même heure, tu seras en train de passer devant une autre cathédrale avec cette veste orange.'::text),
(338786,37643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey ikonik: gelecek hafta bu saatlerde o turuncu montla başka bir katedralin önünden ...'::text,'geçiyor olacaksın'::text,'geçeceksin'::text,'geçiyorsun'::text,'Epey ikonik: gelecek hafta bu saatlerde o turuncu montla başka bir katedralin önünden geçiyor olacaksın.'::text),
(338787,37643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég ikonikus: jövő héten ilyenkor abban a narancssárga kabátban egy másik katedrális mellett ...'::text,'fogsz sétálni'::text,'sétálsz el'::text,'sétálsz'::text,'Elég ikonikus: jövő héten ilyenkor abban a narancssárga kabátban egy másik katedrális mellett fogsz sétálni.'::text),
(338790,37644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du an einer Kathedrale ..., fliegen die Tauben immer für dich auf.'::text,'vorbeigehst'::text,'vorbeigehen wirst'::text,'vorbeigingst'::text,'Ehrlich, wenn du an einer Kathedrale vorbeigehst, fliegen die Tauben immer für dich auf.'::text),
(338794,37644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли ти ... повз собор, голуби завжди злітають заради тебе.'::text,'проходиш'::text,'пройдеш'::text,'проходив'::text,'Чесно, коли ти проходиш повз собор, голуби завжди злітають заради тебе.'::text),
(338793,37644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si ... junto a una catedral, las palomas siempre alzan el vuelo por ti.'::text,'pasas'::text,'pasarás'::text,'pasaste'::text,'La verdad, si pasas junto a una catedral, las palomas siempre alzan el vuelo por ti.'::text),
(338792,37644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu ... devant une cathédrale, les pigeons s''envolent toujours pour toi.'::text,'passes'::text,'passeras'::text,'passais'::text,'Franchement, si tu passes devant une cathédrale, les pigeons s''envolent toujours pour toi.'::text),
(338795,37644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir katedralin önünden ..., güvercinler hep senin için havalanıyor.'::text,'geçersen'::text,'geçeceksen'::text,'geçtiysen'::text,'Açıkçası, bir katedralin önünden geçersen, güvercinler hep senin için havalanıyor.'::text),
(338796,37644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha ... egy katedrális mellett, a galambok mindig felszállnak érted.'::text,'elsétálsz'::text,'el fogsz sétálni'::text,'elsétáltál'::text,'Őszintén, ha elsétálsz egy katedrális mellett, a galambok mindig felszállnak érted.'::text),
(338799,37645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kathedrale hat ihn eindeutig mehr beeindruckt als die Dumplings, ...?'::text,'nicht wahr?'::text,'nicht wahr?'::text,'oder?'::text,'Die Kathedrale hat ihn eindeutig mehr beeindruckt als die Dumplings, nicht wahr?'::text),
(338803,37645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собор явно вразив його більше, ніж дамплінги, ...?'::text,'чи не так?'::text,'чи не так?'::text,'так?'::text,'Собор явно вразив його більше, ніж дамплінги, чи не так?'::text),
(338802,37645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La catedral claramente le impresionó más que los dumplings, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿no?'::text,'La catedral claramente le impresionó más que los dumplings, ¿verdad?'::text),
(338801,37645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cathédrale l''a clairement plus impressionné que les dumplings, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'hein ?'::text,'La cathédrale l''a clairement plus impressionné que les dumplings, n''est-ce pas ?'::text),
(338804,37645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katedral onu dumpling''den çok daha fazla etkiledi, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Katedral onu dumpling''den çok daha fazla etkiledi, değil mi?'::text),
(338805,37645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A katedrális egyértelműen jobban lenyűgözte, mint a dumpling, ...?'::text,'nem?'::text,'nem?'::text,'igaz?'::text,'A katedrális egyértelműen jobban lenyűgözte, mint a dumpling, nem?'::text),
(338826,37648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre er den ganzen Tag bei der Kathedrale geblieben, ... er diese Dumplings verpasst. Eine Tragödie!'::text,'hätte'::text,'würde'::text,'hat'::text,'Wäre er den ganzen Tag bei der Kathedrale geblieben, hätte er diese Dumplings verpasst. Eine Tragödie!'::text),
(338830,37648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він залишився біля собору на весь день, він ... ці дамплінги. Трагедія!'::text,'пропустив би'::text,'пропустив би'::text,'пропустив'::text,'Якби він залишився біля собору на весь день, він пропустив би ці дамплінги. Трагедія!'::text),
(338829,37648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubiera quedado todo el día en la catedral, ... esos dumplings. ¡Una tragedia!'::text,'se habría perdido'::text,'se perdería'::text,'se perdió'::text,'Si se hubiera quedado todo el día en la catedral, se habría perdido esos dumplings. ¡Una tragedia!'::text),
(338828,37648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il était resté toute la journée à la cathédrale, il ... ces dumplings. Une tragédie !'::text,'aurait raté'::text,'raterait'::text,'a raté'::text,'S''il était resté toute la journée à la cathédrale, il aurait raté ces dumplings. Une tragédie !'::text),
(338831,37648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün gün katedralde kalsaydı o dumpling''leri ..., tam bir trajedi!'::text,'kaçırmış olurdu'::text,'kaçırırdı'::text,'kaçırdı'::text,'Bütün gün katedralde kalsaydı o dumpling''leri kaçırmış olurdu, tam bir trajedi!'::text),
(338832,37648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egész nap a katedrálisnál maradt volna, ... azokról a dumplingokról. Tragédia!'::text,'lemaradt volna'::text,'lemaradna'::text,'lemaradt'::text,'Ha egész nap a katedrálisnál maradt volna, lemaradt volna azokról a dumplingokról. Tragédia!'::text),
(338835,37649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, die Dumplings mehr zu ... als die Kathedrale. Was für ein Verrat!'::text,'mögen'::text,'mögen'::text,'mochte'::text,'Er gab zu, die Dumplings mehr zu mögen als die Kathedrale. Was für ein Verrat!'::text),
(338839,37649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зізнався, що дамплінги йому ... більше, ніж собор. Яка зрада!'::text,'подобаються'::text,'подобаються'::text,'подобалися'::text,'Він зізнався, що дамплінги йому подобаються більше, ніж собор. Яка зрада!'::text),
(338838,37649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió que le ... más los dumplings que la catedral. ¡Qué traición!'::text,'gustaban'::text,'gustaban'::text,'gustaron'::text,'Admitió que le gustaban más los dumplings que la catedral. ¡Qué traición!'::text),
(338837,37649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a avoué ... les dumplings plus que la cathédrale. Quelle trahison !'::text,'aimer'::text,'aimer'::text,'a aimé'::text,'Il a avoué aimer les dumplings plus que la cathédrale. Quelle trahison !'::text),
(338840,37649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dumpling''i katedralden daha çok ... itiraf etti. Ne ihanet!'::text,'sevdiğini'::text,'sevmeyi'::text,'sevdi'::text,'Dumpling''i katedralden daha çok sevdiğini itiraf etti. Ne ihanet!'::text),
(338841,37649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallotta, hogy jobban ... a dumplingot, mint a katedrálist. Micsoda árulás!'::text,'szereti'::text,'szeretni'::text,'szerette'::text,'Bevallotta, hogy jobban szereti a dumplingot, mint a katedrálist. Micsoda árulás!'::text),
(338844,37650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... er in die Kathedrale reingehen sollen, aber er hat nur die Tauben gefilmt.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Bestie, angeblich hätte er in die Kathedrale reingehen sollen, aber er hat nur die Tauben gefilmt.'::text),
(338848,37650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... зайти в собор, але лише знімав голубів.'::text,'мав би'::text,'напевно мав'::text,'не міг'::text,'Подруго, кажуть, він мав би зайти в собор, але лише знімав голубів.'::text),
(338847,37650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... entrado en la catedral, pero solo grabó a las palomas.'::text,'debería haber'::text,'debe de haber'::text,'no puede haber'::text,'Amiga, al parecer debería haber entrado en la catedral, pero solo grabó a las palomas.'::text),
(338846,37650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... entrer dans la cathédrale, mais il a juste filmé les pigeons.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Ma belle, apparemment il aurait dû entrer dans la cathédrale, mais il a juste filmé les pigeons.'::text),
(338849,37650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya katedralin içine ..., ama o sadece güvercinleri çekti.'::text,'girmeliydi'::text,'girmiş olmalı'::text,'girmiş olamaz'::text,'Kanka, güya katedralin içine girmeliydi, ama o sadece güvercinleri çekti.'::text),
(338850,37650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag be ... mennie a katedrálisba, de csak a galambokat filmezte.'::text,'kellett volna'::text,'kellett'::text,'nem tudott'::text,'Csajszi, állítólag be kellett volna mennie a katedrálisba, de csak a galambokat filmezte.'::text),
(338853,37651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Abend lässt er sein Kathedralen-Video von einem Freund ..., bevor er es postet.'::text,'schneiden'::text,'schneiden'::text,'schneidend'::text,'Heute Abend lässt er sein Kathedralen-Video von einem Freund schneiden, bevor er es postet.'::text),
(338857,37651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні ввечері він попросить друга ... його відео із собором, перш ніж викласти.'::text,'змонтувати'::text,'змонтувати'::text,'монтуючи'::text,'Сьогодні ввечері він попросить друга змонтувати його відео із собором, перш ніж викласти.'::text),
(338856,37651,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta noche hará que un amigo le ... el vídeo de la catedral antes de publicarlo.'::text,'edite'::text,'edite'::text,'editando'::text,'Esta noche hará que un amigo le edite el vídeo de la catedral antes de publicarlo.'::text),
(338855,37651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce soir, il va faire ... sa vidéo de la cathédrale par un ami avant de la poster.'::text,'monter'::text,'monter'::text,'montant'::text,'Ce soir, il va faire monter sa vidéo de la cathédrale par un ami avant de la poster.'::text),
(338858,37651,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam katedral videosunu paylaşmadan önce bir arkadaşına ...'::text,'düzenletecek'::text,'düzenletecek'::text,'düzenleyerek'::text,'Bu akşam katedral videosunu paylaşmadan önce bir arkadaşına düzenletecek.'::text),
(338859,37651,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma este ... egy barátjával a katedrálisos videóját, mielőtt kiteszi.'::text,'megvágatja'::text,'megvágatja'::text,'vágva'::text,'Ma este megvágatja egy barátjával a katedrálisos videóját, mielőtt kiteszi.'::text),
(338862,37652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, er ... auf dieser Reise mehr Zeit für die Kathedrale.'::text,'hätte'::text,'hat'::text,'hätte'::text,'Er wünscht sich, er hätte auf dieser Reise mehr Zeit für die Kathedrale.'::text),
(338866,37652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб у нього ... більше часу на собор у цій подорожі.'::text,'було'::text,'є'::text,'було б'::text,'Він хотів би, щоб у нього було більше часу на собор у цій подорожі.'::text),
(338865,37652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... más tiempo para la catedral en este viaje.'::text,'tener'::text,'tener'::text,'tener'::text,'Desearía tener más tiempo para la catedral en este viaje.'::text),
(338864,37652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... plus de temps pour la cathédrale pendant ce voyage.'::text,'avoir'::text,'avoir'::text,'avoir'::text,'Il aimerait avoir plus de temps pour la cathédrale pendant ce voyage.'::text),
(338867,37652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bu gezide katedral için daha çok zamanı ... diye düşünüyor.'::text,'olsaydı'::text,'olsa'::text,'olacak olsa'::text,'Keşke bu gezide katedral için daha çok zamanı olsaydı diye düşünüyor.'::text),
(338868,37652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha több ideje ... a katedrálisra ezen az úton.'::text,'lenne'::text,'van'::text,'lenne'::text,'Azt szeretné, ha több ideje lenne a katedrálisra ezen az úton.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
